  ui_story_5037_50370101_167_dialog_content = "是喔，接下來歌爾蒂就拜託PlayerName製作人啦。",
  ui_story_5037_50370101_168_dialog_content = "歌爾蒂本來就已經很厲害了，還需要我做什麼？",
  ui_story_5037_50370101_169_dialog_content = "嘿嘿，雖然我的確是個小有名氣的偶像，但那也已經是過去式啦。",
  ui_story_5037_50370101_170_dialog_content = "現在我剛剛進入星願事務所，需要拿出成績來證明自己的實力。",
  ui_story_5037_50370101_171_dialog_content = "所以要拜託PlayerName的地方可是非常多呢~",
  ui_story_5037_50370101_172_dialog_content = "何況……",
  ui_story_5037_50370101_173_dialog_content = "沒想到這次涉老闆還給我們安排了競爭對手。",
  ui_story_5037_50370101_174_dialog_content = "我也是第一次遇到這種情況，有一點點緊張呢，欸嘿~",
  ui_story_5037_50370101_175_dialog_content = "我要是做不好，豈不是會影響歌爾蒂今後的職業生涯？",
  ui_story_5037_50370101_176_dialog_content = "突然覺得壓力好大啊。",
  ui_story_5037_50370101_177_dialog_content = "PlayerName製作人，不用擔心那麼遠的事情啦。",
  ui_story_5037_50370101_178_dialog_content = "最重要的是我們可以把眼前的事情做好。",
  ui_story_5037_50370101_179_dialog_content = "這樣就算到最後結果不如人意，我們也不會後悔~",
  ui_story_5037_50370101_180_dialog_content = "是……是這樣沒錯！",
  ui_story_5037_50370101_181_dialog_content = "本來這種為偶像加油打氣的事情是製作人該做的吧？",
  ui_story_5037_50370101_182_dialog_content = "怎麼反而是讓妳安慰了我呢？",
  ui_story_5037_50370101_183_dialog_content = "打起精神來！為了歌爾蒂今後的事業發展，我也要加油！",
  ui_story_5037_50370101_184_dialog_content = "不是為了歌爾蒂一個人的事業喔~",
  ui_story_5037_50370101_185_dialog_content = "欸？",
  ui_story_5037_50370101_186_dialog_content = "是為了我們共同的事業！",
  ui_story_5037_50370101_187_dialog_content = "啊……嗯，為了我們共同的事業！",
  ui_story_5037_50370101_188_dialog_content = "但我還是不清楚我們的目標是什麼，實際上我又該做些什麼？",
  ui_story_5037_50370101_189_dialog_content = "我們的目標是在規定的期限內，成功舉辦三場演唱會。",
  ui_story_5037_50370101_190_dialog_content = "而PlayerName能做的事嘛，可就多了！",
  ui_story_5037_50370101_191_dialog_content = "比如為我安排合適的訓練課程啦、為我挑選相襯的商業活動啦、製作我的歌曲啦很多很多。",
  ui_story_5037_50370101_192_dialog_content = "……聽上去都是我完全不懂的領域。",
  ui_story_5037_50370101_193_dialog_content = "只要動手去做，相信PlayerName製作人馬上就可以掌握竅門的！",
  ui_story_5037_50370101_194_dialog_content = "歌爾蒂之前的製作人呢？也許我可以向前輩請教一下經驗。",
  ui_story_5037_50370101_195_dialog_content = "嘻嘻，以前我的製作人就是我自己呀~",
  ui_story_5037_50370101_196_dialog_content = "欸？那妳不會很累嗎？",
  ui_story_5037_50370101_197_dialog_content = "以前的確是很辛苦，不過也都是過去的事情啦。",
  ui_story_5037_50370101_198_dialog_content = "現在，我可是擁有專屬製作人的偶像喔~",
  ui_story_5037_50370101_199_dialog_content = "嘿嘿……",
  ui_story_5037_50370101_200_dialog_content = "事不宜遲，我先帶著PlayerName親自體驗一下製作人要做哪些事情吧？",
  ui_story_5037_50370101_201_dialog_content = "好！",
  ui_story_5037_50370201_1_dialog_content = "演唱會馬上要開始了……",
  ui_story_5037_50370201_2_dialog_content = "可我竟然忘記帶專門為歌爾蒂準備的潤喉糖到後台！",
  ui_story_5037_50370201_3_dialog_content = "<color=#828282>嘩啦嘩啦——</color>",
  ui_story_5037_50370201_4_dialog_content = "呼~竟然是落在參考書堆裡了？",
  ui_story_5037_50370201_5_dialog_content = "幸好找到了，要趕快拿去給歌爾蒂試試！",
  ui_story_5037_50370201_6_dialog_content = "師父，快一點啦！",
  ui_story_5037_50370201_7_dialog_content = "欸，是菲雅的聲音？",
  ui_story_5037_50370201_8_dialog_content = "他們還沒有去後台準備嗎？",
  ui_story_5037_50370201_9_dialog_content = "演唱會就快開始了，你怎麼躲在這裡睡大覺啊？",
  ui_story_5037_50370201_10_dialog_content = "害菲雅找了好久！",
  ui_story_5037_50370201_11_dialog_content = "沒有充足的睡眠，怎麼有精神上台表演呢。",
  ui_story_5037_50370201_12_dialog_content = "就讓我再休息一下吧，我一會就過去。",
  ui_story_5037_50370201_13_dialog_content = "<size=45>師——父——！</size>",
  ui_story_5037_50370201_14_dialog_content = "都什麼時候了，你怎麼一點都不緊張？",
  ui_story_5037_50370201_15_dialog_content = "你知道嗎，歌爾蒂和PlayerName已經彩排過好幾次了。",
  ui_story_5037_50370201_16_dialog_content = "既然他們已經做過了，我們就算了吧~",
  ui_story_5037_50370201_17_dialog_content = "大家不用非要做一樣的事情浪費時間和精力嘛。",
  ui_story_5037_50370201_18_dialog_content = "呼~廢柴師父的廢柴宣言，又來了嗎？",
  ui_story_5037_50370201_19_dialog_content = "訓練的時候也就算了，現在我們一定要端正態度，認真應戰！",
  ui_story_5037_50370201_20_dialog_content = "如果輸給PlayerName他們，我們就賺不到額外的獎金了！",
  ui_story_5037_50370201_21_dialog_content = "有了！讓詩燁來代替我應該還來得及吧？",
  ui_story_5037_50370201_22_dialog_content = "不！可！以！",
  ui_story_5037_50370201_23_dialog_content = "我不明白，菲雅為什麼一定要為難師父我這把老骨頭呢？",
  ui_story_5037_50370201_24_dialog_content = "也不知道是誰當初吹牛說自己差點就出道成為偶像的？",
  ui_story_5037_50370201_25_dialog_content = "菲雅，師父什麼時候吹過牛，我說的可都是事實啊。",
  ui_story_5037_50370201_26_dialog_content = "那不是正好嗎？",
  ui_story_5037_50370201_27_dialog_content = "今天師父就可以正式出道了，不開心嗎？",
  ui_story_5037_50370201_28_dialog_content = "意思意思就行了，師父我又不是真的要成為偶像。",
  ui_story_5037_50370201_29_dialog_content = "如果要成為偶像，也是成為神奇動物訓練師的偶像！",
  ui_story_5037_50370201_30_dialog_content = "那就更應該努力賺錢，好照顧師父養在家的神奇動物了呀！",
  ui_story_5037_50370201_31_dialog_content = "拍攝實境秀的報酬只夠維持師父的生計。",
  ui_story_5037_50370201_32_dialog_content = "如果能贏過PlayerName他們，我們才有錢改善神奇動物們的生活。",
  ui_story_5037_50370201_33_dialog_content = "我之前明明也有認真接委託……",
  ui_story_5037_50370201_34_dialog_content = "師父接十年委託都沒有拍攝實境秀的報酬高。",
  ui_story_5037_50370201_35_dialog_content = "等到十年之後，可憐的神奇動物們恐怕早就被師父餓死了！",
  ui_story_5037_50370201_36_dialog_content = "這次我一定要看好師父，最後的獎金一定是我們的！",
  ui_story_5037_50370201_37_dialog_content = "（雖然沒有聽清楚菲雅在和維克說什麼……）",
  ui_story_5037_50370201_38_dialog_content = "（但是剛才的菲雅看上去好有氣勢啊，和她比起來我……）",
  ui_story_5037_50370201_39_dialog_content = "哇~這顆潤喉糖含在嘴裡好清涼呀。",
  ui_story_5037_50370201_40_dialog_content = "PlayerName製作人好貼心，竟然連這個都想到了！",
  ui_story_5037_50370201_41_dialog_content = "……",
  ui_story_5037_50370201_42_dialog_content = "PlayerName製作人，你在想什麼呢？",
  ui_story_5037_50370201_43_dialog_content = "沒什麼，妳能喜歡再好不過了。",
  ui_story_5037_50370201_44_dialog_content = "以後我可以多準備幾種口味，又好吃又能保護嗓子！",
  ui_story_5037_50370201_45_dialog_content = "哦唷，看來你們已經準備得差不多了？",
  ui_story_5037_50370201_46_dialog_content = "嗯！歌爾蒂一定會為涉老闆交上一份滿意的答卷喔~",
  ui_story_5037_50370201_47_dialog_content = "親愛的，我很喜歡妳的這份自信。那我就拭目以待囉。",
  ui_story_5037_50370201_48_dialog_content = "那個……涉女士！",
  ui_story_5037_50370201_49_dialog_content = "嗯？PlayerName製作人，有什麼問題嗎？",
  ui_story_5037_50370201_50_dialog_content = "等會維克和歌爾蒂會同台演出嗎？",
  ui_story_5037_50370201_51_dialog_content = "你在擔心什麼？",
  ui_story_5037_50370201_52_dialog_content = "啊，我……我只是想確認一下演出的流程！",
  ui_story_5037_50370201_53_dialog_content = "演出流程就按照你安排的進行即可。",
  ui_story_5037_50370201_54_dialog_content = "維克的演唱會地點不在這裡，而是在這座舞台旁邊的另一座舞台。",
  ui_story_5037_50370201_55_dialog_content = "待會將同時舉辦歌爾蒂和維克的演唱會。",
  ui_story_5037_50370201_56_dialog_content = "另一座舞台！？怪不得我一直沒有在後台看到維克。",
  ui_story_5037_50370201_57_dialog_content = "原來如此，在建造這個劇院之初，涉老闆就已經料想到今天了嗎？",
  ui_story_5037_50370201_58_dialog_content = "所以才會在劇院裡打造了兩座一模一樣的雙子舞台。",
  ui_story_5037_50370201_59_dialog_content = "欸，一模一樣的雙子舞台?",
  ui_story_5037_50370201_60_dialog_content = "親愛的，驚訝就對了喔，這可是我創造的得意作品呢。",
  ui_story_5037_50370201_61_dialog_content = "兩座舞台中間只隔著一條走廊。",
  ui_story_5037_50370201_62_dialog_content = "演出開始後，兩座舞台下方的觀眾可以根據自己喜好，在舞台之間自由流動。",
  ui_story_5037_50370201_63_dialog_content = "最終誰的舞台能留住更多的觀眾駐足，誰就是獲勝的一方。",
  ui_story_5037_50370201_64_dialog_content = "不只帶給觀眾前所未有的體驗，又能為我們的實境秀製造噱頭唷~",
  ui_story_5037_50370201_65_dialog_content = "莉莉卡，正式播出時，記得把我剛才那句話剪掉喔~",
  ui_story_5037_50370201_66_dialog_content = "沒問題~！",
  ui_story_5037_50370201_67_dialog_content = "（最近習慣了莉莉卡的跟拍，差點忘記莉莉卡一直跟在我們身邊了。）",
  ui_story_5037_50370201_68_dialog_content = "那麼，親愛的，祝你們好運了囉~",
  ui_story_5037_50370201_69_dialog_content = "呃，為什麼這種事沒有提前告訴我們一聲？",
  ui_story_5037_50370201_70_dialog_content = "這下我需要重新調整我們的演唱曲目，創造一些可以吸引觀眾的亮點才行！",
  ui_story_5037_50370201_71_dialog_content = "啊！我還沒有去檢查燈光和音響設備……",
  ui_story_5037_50370201_72_dialog_content = "PlayerName製作人，你剛才已經檢查過一遍了。",
  ui_story_5037_50370201_73_dialog_content = "欸，是、是嗎？",
  ui_story_5037_50370201_74_dialog_content = "哈哈……我這是怎麼了，好像突然忘記剛才都做過什麼事了。",
  ui_story_5037_50370201_75_dialog_content = "PlayerName製作人是不是在緊張呀？",
  ui_story_5037_50370201_76_dialog_content = "不用擔心啦，我們在之前的準備過程中已經充分努力過了！",
  ui_story_5037_50370201_77_dialog_content = "今天我們可以不去想結果如何……",
  ui_story_5037_50370201_78_dialog_content = "只要能順利地把平時準備好的表演內容，用快樂的情緒傳遞給觀眾，我們就算是贏了哦～",
  ui_story_5037_50370201_79_dialog_content = "對……對、對！歌爾蒂說得沒錯。",
  ui_story_5037_50370201_80_dialog_content = "只要把平時的實力展現給大家就好！",
  ui_story_5037_50370201_81_dialog_content = "演出倒數計時啦！還有<color=#793f76>五分鐘</color>！",
  ui_story_5037_50370201_82_dialog_content = "啊啊啊啊啊！",
  ui_story_5037_50370201_83_dialog_content = "不行不行不行！我好像還有很多事情沒有做啊！",
  ui_story_5037_50370201_84_dialog_content = "哈哈，放心啦。我們現在只需要靜靜等待開場就足夠啦～",
  ui_story_5037_50370201_85_dialog_content = "是……是嗎？",
  ui_story_5037_50370201_86_dialog_content = "對不起，我這麼緊張，會不會影響到歌爾蒂的情緒。",
  ui_story_5037_50370201_87_dialog_content = "果然，我沒能成為一名稱職的製作人。",
  ui_story_5037_50370201_88_dialog_content = "才沒有那回事呢！",
  ui_story_5037_50370201_89_dialog_content = "而且，凡事都有第一次嘛。",
  ui_story_5037_50370201_90_dialog_content = "PlayerName製作人現在的表現，比我第一次登台表演的時候要強上一萬倍啦。",
  ui_story_5037_50370201_91_dialog_content = "歌爾蒂第一次登台？",
  ui_story_5037_50370201_92_dialog_content = "是喔，那個時候沒有公司願意給我機會。",
  ui_story_5037_50370201_93_dialog_content = "我好不容易爭取到一次商業表演的機會。",
  ui_story_5037_50370201_94_dialog_content = "下面，有請歌爾蒂帶來一首歡快的歌曲！",
  ui_story_5037_50370201_95_dialog_content = "大……大家好！",
  ui_story_5037_50370201_96_dialog_content = "這是誰啊？",
  ui_story_5037_50370201_97_dialog_content = "完全沒見過。",
  ui_story_5037_50370201_98_dialog_content = "呃，算了。趁這個時候去趟洗手間好了。",
  ui_story_5037_50370201_99_dialog_content = "欸……",
  ui_story_5037_50370201_100_dialog_content = "（為什麼、為什麼好多觀眾都走了？）",
  ui_story_5037_50370201_101_dialog_content = "（剩下的觀眾，他們都在盯著我。）",
  ui_story_5037_50370201_102_dialog_content = "（說起來，我為什麼會站在這裡？）",
  ui_story_5037_50370201_103_dialog_content = "（我是來做什麼的……？）",
  ui_story_5037_50370201_104_dialog_content = "那女孩站在舞台上幹嘛呢，表演木頭人？",
  ui_story_5037_50370201_105_dialog_content = "不唱歌就下來吧！",
  ui_story_5037_50370201_106_dialog_content = "我、我……",
  ui_story_5037_50370201_107_dialog_content = "觀眾們竟然趕妳下台？",
  ui_story_5037_50370201_108_dialog_content = "抱歉，我是不是讓妳想起了傷心的往事？",
  ui_story_5037_50370201_109_dialog_content = "沒關係喔，我現在已經完全不覺得傷心啦～",
  ui_story_5037_50370201_110_dialog_content = "欸？",
  ui_story_5037_50370201_111_dialog_content = "萬事起頭難，那個時候我告訴自己……",
  ui_story_5037_50370201_112_dialog_content = "犯錯可以，但是永遠不能犯兩次相同的錯誤！",
  ui_story_5037_50370201_113_dialog_content = "所以當我第二次、第三次站上舞台的時候，就已經不會緊張到忘詞啦。",
  ui_story_5037_50370201_114_dialog_content = "如果我沒有克服第一次登台的恐懼，一直為這件事難過的話……",
  ui_story_5037_50370201_115_dialog_content = "也就不會有今天的歌爾蒂啦。",
  ui_story_5037_50370201_116_dialog_content = "好厲害！",
  ui_story_5037_50370201_117_dialog_content = "其實現在我也還是會有一點緊張的啦，嘿嘿～",
  ui_story_5037_50370201_118_dialog_content = "不過，適當的緊張也能讓人更容易集中注意力，發揮出更好的水準。",
  ui_story_5037_50370201_119_dialog_content = "完全沒有看出來歌爾蒂在緊張！",
  ui_story_5037_50370201_120_dialog_content = "唔，可能是因為PlayerName製作人太緊張了，反而顯得我很輕鬆了吧？",
  ui_story_5037_50370201_121_dialog_content = "嘻嘻，說這麼多，我只是想告訴PlayerName製作人……",
  ui_story_5037_50370201_122_dialog_content = "請相信歌爾蒂吧～",
  ui_story_5037_50370201_123_dialog_content = "歌爾蒂已經是身經百戰的職業偶像了喔。",
  ui_story_5037_50370201_124_dialog_content = "更何況，這次我的身邊還有一位優秀的製作人幫我選擇了合適的歌曲、服裝和道具。",
  ui_story_5037_50370201_125_dialog_content = "而且，我剛才還吃到最好吃的潤喉糖呢！",
  ui_story_5037_50370201_126_dialog_content = "所以，我一定不會讓製作人失望的！",
  ui_story_5037_50370201_127_dialog_content = "歌爾蒂……",
  ui_story_5037_50370201_128_dialog_content = "嗯！那我也不會讓歌爾蒂失望。",
  ui_story_5037_50370201_129_dialog_content = "距離演唱會開始還有十秒，倒數計時開始！",
  ui_story_5037_50370201_130_dialog_content = "十……九……八……七……",
  ui_story_5037_50370201_131_dialog_content = "PlayerName製作人，我要準備上台了！",
  ui_story_5037_50370201_132_dialog_content = "歌爾蒂，加油！",
  ui_story_5037_50370201_133_dialog_content = "加油！",
  ui_story_5037_50370301_1_dialog_content = "歌爾蒂放心飛，蒂蒂人永相隨！",
  ui_story_5037_50370301_2_dialog_content = "歌爾蒂！歌爾蒂！歌爾蒂！歌爾蒂！",
  ui_story_5037_50370301_3_dialog_content = "觀眾們好熱情啊！",
  ui_story_5037_50370301_4_dialog_content = "演唱會明明已經結束了，他們仍在台下喊著歌爾蒂的名字。",
  ui_story_5037_50370301_5_dialog_content = "PlayerName製作人，我回來啦～",
  ui_story_5037_50370301_6_dialog_content = "歌爾蒂，辛苦啦！",
  ui_story_5037_50370301_7_dialog_content = "欸，製作人你怎麼了？為什麼一副快要哭了的表情？",
  ui_story_5037_50370301_8_dialog_content = "成功了……我們成功了！",
  ui_story_5037_50370301_9_dialog_content = "剛才的演唱會效果出奇地好，所有觀眾的情緒都被妳的歌聲帶動。",
  ui_story_5037_50370301_10_dialog_content = "嗯，我在台上也能夠感覺到，自己好像和舞台融為了一體！",
  ui_story_5037_50370301_11_dialog_content = "妳唱慢歌的時候，好多人都因為妳的演唱感動落淚。",
  ui_story_5037_50370301_12_dialog_content = "後面唱快歌的時候，全場都在跟著節奏擺動。",
  ui_story_5037_50370301_13_dialog_content = "歌爾蒂，妳今天的表現真是太完美了！",
  ui_story_5037_50370301_14_dialog_content = "嘻嘻，這也多虧了PlayerName製作人呀。",
  ui_story_5037_50370301_15_dialog_content = "以前我從來沒有發現自己可以駕馭得了這些歌曲！",
  ui_story_5037_50370301_16_dialog_content = "搭配今天的燈光和舞台美術，才能達到這次這麼震撼的效果。",
  ui_story_5037_50370301_17_dialog_content = "別說是觀眾了，就連我也很享受這次的演出呢。",
  ui_story_5037_50370301_18_dialog_content = "PlayerName製作人根本就不像是一個初出茅廬的新手。",
  ui_story_5037_50370301_19_dialog_content = "而是一個能夠獨當一面的全能偶像製作人！",
  ui_story_5037_50370301_20_dialog_content = "嘿嘿，沒有那麼誇張了，我還有好多地方做得不夠好。",
  ui_story_5037_50370301_21_dialog_content = "開場前因為我的測量失誤，有個道具還差點搬不進來。",
  ui_story_5037_50370301_22_dialog_content = "還是歌爾蒂有經驗，才化解了當時的窘境。",
  ui_story_5037_50370301_23_dialog_content = "下次我的製作人先生一定不會再有同樣的失誤了，對不對呢？",
  ui_story_5037_50370301_24_dialog_content = "啊……嗯！",
  ui_story_5037_50370301_25_dialog_content = "哈哈哈～",
  ui_story_5037_50370301_26_dialog_content = "對了，涉女士說演出結束後，要在事務所宣布這次的演出結果。",
  ui_story_5037_50370301_27_dialog_content = "好呀，我們快過去吧。",
  ui_story_5037_50370301_28_dialog_content = "師父，你也真是的，剛才在台上根本就沒有認真表演嘛！",
  ui_story_5037_50370301_29_dialog_content = "不過，沒想到觀眾就喜歡師父懶洋洋的樣子。",
  ui_story_5037_50370301_30_dialog_content = "他們還以為這是台上的表演效果呢，哈哈哈。",
  ui_story_5037_50370301_31_dialog_content = "這樣看來，原來師父真的有一點點當偶像的天分嘛~",
  ui_story_5037_50370301_32_dialog_content = "我早就說囉，為師我曾經差點就出道了。",
  ui_story_5037_50370301_33_dialog_content = "為什麼以前沒有出道成功，今天就出道成功了呢？",
  ui_story_5037_50370301_34_dialog_content = "嗯？為什麼呢~",
  ui_story_5037_50370301_35_dialog_content = "因為有菲雅一直在監督師父努力訓練啦！",
  ui_story_5037_50370301_36_dialog_content = "維克和菲雅聊得好開心。",
  ui_story_5037_50370301_37_dialog_content = "看來他們的演唱會也辦得很成功呢。",
  ui_story_5037_50370301_38_dialog_content = "……",
  ui_story_5037_50370301_39_dialog_content = "不用愁眉苦臉的啦，無論是我還是維克，現在都是星願事務所的偶像。",
  ui_story_5037_50370301_40_dialog_content = "大家的出道演唱會都很成功，這可是件天大的好消息呀！",
  ui_story_5037_50370301_41_dialog_content = "嗯，歌爾蒂說得對！",
  ui_story_5037_50370301_42_dialog_content = "喔？看來大家都到齊了。",
  ui_story_5037_50370301_43_dialog_content = "大家辛苦了喔，我呢也就不廢話了。",
  ui_story_5037_50370301_44_dialog_content = "這次兩場演唱會對決的結果是……",
  ui_story_5037_50370301_45_dialog_content = "……",
  ui_story_5037_50370301_46_dialog_content = "是……？",
  ui_story_5037_50370301_47_dialog_content = "平手！",
  ui_story_5037_50370301_48_dialog_content = "欸？",
  ui_story_5037_50370301_49_dialog_content = "新人偶像初出茅廬就和現役偶像打了個平手。",
  ui_story_5037_50370301_50_dialog_content = "我們的實境秀真是充滿了未知和懸念呢。",
  ui_story_5037_50370301_51_dialog_content = "這下我應該不用擔心以後的收視情況了吧，哈哈哈哈。",
  ui_story_5037_50370301_52_dialog_content = "親愛的各位，容我提醒幾句喔。",
  ui_story_5037_50370301_53_dialog_content = "雖然在這次的演唱會中，支持兩位偶像的觀眾人數數量相當。",
  ui_story_5037_50370301_54_dialog_content = "但我們之後還有<color=#793f76>兩場</color>演唱會呢。",
  ui_story_5037_50370301_55_dialog_content = "最後你們要較量的是——三場演唱會過後的<color=#793f76>總支持人數</color>。",
  ui_story_5037_50370301_56_dialog_content = "所以無論你們覺得這次的結果如何……",
  ui_story_5037_50370301_57_dialog_content = "都要好好準備接下來的考核演唱會。",
  ui_story_5037_50370301_58_dialog_content = "能和歌爾蒂小姐打個平手，我也真是太厲害了！",
  ui_story_5037_50370301_59_dialog_content = "不過再這麼訓練下去，我的老骨頭真的要撐不住了，我能不能回家——",
  ui_story_5037_50370301_60_dialog_content = "哼！這種結果不就證明……",
  ui_story_5037_50370301_61_dialog_content = "如果剛才師父發揮全力，我們其實就能贏過歌爾蒂和PlayerName的嘛！",
  ui_story_5037_50370301_62_dialog_content = "這下又要重新來過了。",
  ui_story_5037_50370301_63_dialog_content = "下一次的考核演唱會，師父你就別再想著偷懶了！",
  ui_story_5037_50370301_64_dialog_content = "欸，菲雅，妳去哪裡？",
  ui_story_5037_50370301_65_dialog_content = "排練室，接著訓練！",
  ui_story_5037_50370301_66_dialog_content = "我的好徒弟，什麼時候才能讓為師休息一下啊？",
  ui_story_5037_50370301_67_dialog_content = "凱羅，把師父拖走！",
  ui_story_5037_50370301_68_dialog_content = "囉！",
  ui_story_5037_50370301_69_dialog_content = "凱羅，輕點、輕點啊……",
  ui_story_5037_50370301_70_dialog_content = "維克的成績，竟然這麼厲害？",
  ui_story_5037_50370301_71_dialog_content = "嗯~不愧是我看好的新人偶像，第一次開演唱會就這麼受觀眾歡迎。",
  ui_story_5037_50370301_72_dialog_content = "小菲雅擔任維克的製作人，也真是相當拼命呢。",
  ui_story_5037_50370301_73_dialog_content = "我聽人說，小菲雅每天都要親自盯著維克訓練到深夜。",
  ui_story_5037_50370301_74_dialog_content = "其實我也見到過幾次。",
  ui_story_5037_50370301_75_dialog_content = "維克要是敢在訓練時偷懶，菲雅就會讓凱羅咬維克的腳後跟！",
  ui_story_5037_50370301_76_dialog_content = "那隻叫做凱羅的神奇動物有這麼大的威力嗎？",
  ui_story_5037_50370301_77_dialog_content = "我是不是也該找一隻凱羅來咬咬自己的腳後跟了……",
  ui_story_5037_50370301_78_dialog_content = "這……這應該不用吧。",
  ui_story_5037_50370301_79_dialog_content = "歌爾蒂不用這種外力監督，就已經非常努力了！",
  ui_story_5037_50370301_80_dialog_content = "要被凱羅監督的人是我。",
  ui_story_5037_50370301_81_dialog_content = "一定是因為我還不夠努力，所以一名優秀偶像的支持人數才會被新人追上。",
  ui_story_5037_50370301_82_dialog_content = "PlayerName製作人，其實也不能這樣解釋啦。",
  ui_story_5037_50370301_83_dialog_content = "偶像的人氣高低，有時候是沒辦法解釋清楚的神祕學問。",
  ui_story_5037_50370301_84_dialog_content = "至少我很享受今天的舞台，也沒有留下任何遺憾，這就夠了！",
  ui_story_5037_50370301_85_dialog_content = "……謝謝妳。",
  ui_story_5037_50370301_86_dialog_content = "歌爾蒂雖然這樣安慰我，但是我不能這樣自我安慰！",
  ui_story_5037_50370301_87_dialog_content = "欸？",
  ui_story_5037_50370301_88_dialog_content = "我會繼續加油，更熟練地駕馭製作人的工作。",
  ui_story_5037_50370301_89_dialog_content = "提供歌爾蒂更好的行程安排和訓練計畫。",
  ui_story_5037_50370301_90_dialog_content = "然後和歌爾蒂一起，舉辦一場更讓人震撼的演唱會！",
  ui_story_5037_50370301_91_dialog_content = "……PlayerName。",
  ui_story_5037_50370301_92_dialog_content = "一場可不夠啊，我們還有兩場演唱會……還有未來的很多很多場！",
  ui_story_5037_50370301_93_dialog_content = "啊，對喔，那我改一下！",
  ui_story_5037_50370301_94_dialog_content = "我會和歌爾蒂一起，把接下來的演唱會舉辦得更加震撼人心！",
  ui_story_5037_50370301_95_dialog_content = "嗯！",
  ui_story_5037_50370301_96_dialog_content = "那接下來，也請多指教啦~",
  ui_story_5037_50370301_97_dialog_content = "出道演唱會親友團事後採訪，準備……",
  ui_story_5037_50370301_98_dialog_content = "開拍！",
  ui_story_5037_50370301_99_dialog_content = "滿分十分的話，妳會給這場演唱會打幾分？",
  ui_story_5037_50370301_100_dialog_content = "當然是滿分，十分啦~",
  ui_story_5037_50370301_101_dialog_content = "嗯，八分吧，還有進步的空間。",
  ui_story_5037_50370301_102_dialog_content = "他們兩個湊一組，能做出什麼名堂？",
  ui_story_5037_50370301_103_dialog_content = "嗯？對，我今天沒去看演唱會。",
  ui_story_5037_50370301_104_dialog_content = "妳說什麼，觀眾反響很好？",
  ui_story_5037_50370301_105_dialog_content = "對手的演唱會呢，會打幾分？",
  ui_story_5037_50370301_106_dialog_content = "唔……也是十分吧，畢竟菲雅和維克的努力我們也看在眼裡。",
  ui_story_5037_50370301_107_dialog_content = "也是八分，還有進步的空間。",
  ui_story_5037_50370301_108_dialog_content = "必須回答這個問題嗎？",
  ui_story_5037_50370301_109_dialog_content = "親友最近的變化？",
  ui_story_5037_50370301_110_dialog_content = "PlayerName的生活比以前規律了很多，早上也不會賴床了。",
  ui_story_5037_50370301_111_dialog_content = "他的領悟力比我想像中要高很多，很快就熟悉製作人該做的事情。",
  ui_story_5037_50370301_112_dialog_content = "看起來還是老樣子啊？",
  ui_story_5037_50370301_113_dialog_content = "出道演唱會親友團事後採訪，錄製完畢！",
  ui_story_5037_50370301_114_dialog_content = "什麼？PlayerName他們已經開始訓練了？",
  ui_story_5037_50370301_115_dialog_content = "啊，我要快點過去繼續跟拍了！",
  ui_story_5037_50370401_1_dialog_content = "製作人，這個有點大的道具應該搬到哪裡啊？",
  ui_story_5037_50370401_2_dialog_content = "麻煩搬到舞台中間去，切記要對準正中央。",
  ui_story_5037_50370401_3_dialog_content = "製作人，這邊的燈光強弱可以嗎？",
  ui_story_5037_50370401_4_dialog_content = "有點太刺眼了，麻煩把燈光再調弱一些吧。",
  ui_story_5037_50370401_5_dialog_content = "製作人！來這裡看看吧！",
  ui_story_5037_50370401_6_dialog_content = "製作人，這個問題怎麼辦啊？",
  ui_story_5037_50370401_7_dialog_content = "製作人！製作人！",
  ui_story_5037_50370401_8_dialog_content = "一個一個來，一個一個問啊……",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50370401_10_dialog_content = "呼，總算是告一段落了。",
  ui_story_5037_50370401_11_dialog_content = "辛苦啦。",
  ui_story_5037_50370401_12_dialog_content = "欸，歌爾蒂已經準備好了？",
  ui_story_5037_50370401_13_dialog_content = "一切就緒~",
  ui_story_5037_50370401_14_dialog_content = "老樣子？",
  ui_story_5037_50370401_15_dialog_content = "老樣子！",
  ui_story_5037_50370401_16_dialog_content = "給。",
  ui_story_5037_50370401_17_dialog_content = "謝啦。",
  ui_story_5037_50370401_18_dialog_content = "欸欸欸？什麼「老樣子」啊？你們說話也太簡略了吧？",
  ui_story_5037_50370401_19_dialog_content = "剛才PlayerName給了歌爾蒂一個什麼東西？我的鏡頭沒有拍到……",
  ui_story_5037_50370401_20_dialog_content = "啊，這是我們之間的默契啦。",
  ui_story_5037_50370401_21_dialog_content = "PlayerName製作人知道我喜歡吃薄荷味的潤喉糖，所以每次都帶在身上。",
  ui_story_5037_50370401_22_dialog_content = "剛才他又給了我一顆糖，就是這樣而已啦。",
  ui_story_5037_50370401_23_dialog_content = "你們兩個什麼時候開始變得這麼有默契了？",
  ui_story_5037_50370401_24_dialog_content = "唔，說起來就是這幾天的事情吧。",
  ui_story_5037_50370401_25_dialog_content = "在一起訓練的時間久了，大家不用說話，透過眼神就能明白彼此的意思了。",
  ui_story_5037_50370401_26_dialog_content = "好厲害……",
  ui_story_5037_50370401_27_dialog_content = "等等！",
  ui_story_5037_50370401_28_dialog_content = "你們不說話，我的實境秀要拍什麼東西呢？",
  ui_story_5037_50370401_29_dialog_content = "要不我去找PlayerName製作人說幾句話？",
  ui_story_5037_50370401_30_dialog_content = "可是那樣就太刻意了啦。",
  ui_story_5037_50370401_31_dialog_content = "欸，對了。",
  ui_story_5037_50370401_32_dialog_content = "我可以像當時採訪親友團一樣，加一段你們的採訪嘛！",
  ui_story_5037_50370401_33_dialog_content = "欸嘿，莉莉卡真是天才！",
  ui_story_5037_50370401_34_dialog_content = "採訪親友團？這是什麼時候的事？",
  ui_story_5037_50370401_35_dialog_content = "嘿嘿，等實境秀播出的時候你就知道啦~",
  ui_story_5037_50370401_36_dialog_content = "現在讓我們抽點時間做一個……嗯！演唱會的事前專訪吧！",
  ui_story_5037_50370401_37_dialog_content = "考核演唱會PlayerName組事前專訪，準備……",
  ui_story_5037_50370401_38_dialog_content = "開拍！",
  ui_story_5037_50370401_39_dialog_content = "考核演唱會和出道演唱會有什麼不同？",
  ui_story_5037_50370401_40_dialog_content = "我覺得出道演唱會，只是證明我可以作為星願事務所的偶像開始活動。",
  ui_story_5037_50370401_41_dialog_content = "打個比方的話，對我來說，出道演唱會就像是一張遊樂園的門票。",
  ui_story_5037_50370401_42_dialog_content = "但是歌爾蒂在遊樂園裡可以做什麼呢？",
  ui_story_5037_50370401_43_dialog_content = "這就需要我拿出好作品來證明自己了~",
  ui_story_5037_50370401_44_dialog_content = "雖說考核演唱會是事務所對我們的考驗，用來檢視我們節目開拍以來的學習成果。",
  ui_story_5037_50370401_45_dialog_content = "但是對我們而言，這更像是粉絲「蒂蒂人」對我們的考驗。",
  ui_story_5037_50370401_46_dialog_content = "沒錯，歌爾蒂想要向大家證明……",
  ui_story_5037_50370401_47_dialog_content = "無論我在哪裡，都沒有忘記自己的初心喔~",
  ui_story_5037_50370401_48_dialog_content = "準備演唱會時會感到壓力嗎？",
  ui_story_5037_50370401_49_dialog_content = "完全沒有壓力喔~",
  ui_story_5037_50370401_50_dialog_content = "開玩笑啦，其實當然會有壓力的。",
  ui_story_5037_50370401_51_dialog_content = "但我真的很感謝，我身邊的製作人為我分擔了很多工作。",
  ui_story_5037_50370401_52_dialog_content = "讓我更能專心訓練，其實我反而輕鬆了很多呢。",
  ui_story_5037_50370401_53_dialog_content = "至於訓練的成果如何……大家稍後在演唱會上就可以看到了喔~",
  ui_story_5037_50370401_54_dialog_content = "製作人會覺得辛苦嗎？",
  ui_story_5037_50370401_55_dialog_content = "老實說，在出道演唱會之前，我的確度過了一段非常煎熬的時期。",
  ui_story_5037_50370401_56_dialog_content = "在那次演唱會的準備工作中，我犯了很多錯誤。",
  ui_story_5037_50370401_57_dialog_content = "但是一回生、二回熟，這些日子以來，我已經熟悉了製作人的工作內容。",
  ui_story_5037_50370401_58_dialog_content = "絕對不會同樣的錯犯第二次。",
  ui_story_5037_50370401_59_dialog_content = "嗯，我可以證明喔~",
  ui_story_5037_50370401_60_dialog_content = "PlayerName現在已經是非常專業的製作人了。",
  ui_story_5037_50370401_61_dialog_content = "而且他最近每天都忙著工作，幾乎沒有闔眼的時候。",
  ui_story_5037_50370401_62_dialog_content = "為了籌辦這場演唱會，PlayerName製作人真的是辛苦啦！",
  ui_story_5037_50370401_63_dialog_content = "沒什麼的，都是我應該做的。",
  ui_story_5037_50370401_64_dialog_content = "能幫助歌爾蒂完成最華麗的舞台，讓「蒂蒂人」看到他們喜歡的演出，我覺得一切都值得了。",
  ui_story_5037_50370401_65_dialog_content = "所以現在我一點都不覺得辛苦！",
  ui_story_5037_50370401_66_dialog_content = "這次準備了什麼樣的節目，可以透露嗎？",
  ui_story_5037_50370401_67_dialog_content = "現在還是祕密喔。",
  ui_story_5037_50370401_68_dialog_content = "但絕對都是大家在之前的演唱會上前所未見的節目~",
  ui_story_5037_50370401_69_dialog_content = "其實可以和大家透露一下演唱會的主題。",
  ui_story_5037_50370401_70_dialog_content = "啊，是呢。",
  ui_story_5037_50370401_71_dialog_content = "PlayerName製作人為我的三場演唱會設計了不同的主題。",
  ui_story_5037_50370401_72_dialog_content = "出道演唱會的主題是<color=#793f76>「破土而出」</color>，不知道看過演出的觀眾們有沒有體會到呢？",
  ui_story_5037_50370401_73_dialog_content = "而這次演唱會的主題是<color=#793f76>「含苞待放」</color>！",
  ui_story_5037_50370401_74_dialog_content = "為了這個主題，歌爾蒂在製作人的幫助下，編排了全新的節目。",
  ui_story_5037_50370401_75_dialog_content = "絕對不會讓花錢看演唱會的觀眾們，看到重複的表演呢~",
  ui_story_5037_50370401_76_dialog_content = "我需要澄清，我只是做了些後勤工作，主要還是歌爾蒂的功勞。",
  ui_story_5037_50370401_77_dialog_content = "本來我想讓她翻唱一些曲目。",
  ui_story_5037_50370401_78_dialog_content = "但她專門為這場演唱會寫了好幾首原創歌曲。",
  ui_story_5037_50370401_79_dialog_content = "那也是因為，在訓練的時候突然有很多情緒湧現出來。",
  ui_story_5037_50370401_80_dialog_content = "因為自從開始決定做偶像以來，我一直都是孤身奮戰。",
  ui_story_5037_50370401_81_dialog_content = "如今不只有PlayerName製作人陪在身邊幫我……",
  ui_story_5037_50370401_82_dialog_content = "還有為了同一個目標而奮鬥的對手。",
  ui_story_5037_50370401_83_dialog_content = "不對！與其說是對手，我覺得維克更像是我在偶像之路上攜手前進的夥伴。",
  ui_story_5037_50370401_84_dialog_content = "這麼多新鮮的情緒使我有感而發，寫下了很多新歌。",
  ui_story_5037_50370401_85_dialog_content = "我在訓練的時候已經聽過很多遍了，但每一次聽到……",
  ui_story_5037_50370401_86_dialog_content = "都還是令我非常感動。",
  ui_story_5037_50370401_87_dialog_content = "相信這樣充滿誠意的節目，一定會讓大家滿意！",
  ui_story_5037_50370401_88_dialog_content = "聽說製作人每天都在外面發傳單，幫歌爾蒂爭取粉絲？",
  ui_story_5037_50370401_89_dialog_content = "咦？真的嗎？",
  ui_story_5037_50370401_90_dialog_content = "我是第一次聽說，PlayerName製作人從來都沒有告訴我！",
  ui_story_5037_50370401_91_dialog_content = "這是我應該做的，沒什麼。",
  ui_story_5037_50370401_92_dialog_content = "我想起來了！",
  ui_story_5037_50370401_93_dialog_content = "有好幾次，你說要出去吃飯或買零食……",
  ui_story_5037_50370401_94_dialog_content = "原來都去發傳單了嗎？",
  ui_story_5037_50370401_95_dialog_content = "嗯。抱歉，我之前只是不想讓歌爾蒂分心，才沒有告訴妳。",
  ui_story_5037_50370401_96_dialog_content = "雖然歌爾蒂總說結果不重要，只希望奮鬥的過程無怨無悔……",
  ui_story_5037_50370401_97_dialog_content = "但我還是想要幫歌爾蒂爭取更多的關注和喜愛。",
  ui_story_5037_50370401_98_dialog_content = "我覺得這樣才不會留下遺憾吧。",
  ui_story_5037_50370401_99_dialog_content = "PlayerName製作人……",
  ui_story_5037_50370401_100_dialog_content = "下次我也可以一起去啊！在街頭表演應該能吸引到更多人的注意呀~",
  ui_story_5037_50370401_101_dialog_content = "別忘了，我們可是同一個團隊的喔！",
  ui_story_5037_50370401_102_dialog_content = "團隊嗎……嗯，我們是同個團隊！",
  ui_story_5037_50370401_103_dialog_content = "對這場演唱會有信心嗎？",
  ui_story_5037_50370401_104_dialog_content = "PlayerName製作人，你對我有信心嗎？",
  ui_story_5037_50370401_105_dialog_content = "我看過歌爾蒂的訓練，沒有任何瑕疵，堪稱完美。",
  ui_story_5037_50370401_106_dialog_content = "今天只不過是換了個場地表演，我對歌爾蒂非常有信心！",
  ui_story_5037_50370401_107_dialog_content = "好巧呀，我也對PlayerName製作人很有信心喔~",
  ui_story_5037_50370401_108_dialog_content = "老樣子？",
  ui_story_5037_50370401_109_dialog_content = "老樣子！",
  ui_story_5037_50370401_110_dialog_content = "加油！加油！加油！",
  ui_story_5037_50370401_111_dialog_content = "製作人，這個道具該放哪裡啊？",
  ui_story_5037_50370401_112_dialog_content = "製作人在哪裡啊？",
  ui_story_5037_50370401_113_dialog_content = "製作人！製作人！",
  ui_story_5037_50370401_114_dialog_content = "啊……我、我先去處理問題了！",
  ui_story_5037_50370401_115_dialog_content = "呼～",
  ui_story_5037_50370401_116_dialog_content = "這場演唱會沒有PlayerName可真不行呢。",
  ui_story_5037_50370401_117_dialog_content = "我也要好好調整心態，準備上台啦~",
  ui_story_5037_50370501_1_dialog_content = "接下來，將向大家宣布這次考核演唱會的對決結果。",
  ui_story_5037_50370501_2_dialog_content = "這次的結果，真是超出了我的想像喔。",
  ui_story_5037_50370501_3_dialog_content = "（有什麼結果能夠超出涉女士的想像呢？）",
  ui_story_5037_50370501_4_dialog_content = "（難道是……維克贏了？）",
  ui_story_5037_50370501_5_dialog_content = "在對決中獲勝的一組，承受住出道演唱會所帶來的壓力，成功吸引了更多觀眾的目光。",
  ui_story_5037_50370501_6_dialog_content = "這歸功於偶像本人的刻苦訓練。",
  ui_story_5037_50370501_7_dialog_content = "當然，也仰賴製作人的用心相伴。",
  ui_story_5037_50370501_8_dialog_content = "（唔，刻苦訓練和用心相伴？這說的不就是師父和菲雅嗎？）",
  ui_story_5037_50370501_9_dialog_content = "（努力終有回報，師父終於贏過了歌爾蒂！？）",
  ui_story_5037_50370501_10_dialog_content = "對決的結果就是……",
  ui_story_5037_50370501_11_dialog_content = "……",
  ui_story_5037_50370501_12_dialog_content = "嘿嘿～",
  ui_story_5037_50370501_13_dialog_content = "<size=45>歌爾蒂和PlayerName組獲勝！</size>",
  ui_story_5037_50370501_14_dialog_content = "PlayerName製作人，你聽到了嗎？我們獲勝了！",
  ui_story_5037_50370501_15_dialog_content = "贏……贏了？",
  ui_story_5037_50370501_16_dialog_content = "欸？？？怎麼會這樣？",
  ui_story_5037_50370501_17_dialog_content = "終於離回家又更近了一步呢。",
  ui_story_5037_50370501_18_dialog_content = "雖然很殘酷，但對決的結果是：支持歌爾蒂的觀眾比支持維克的觀眾更多。",
  ui_story_5037_50370501_19_dialog_content = "可是師父這次的演唱會明明比上次的更成功啊，怎麼會是歌爾蒂獲勝？",
  ui_story_5037_50370501_20_dialog_content = "嗯，其實不會很難理解喔，畢竟歌爾蒂在這次演唱會的表現真的很不錯呢。",
  ui_story_5037_50370501_21_dialog_content = "不僅在歌曲的編舞方面展現新意，還在燈光和舞台設計上下足功夫。",
  ui_story_5037_50370501_22_dialog_content = "最重要的是，歌爾蒂這次的演唱會直接圈粉了很多觀眾。",
  ui_story_5037_50370501_23_dialog_content = "大家衝進浮空商會，把歌爾蒂的週邊商品搶購一空。",
  ui_story_5037_50370501_24_dialog_content = "甚至很多與歌爾蒂毫無關係的商品也都一起買走。",
  ui_story_5037_50370501_25_dialog_content = "藉由「蒂蒂人」的口耳相傳……",
  ui_story_5037_50370501_26_dialog_content = "「觀看歌爾蒂的演唱會」已經成為「來影鎮必做的的十件事」之一了。",
  ui_story_5037_50370501_27_dialog_content = "所有人都在期待星願事務所舉辦的下一場演唱會。",
  ui_story_5037_50370501_28_dialog_content = "你們有想到嗎？畢業演唱會的門票已經一票難求了喔。",
  ui_story_5037_50370501_29_dialog_content = "我終於可以不用再去求人買票了！？",
  ui_story_5037_50370501_30_dialog_content = "沒想到實境秀尚未播出，我對星願事務所的投資就能回本。",
  ui_story_5037_50370501_31_dialog_content = "接下來，你們也不需要再進行額外宣傳來吸引粉絲了。",
  ui_story_5037_50370501_32_dialog_content = "專心精進你們的舞台表演，以最好的狀態迎接最後的畢業演唱會吧！",
  ui_story_5037_50370501_33_dialog_content = "謝謝涉老闆。",
  ui_story_5037_50370501_34_dialog_content = "我們一定再接再厲，用更好的表演來回報您和粉絲的支持！",
  ui_story_5037_50370501_35_dialog_content = "維克，我似乎還未聽到你的回答？",
  ui_story_5037_50370501_36_dialog_content = "我要不然就算了？",
  ui_story_5037_50370501_37_dialog_content = "反正也輸了，老闆您就提前放我回家吧~",
  ui_story_5037_50370501_38_dialog_content = "我不信，我還是無法相信。",
  ui_story_5037_50370501_39_dialog_content = "這……這說不定是你們聯合起來欺負菲雅和師父的。",
  ui_story_5037_50370501_40_dialog_content = "涉老闆，妳說！",
  ui_story_5037_50370501_41_dialog_content = "這是不是你們安排好的實境秀劇本？",
  ui_story_5037_50370501_42_dialog_content = "實境秀劇本？",
  ui_story_5037_50370501_43_dialog_content = "菲雅，妳真是個天才啊。",
  ui_story_5037_50370501_44_dialog_content = "菲雅當然是天才！嘿嘿。",
  ui_story_5037_50370501_45_dialog_content = "……等等，為什麼突然這麼說？",
  ui_story_5037_50370501_46_dialog_content = "幫實境秀寫劇本，這種創意我一開始怎麼沒有想到呢？",
  ui_story_5037_50370501_47_dialog_content = "那樣我說不定能更快回本呢。",
  ui_story_5037_50370501_48_dialog_content = "但是菲雅製作人，這次對決的結果是千真萬確的。",
  ui_story_5037_50370501_49_dialog_content = "要是妳依然不認可，不妨看看攝影機裡的舞台重播。",
  ui_story_5037_50370501_50_dialog_content = "如果看過之後仍然覺得有問題，歡迎隨時來找我。",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50370501_52_dialog_content = "這是怎麼做到的？這麼驚豔的舞台效果是怎麼做到的！？",
  ui_story_5037_50370501_53_dialog_content = "歌爾蒂竟然可以做到一秒換裝！？",
  ui_story_5037_50370501_54_dialog_content = "而且還能突然出現在觀眾席中，再飛回舞台！？",
  ui_story_5037_50370501_55_dialog_content = "和歌爾蒂的演唱會相比，師父的演唱會果然差了不只一點。",
  ui_story_5037_50370501_56_dialog_content = "難怪之前師父都沒辦法出道呢。",
  ui_story_5037_50370501_57_dialog_content = "呃……咳咳。",
  ui_story_5037_50370501_58_dialog_content = "總算知道了吧？為師我就算再有天賦，也沒辦法和專業的偶像比嘛。",
  ui_story_5037_50370501_59_dialog_content = "現在認清事實也不遲，為師我這就去收拾行李！",
  ui_story_5037_50370501_60_dialog_content = "等一下！",
  ui_story_5037_50370501_61_dialog_content = "其實師父你不說，菲雅也明白。",
  ui_story_5037_50370501_62_dialog_content = "這次演唱會的效果不好，不是師父的錯。",
  ui_story_5037_50370501_63_dialog_content = "菲雅作為製作人，一直只顧著讓師父好好訓練，忽視了對節目內容的編排和舞台效果的掌控。",
  ui_story_5037_50370501_64_dialog_content = "我一直以為，演唱會的關鍵在於師父……",
  ui_story_5037_50370501_65_dialog_content = "直到剛才我看到了歌爾蒂的演唱會，才明白原來演唱會還能有那樣的設計！",
  ui_story_5037_50370501_66_dialog_content = "剛才師父的表演非常出色。",
  ui_story_5037_50370501_67_dialog_content = "是菲雅沒能給師父設計一場完美的舞台！",
  ui_story_5037_50370501_68_dialog_content = "能順利完成演唱會對我來說就已經很完美啦，別放心上，我們快回家……",
  ui_story_5037_50370501_69_dialog_content = "不可以，菲雅還不能回家！",
  ui_story_5037_50370501_70_dialog_content = "還有最後一場演唱會，我們還有機會扳回一城。",
  ui_story_5037_50370501_71_dialog_content = "這次，菲雅一定不會讓師父的偶像夢留下遺憾！",
  ui_story_5037_50370501_72_dialog_content = "啊……？",
  ui_story_5037_50370501_73_dialog_content = "我剛才也看了維克的演唱會重播。",
  ui_story_5037_50370501_74_dialog_content = "維克，你的表演已經達到了專業偶像的水準。",
  ui_story_5037_50370501_75_dialog_content = "只是其中幾首歌的舞蹈，確實沒有突顯出維克的魅力。",
  ui_story_5037_50370501_76_dialog_content = "欸，真的嗎真的嗎？是哪幾首歌？",
  ui_story_5037_50370501_77_dialog_content = "嗯，等一下我整理一份觀後感給菲雅看看吧。",
  ui_story_5037_50370501_78_dialog_content = "話說我最近新寫了一首慢歌，感覺很適合維克演唱呢。",
  ui_story_5037_50370501_79_dialog_content = "等我把資料整理好之後一起拿給你們喔~",
  ui_story_5037_50370501_80_dialog_content = "太好了！",
  ui_story_5037_50370501_81_dialog_content = "可是……可是真的能這樣嗎？",
  ui_story_5037_50370501_82_dialog_content = "明明是競爭對手，歌爾蒂為什麼願意幫我們？",
  ui_story_5037_50370501_83_dialog_content = "偶像是帶給人們希望和溫暖的職業。",
  ui_story_5037_50370501_84_dialog_content = "身為一名偶像，如果無法溫暖身邊的人，又怎麼說得上稱職呢？",
  ui_story_5037_50370501_85_dialog_content = "我記得歌爾蒂小姐在事前採訪中就曾經表示過……",
  ui_story_5037_50370501_86_dialog_content = "與其說是對手，我覺得維克更像是我在偶像之路上攜手前進的夥伴。",
  ui_story_5037_50370501_87_dialog_content = "閃亮……",
  ui_story_5037_50370501_88_dialog_content = "好閃亮啊！！！",
  ui_story_5037_50370501_89_dialog_content = "原來這才是偶像的真諦嗎？",
  ui_story_5037_50370501_90_dialog_content = "啊！？",
  ui_story_5037_50370501_91_dialog_content = "和歌爾蒂比起來，我讓師父在事前採訪說的話，會被當成笑話看的吧？",
  ui_story_5037_50370501_92_dialog_content = "（菲雅究竟在採訪裡說了什麼啊？）",
  ui_story_5037_50370501_93_dialog_content = "莉莉卡，可以刪掉我們之前進行的事前採訪，重新採訪一次嗎？",
  ui_story_5037_50370501_94_dialog_content = "恐怕不行吧。",
  ui_story_5037_50370501_95_dialog_content = "這可是實境秀呢！",
  ui_story_5037_50370501_96_dialog_content = "凱羅！過來一下~",
  ui_story_5037_50370501_97_dialog_content = "囉！",
  ui_story_5037_50370501_98_dialog_content = "妳……妳打算做什麼？",
  ui_story_5037_50370501_99_dialog_content = "就算妳放凱羅咬我腳後跟，我也不會答應的！",
  ui_story_5037_50370501_100_dialog_content = "唔，別跑呀！",
  ui_story_5037_50370501_101_dialog_content = "如果妳答應我，我可以讓凱羅陪妳玩呢！",
  ui_story_5037_50370501_102_dialog_content = "嗯？菲雅該不會是……把我給忘了吧？",
  ui_story_5037_50370501_103_dialog_content = "這下我總算能找個好地方大睡一覺了。",
  ui_story_5037_50370501_104_dialog_content = "各位，回見了~",
  ui_story_5037_50370501_105_dialog_content = "呼~PlayerName製作人，考核演唱會總算是平安無事地度過了呢。",
  ui_story_5037_50370501_106_dialog_content = "歌爾蒂，這段時間辛苦妳啦！",
  ui_story_5037_50370501_107_dialog_content = "今天這場演唱會的效果太棒了，這種成果已經稱得上是史上最棒的演唱會了吧？",
  ui_story_5037_50370501_108_dialog_content = "PlayerName製作人，不要這麼輕易就下定論嘛。",
  ui_story_5037_50370501_109_dialog_content = "不是還有畢業演唱會嗎？",
  ui_story_5037_50370501_110_dialog_content = "說的也是，最好看的演唱會永遠是下一場！",
  ui_story_5037_50370501_111_dialog_content = "哈哈哈，PlayerName製作人說出一句不得了的話呢。",
  ui_story_5037_50370501_112_dialog_content = "PlayerName製作人該不會已經想好，最後一場演唱會的主題了吧？",
  ui_story_5037_50370501_113_dialog_content = "哎呀！對，我得快點進行畢業演唱會的設計方案了。",
  ui_story_5037_50370501_114_dialog_content = "歌爾蒂不用管我，快回去好好休息吧！",
  ui_story_5037_50370501_115_dialog_content = "好哦~PlayerName製作人也要早點休息喔。",
  ui_story_5037_50370501_116_dialog_content = "棉花糖。",
  ui_story_5037_50370501_117_dialog_content = "汪！",
  ui_story_5037_50370501_118_dialog_content = "剛才的演唱會上，似乎有一個偷東西的小偷。",
  ui_story_5037_50370501_119_dialog_content = "你也發現了吧？",
  ui_story_5037_50370501_120_dialog_content = "汪汪！",
  ui_story_5037_50370501_121_dialog_content = "竟敢在我的演唱會做這種事……",
  ui_story_5037_50370501_122_dialog_content = "棉花糖，準備好了嗎？",
  ui_story_5037_50370501_123_dialog_content = "今晚我們也要速戰速決，貫徹正義！",
  ui_story_5037_50370501_124_dialog_content = "汪汪！",
  ui_story_5037_50370501_125_dialog_content = "考核演唱會親友團事後採訪，準備……",
  ui_story_5037_50370501_126_dialog_content = "開拍！",
  ui_story_5037_50370501_127_dialog_content = "滿分仍是十分，妳為這場演唱會打幾分？",
  ui_story_5037_50370501_128_dialog_content = "十二分！嗯！",
  ui_story_5037_50370501_129_dialog_content = "接近十分。",
  ui_story_5037_50370501_130_dialog_content = "嘖嘖嘖，竟然能看見那傢伙在舞台上唱歌跳舞……",
  ui_story_5037_50370501_131_dialog_content = "但我不想打分。",
  ui_story_5037_50370501_132_dialog_content = "嗯？為什麼？怕那兩個胡鬧的傢伙驕傲吧。",
  ui_story_5037_50370501_133_dialog_content = "覺得對手這次的演唱會如何呢？",
  ui_story_5037_50370501_134_dialog_content = "十分！",
  ui_story_5037_50370501_135_dialog_content = "已經很完美了，但是歌爾蒂的演唱會更能帶動氣氛。",
  ui_story_5037_50370501_136_dialog_content = "九分。",
  ui_story_5037_50370501_137_dialog_content = "我沒看，但應該比菲雅他們的差一些吧。",
  ui_story_5037_50370501_138_dialog_content = "有什麼想對親友說的嗎？",
  ui_story_5037_50370501_139_dialog_content = "PlayerName放心飛，空心粉永相隨~",
  ui_story_5037_50370501_140_dialog_content = "努力是不會騙人的。",
  ui_story_5037_50370501_141_dialog_content = "聽說最後有獎金？",
  ui_story_5037_50370501_142_dialog_content = "你們給我把獎金贏回來啊！",
  ui_story_5037_50370501_143_dialog_content = "要不然，哼哼……",
  ui_story_5037_50370501_144_dialog_content = "這位親友團的朋友，請不要用觸鬚纏繞攝影機啊！",
  ui_story_5037_50370601_1_dialog_content = "畢業演唱會PlayerName組事前專訪……",
  ui_story_5037_50370601_2_dialog_content = "開拍！",
  ui_story_5037_50370601_3_dialog_content = "畢業演唱會的主題是什麼？",
  ui_story_5037_50370601_4_dialog_content = "這次畢業演唱會的主題是「怒放青春」。",
  ui_story_5037_50370601_5_dialog_content = "也請大家不用擔心喔~",
  ui_story_5037_50370601_6_dialog_content = "雖然叫做畢業演唱會，但歌爾蒂並不是真的從星願事務所「畢業」了。",
  ui_story_5037_50370601_7_dialog_content = "沒錯。從「破土而出」、「含苞待放」到「怒放青春」……",
  ui_story_5037_50370601_8_dialog_content = "這三場演唱會是透過實境秀節目，向螢幕前的大家濃縮呈現了偶像的職業生涯。",
  ui_story_5037_50370601_9_dialog_content = "歌爾蒂在節目結束後，會繼續以偶像的身分在大家的面前活躍。",
  ui_story_5037_50370601_10_dialog_content = "是的喔，歌爾蒂會為大家帶來更棒的作品和舞台表演的！",
  ui_story_5037_50370601_11_dialog_content = "雖然到了那時，我很可能已不是歌爾蒂的製作人了。",
  ui_story_5037_50370601_12_dialog_content = "……",
  ui_story_5037_50370601_13_dialog_content = "哈哈~是的喔，想成為星願事務所的製作人，是非常難的一件事呢。",
  ui_story_5037_50370601_14_dialog_content = "要先向星願事務所投遞簡歷，再通過老闆的各種考核才行呢。",
  ui_story_5037_50370601_15_dialog_content = "就算是PlayerName這麼出色的製作人，果然也會有些擔心呢。",
  ui_story_5037_50370601_16_dialog_content = "如果不是因為拍攝實境秀，在高手雲集的影鎮，也許我根本沒有機會擔任製作人。",
  ui_story_5037_50370601_17_dialog_content = "節目結束後，可能就有更優秀的人出現，我也沒辦法成為真正的製作人了。",
  ui_story_5037_50370601_18_dialog_content = "但能夠陪伴歌爾蒂在節目中成長至今，我已經非常滿足了！",
  ui_story_5037_50370601_19_dialog_content = "PlayerName……",
  ui_story_5037_50370601_20_dialog_content = "你的催淚時刻也未免太早了啦！",
  ui_story_5037_50370601_21_dialog_content = "歌爾蒂有沒有為這次的演唱會創作新歌？",
  ui_story_5037_50370601_22_dialog_content = "當然有啦。",
  ui_story_5037_50370601_23_dialog_content = "聽到PlayerName為畢業演唱會制定的主題「怒放青春」後……",
  ui_story_5037_50370601_24_dialog_content = "我忍不住問自己：青春是什麼呢？",
  ui_story_5037_50370601_25_dialog_content = "隨即我的腦海裡就湧現出好多畫面。",
  ui_story_5037_50370601_26_dialog_content = "是無憂無慮在影鎮的街道上追逐嬉鬧？",
  ui_story_5037_50370601_27_dialog_content = "是睡眼惺忪地坐在教室裡聽老師講課？",
  ui_story_5037_50370601_28_dialog_content = "還是早早擔負生活重任，在職場中揮汗如雨？",
  ui_story_5037_50370601_29_dialog_content = "然後我回答自己，青春沒有固定的模樣。",
  ui_story_5037_50370601_30_dialog_content = "每一種青春都值得怒放~",
  ui_story_5037_50370601_31_dialog_content = "追隨這些畫面，我寫下了這次演唱會上將表演給大家的歌曲。",
  ui_story_5037_50370601_32_dialog_content = "PlayerName製作人覺得這次歌爾蒂創作的歌曲如何呢？",
  ui_story_5037_50370601_33_dialog_content = "歌爾蒂寫的歌從來沒有問題！",
  ui_story_5037_50370601_34_dialog_content = "這一次她為「怒放青春」畢業演唱會寫的歌更是值得一聽。",
  ui_story_5037_50370601_35_dialog_content = "尤其這當中，有一首講述「離別」的歌曲……",
  ui_story_5037_50370601_36_dialog_content = "還被涉女士拿去當作這次實境秀節目的片尾曲了。",
  ui_story_5037_50370601_37_dialog_content = "雖說人生時時有離別……",
  ui_story_5037_50370601_38_dialog_content = "我還是會繼續努力，活躍在大家的視線中，陪伴大家成長的。",
  ui_story_5037_50370601_39_dialog_content = "也請大家別忘了關注歌爾蒂的成長喲~",
  ui_story_5037_50370601_40_dialog_content = "歌爾蒂有什麼想對製作人說的話嗎？",
  ui_story_5037_50370601_41_dialog_content = "啊？演唱會開始前就要問這個嗎？",
  ui_story_5037_50370601_42_dialog_content = "沒關係啦。",
  ui_story_5037_50370601_43_dialog_content = "演唱會結束後，我還怕會說不出口呢，嘿嘿~",
  ui_story_5037_50370601_44_dialog_content = "欸？",
  ui_story_5037_50370601_45_dialog_content = "咳咳，想對製作人說的話是……",
  ui_story_5037_50370601_46_dialog_content = "感謝你這些日子以來，一直陪伴在我的身邊。",
  ui_story_5037_50370601_47_dialog_content = "說實話喔，我一直以來都是隻身一人在這個行業中闖蕩，並不習慣身邊有製作人。",
  ui_story_5037_50370601_48_dialog_content = "一開始，我是為了節目效果才同意由你當我的製作人。",
  ui_story_5037_50370601_49_dialog_content = "但這些日子以來，你真的從什麼都不懂的新手，變成了非常專業的製作人。",
  ui_story_5037_50370601_50_dialog_content = "不只替我安排行程、應付狗仔隊，還幫我設計演唱會的各種細節……",
  ui_story_5037_50370601_51_dialog_content = "讓我能專心地創作和排練。",
  ui_story_5037_50370601_52_dialog_content = "到了現在，我發現自己越來越離不開PlayerName製作人了。",
  ui_story_5037_50370601_53_dialog_content = "雖然，也許你以後不會再擔任製作人了，但我還是想對PlayerName說……",
  ui_story_5037_50370601_54_dialog_content = "你是我心目中最棒的製作人！",
  ui_story_5037_50370601_55_dialog_content = "——目前為止啦。",
  ui_story_5037_50370601_56_dialog_content = "歌爾蒂也只有過我這一個製作人啊？",
  ui_story_5037_50370601_57_dialog_content = "我還沒有說完呢~無論以後你去哪裡，做什麼，我都相信！",
  ui_story_5037_50370601_58_dialog_content = "你一定能在任何領域嶄露頭角的。",
  ui_story_5037_50370601_59_dialog_content = "到了那時的我……",
  ui_story_5037_50370601_60_dialog_content = "也會……",
  ui_story_5037_50370601_61_dialog_content = "歌爾蒂？",
  ui_story_5037_50370601_62_dialog_content = "咳咳……",
  ui_story_5037_50370601_63_dialog_content = "<size=30>莉莉卡，拜託把剛才的那段刪掉喔~我重新說！</size>",
  ui_story_5037_50370601_64_dialog_content = "無論以後你去哪裡，做什麼，我都相信！",
  ui_story_5037_50370601_65_dialog_content = "你一定能在任何領域嶄露頭角的。",
  ui_story_5037_50370601_66_dialog_content = "到了那個時候，我也會堅持走在自己的道路上，不辜負PlayerName的付出的~",
  ui_story_5037_50370601_67_dialog_content = "製作人有什麼想對歌爾蒂說的話嗎？",
  ui_story_5037_50370601_68_dialog_content = "我也想謝謝歌爾蒂。",
  ui_story_5037_50370601_69_dialog_content = "因為有妳的鼓勵，我才能做到很多我連想都不敢想的事情。",
  ui_story_5037_50370601_70_dialog_content = "歌爾蒂和我能夠在節目中一起走到今天，其實是因為歌爾蒂本身就已經很耀眼了！",
  ui_story_5037_50370601_71_dialog_content = "如果說我在這段日子裡有什麼進步和成長……",
  ui_story_5037_50370601_72_dialog_content = "那也只是歌爾蒂散發的光芒給我的加護！",
  ui_story_5037_50370601_73_dialog_content = "PlayerName，你自己就很耀眼呀？",
  ui_story_5037_50370601_74_dialog_content = "歌爾蒂，就算以後我不在妳的身邊……",
  ui_story_5037_50370601_75_dialog_content = "妳也永遠會是那名閃閃發光的完美偶像。",
  ui_story_5037_50370601_76_dialog_content = "妳會成為最厲害的偶像，成為艾斯特拉大陸的傳說！",
  ui_story_5037_50370601_77_dialog_content = "而我，也會永遠地祝福歌爾蒂。",
  ui_story_5037_50370601_78_dialog_content = "畢業演唱會PlayerName組事前專訪……",
  ui_story_5037_50370601_79_dialog_content = "拍攝結束！",
  ui_story_5037_50370601_80_dialog_content = "……",
  ui_story_5037_50370601_81_dialog_content = "……",
  ui_story_5037_50370601_82_dialog_content = "嗯？氣氛怎麼突然沉寂下來了？",
  ui_story_5037_50370601_83_dialog_content = "我是不是不應該問這些？",
  ui_story_5037_50370601_84_dialog_content = "這種採訪果然還是會影響實境秀成員的心情嗎？",
  ui_story_5037_50370601_85_dialog_content = "啊，不會因為這樣，影響待會歌爾蒂在演唱會中的表現吧？",
  ui_story_5037_50370601_86_dialog_content = "莉莉卡，放心啦。",
  ui_story_5037_50370601_87_dialog_content = "看~我一點都沒有受到影響呢！",
  ui_story_5037_50370601_88_dialog_content = "太好了！歌爾蒂的笑容，又回來了！",
  ui_story_5037_50370601_89_dialog_content = "PlayerName製作人~",
  ui_story_5037_50370601_90_dialog_content = "嗯，給。",
  ui_story_5037_50370601_91_dialog_content = "謝啦~",
  ui_story_5037_50370601_92_dialog_content = "欸欸欸，我又錯過了什麼？",
  ui_story_5037_50370601_93_dialog_content = "哈~啊~",
  ui_story_5037_50370601_94_dialog_content = "薄荷味的潤喉糖，還真是能讓人冷靜下來呢。",
  ui_story_5037_50370601_95_dialog_content = "請問歌爾蒂的演唱會該怎麼走啊？",
  ui_story_5037_50370601_96_dialog_content = "欸，觀眾怎麼跑到後台來了？",
  ui_story_5037_50370601_97_dialog_content = "大家可以沿著這條路直走，接著往左轉就到了喔~",
  ui_story_5037_50370601_98_dialog_content = "哇賽，太幸運了吧，這不就是歌爾蒂本尊嗎？",
  ui_story_5037_50370601_99_dialog_content = "欸，真的啊？歌爾蒂，可以幫我在衣服上簽名嗎！？",
  ui_story_5037_50370601_100_dialog_content = "我是從北境趕過來的啊！",
  ui_story_5037_50370601_101_dialog_content = "還有我！我是從紅油扳手過來的！",
  ui_story_5037_50370601_102_dialog_content = "我是從雲島過來的！",
  ui_story_5037_50370601_103_dialog_content = "我是從尤佛里亞過來的！",
  ui_story_5037_50370601_104_dialog_content = "各位觀眾朋友們、觀眾朋友們。",
  ui_story_5037_50370601_105_dialog_content = "演唱會結束後，歌爾蒂會親自騰出時間為大家簽名拍照的。",
  ui_story_5037_50370601_106_dialog_content = "大家可以先去演唱會現場稍作等候，演唱會馬上就開始啦。",
  ui_story_5037_50370601_107_dialog_content = "還有簽名拍照的時間！？",
  ui_story_5037_50370601_108_dialog_content = "喔，那我可得先過去了！",
  ui_story_5037_50370601_109_dialog_content = "快走啊，先到現場的人就能獲得歌爾蒂的簽名照！",
  ui_story_5037_50370601_110_dialog_content = "不用急啊，大家都有機會的！",
  ui_story_5037_50370601_111_dialog_content = "呼~他們跑得也太快了，好像誰都沒聽見我說了什麼。",
  ui_story_5037_50370601_112_dialog_content = "不過這次真的來了好多觀眾啊，而且似乎都是從各個不同的地方趕過來的。",
  ui_story_5037_50370601_113_dialog_content = "歌爾蒂的環艾斯特拉大陸巡迴演唱會，看起來很有希望嘛！",
  ui_story_5037_50370601_114_dialog_content = "嗯？歌爾蒂，妳怎麼了？",
  ui_story_5037_50370601_115_dialog_content = "PlayerName製作人，我好緊張。",
  ui_story_5037_50370601_116_dialog_content = "好像……好像又回到了第一次登上舞台時的感覺……",
  ui_story_5037_50370601_117_dialog_content = "歌爾蒂，妳看看台下的觀眾。",
  ui_story_5037_50370601_118_dialog_content = "他們都是因為喜歡妳，為了妳而來的！",
  ui_story_5037_50370601_119_dialog_content = "而妳，歌爾蒂，妳是值得受到大家喜愛的。",
  ui_story_5037_50370601_120_dialog_content = "PlayerName製作人……",
  ui_story_5037_50370601_121_dialog_content = "嗯，你說得對！",
  ui_story_5037_50370601_122_dialog_content = "我早就不是當初的那個自己了。",
  ui_story_5037_50370601_123_dialog_content = "PlayerName製作人，請好好注視著我吧。",
  ui_story_5037_50370601_124_dialog_content = "我會以最好的狀態……",
  ui_story_5037_50370601_125_dialog_content = "完成這場畢業演唱會！",
  ui_story_5037_50370701_1_dialog_content = "畢業演唱會，也順利結束了。",
  ui_story_5037_50370701_2_dialog_content = "道具和燈光沒有出錯的地方，歌爾蒂的表演更不在話下。",
  ui_story_5037_50370701_3_dialog_content = "其他所有我們想要展現的細節，都完美地呈現了出來。",
  ui_story_5037_50370701_4_dialog_content = "觀眾高呼歌爾蒂的名字，久久不肯離場。",
  ui_story_5037_50370701_5_dialog_content = "舞台上下都是一片激動與興奮的心情。",
  ui_story_5037_50370701_6_dialog_content = "可是為什麼……",
  ui_story_5037_50370701_7_dialog_content = "為什麼我的心情會突然變得有些低落？",
  ui_story_5037_50370701_8_dialog_content = "啊！",
  ui_story_5037_50370701_9_dialog_content = "差點忘了，涉女士說過要在這個時間宣布最終的對決結果！",
  ui_story_5037_50370701_10_dialog_content = "已經快要遲到了嗎？",
  ui_story_5037_50370701_11_dialog_content = "哈……哈……哈……",
  ui_story_5037_50370701_12_dialog_content = "對不起，我來晚了！",
  ui_story_5037_50370701_13_dialog_content = "PlayerName製作人再不來，我都以為你們打算放棄對決了呢。",
  ui_story_5037_50370701_14_dialog_content = "不過歌爾蒂呢？怎麼只有你一個人來了？",
  ui_story_5037_50370701_15_dialog_content = "歌爾蒂正在和粉絲互動，抽不開身。",
  ui_story_5037_50370701_16_dialog_content = "哼，這有什麼呀，師父也被粉絲團團圍住爭相合影呢！",
  ui_story_5037_50370701_17_dialog_content = "我親愛的偶像們人氣真是高呢。",
  ui_story_5037_50370701_18_dialog_content = "好事，這可是件好事~",
  ui_story_5037_50370701_19_dialog_content = "我很想等他們兩人忙完後，親自向他們說聲恭喜。",
  ui_story_5037_50370701_20_dialog_content = "但我稍後還約了影視製作公司的老闆談合作。",
  ui_story_5037_50370701_21_dialog_content = "涉女士真是比我們還忙碌啊。",
  ui_story_5037_50370701_22_dialog_content = "沒關係啦，涉老闆妳就快點宣布對決結果吧。",
  ui_story_5037_50370701_23_dialog_content = "菲雅製作人還真是急性子呢。",
  ui_story_5037_50370701_24_dialog_content = "不過這也不是件壞事，從維克的畢業演唱會就能看出……",
  ui_story_5037_50370701_25_dialog_content = "菲雅在很短的時間裡，就學會了如何策劃演唱會。",
  ui_story_5037_50370701_26_dialog_content = "相較考核演唱會，維克的畢業演唱會在舞台效果和節目設計方面，都有突破性的進步。",
  ui_story_5037_50370701_27_dialog_content = "那當然，菲雅是真的有好好努力了！",
  ui_story_5037_50370701_28_dialog_content = "而歌爾蒂陣營呢，已經辦過一場難以超越的考核演唱會。",
  ui_story_5037_50370701_29_dialog_content = "但是PlayerName製作人，這次仍然能在舞台設計上帶來驚艷。",
  ui_story_5037_50370701_30_dialog_content = "再加上歌爾蒂創作的新歌，給觀眾們帶來了十足的誠意和感動。",
  ui_story_5037_50370701_31_dialog_content = "唔，什麼嘛，還以為只會誇菲雅呢。",
  ui_story_5037_50370701_32_dialog_content = "這次對決的結果就是，菲雅組……",
  ui_story_5037_50370701_33_dialog_content = "什麼什麼什麼什麼？",
  ui_story_5037_50370701_34_dialog_content = "菲雅贏了嗎！？",
  ui_story_5037_50370701_35_dialog_content = "親愛的，聽我說完呢。",
  ui_story_5037_50370701_36_dialog_content = "真的很可惜，菲雅組以非常些微的差距輸給了PlayerName組。",
  ui_story_5037_50370701_37_dialog_content = "你們這場的票數大概只有個位數的差距呢~",
  ui_story_5037_50370701_38_dialog_content = "欸？",
  ui_story_5037_50370701_39_dialog_content = "綜合三場演唱會的成績，最後獲得優勝獎金的就是……",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerName和歌爾蒂！</size>",
  ui_story_5037_50370701_41_dialog_content = "……",
  ui_story_5037_50370701_42_dialog_content = "哇啊啊啊……",
  ui_story_5037_50370701_43_dialog_content = "菲雅明明、明明都那麼努力了。",
  ui_story_5037_50370701_44_dialog_content = "不只要花時間監督不成器的師父，還要熬夜學習怎麼設計演唱會……",
  ui_story_5037_50370701_45_dialog_content = "菲雅製作人，妳這樣會錯過我接著要宣布的獎項呢。",
  ui_story_5037_50370701_46_dialog_content = "欸？",
  ui_story_5037_50370701_47_dialog_content = "菲雅和維克在這段時間內，也透過努力獲得了很多粉絲，帶動了浮空商會的周邊銷量。",
  ui_story_5037_50370701_48_dialog_content = "鑑於兩人的優異表現……",
  ui_story_5037_50370701_49_dialog_content = "你們將獲得額外的獎金喔~",
  ui_story_5037_50370701_50_dialog_content = "額外的……",
  ui_story_5037_50370701_51_dialog_content = "獎金！？",
  ui_story_5037_50370701_52_dialog_content = "我就知道。菲雅和師父沒有白白受苦，一切都是能獲得回報的嗚嗚嗚！",
  ui_story_5037_50370701_53_dialog_content = "咳咳，還有呢~",
  ui_story_5037_50370701_54_dialog_content = "在錄製這次實境秀的過程中，獲得「最努力偶像獎」的是……",
  ui_story_5037_50370701_55_dialog_content = "維克！",
  ui_story_5037_50370701_56_dialog_content = "師父？師父獲獎了？",
  ui_story_5037_50370701_57_dialog_content = "而且是「最努力偶像獎」？",
  ui_story_5037_50370701_58_dialog_content = "師父贏過了歌爾蒂，獲得了大家的認可欸！",
  ui_story_5037_50370701_59_dialog_content = "我家師父還是不錯的嘛。",
  ui_story_5037_50370701_60_dialog_content = "嘿嘿，這也是對菲雅和凱羅工作的肯定呢~",
  ui_story_5037_50370701_61_dialog_content = "囉～",
  ui_story_5037_50370701_62_dialog_content = "PlayerName，不好意思啦，是我們獲得這個獎呢嘿嘿嘿。",
  ui_story_5037_50370701_63_dialog_content = "維克的確很努力，我也覺得這是他應得的。",
  ui_story_5037_50370701_64_dialog_content = "接下來，獲得「最佳製作人獎」的是……",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName製作人！</size>",
  ui_story_5037_50370701_66_dialog_content = "欸？",
  ui_story_5037_50370701_67_dialog_content = "我？最佳製作人？",
  ui_story_5037_50370701_68_dialog_content = "……！！！",
  ui_story_5037_50370701_69_dialog_content = "哼，好吧。",
  ui_story_5037_50370701_70_dialog_content = "菲雅也承認PlayerName的確比菲雅更快、更好地掌握了製作人的工作。",
  ui_story_5037_50370701_71_dialog_content = "誰讓PlayerName比菲雅大幾歲呢！",
  ui_story_5037_50370701_72_dialog_content = "等菲雅我和PlayerName一樣大的時候，一定會比PlayerName更厲害的！",
  ui_story_5037_50370701_73_dialog_content = "菲雅？",
  ui_story_5037_50370701_74_dialog_content = "怎麼說走就走了？",
  ui_story_5037_50370701_75_dialog_content = "放心吧，看樣子應該是去找她師父了。",
  ui_story_5037_50370701_76_dialog_content = "那孩子就是說話像刀子，其實心裡還是很溫柔呢。",
  ui_story_5037_50370701_77_dialog_content = "涉女士怎麼這麼懂菲雅？",
  ui_story_5037_50370701_78_dialog_content = "雖然我不是空裔，沒有感應能力……",
  ui_story_5037_50370701_79_dialog_content = "但我也許比PlayerName更會讀人心也說不定呢。",
  ui_story_5037_50370701_80_dialog_content = "要不然，你以為我是怎麼白手起家，發展浮空商會到現在的規模呢？",
  ui_story_5037_50370701_81_dialog_content = "……",
  ui_story_5037_50370701_82_dialog_content = "莉莉卡。",
  ui_story_5037_50370701_83_dialog_content = "涉老闆，我一直都在喔~",
  ui_story_5037_50370701_84_dialog_content = "妳之前拍的素材都非常好，我很滿意。",
  ui_story_5037_50370701_85_dialog_content = "妥善剪輯，一定會成為一部非常有吸引力的實境秀節目。",
  ui_story_5037_50370701_86_dialog_content = "到時候找妳做導演的人，也會絡繹不絕的。",
  ui_story_5037_50370701_87_dialog_content = "莉莉卡一定會仔細剪輯的！",
  ui_story_5037_50370701_88_dialog_content = "以後涉老闆有什麼需求，也儘管告訴莉莉卡喔~",
  ui_story_5037_50370701_89_dialog_content = "嗯，演唱會結束後，也會發生一些有趣的故事呢。",
  ui_story_5037_50370701_90_dialog_content = "希望妳好好盯緊，不要錯過最棒的素材呢。",
  ui_story_5037_50370701_91_dialog_content = "好的，涉老闆！",
  ui_story_5037_50370701_92_dialog_content = "請您放心交給莉莉卡吧~",
  ui_story_5037_50370701_93_dialog_content = "PlayerName，如果你想繼續擔任製作人，我也是很歡迎的。",
  ui_story_5037_50370701_94_dialog_content = "不過記得，到時要把簡歷送到我的辦公室喔。",
  ui_story_5037_50370701_95_dialog_content = "好……好的！",
  ui_story_5037_50370701_96_dialog_content = "嗯，時間正好，我要動身去談生意了。",
  ui_story_5037_50370701_97_dialog_content = "期待大家的好消息囉~",
  ui_story_5037_50370701_98_dialog_content = "涉老闆再見！",
  ui_story_5037_50370701_99_dialog_content = "呼~我的製作人之路，到這裡就真的結束了嗎？",
  ui_story_5037_50370701_100_dialog_content = "……",
  ui_story_5037_50370701_101_dialog_content = "欸？莉莉卡妳為什麼用攝影機對著我的臉啊？",
  ui_story_5037_50370701_102_dialog_content = "實境秀拍攝還沒有結束呢。",
  ui_story_5037_50370701_103_dialog_content = "我還要繼續工作才可以呀。",
  ui_story_5037_50370701_104_dialog_content = "可演唱會結束了，我也沒有其他的工作了……",
  ui_story_5037_50370701_105_dialog_content = "妳還要拍什麼呢？",
  ui_story_5037_50370701_106_dialog_content = "當然是拍你啦。",
  ui_story_5037_50370701_107_dialog_content = "最佳製作人~",
  ui_story_5037_50370701_108_dialog_content = "……我？我應該做些什麼嗎？",
  ui_story_5037_50370701_109_dialog_content = "那要問你自己呀。",
  ui_story_5037_50370701_110_dialog_content = "問我自己？",
  ui_story_5037_50370701_111_dialog_content = "對呀，例如……你現在最想去找誰呢？",
  ui_story_5037_50370701_112_dialog_content = "我想去找誰？",
  ui_story_5037_50370701_113_dialog_content = "對啊，說起來今天還沒有結束呢！",
  ui_story_5037_50370701_114_dialog_content = "我想……我想去找……",
  ui_story_5037_50370701_115_option_content = "歌爾蒂",
  ui_story_5037_50370701_116_dialog_content = "我要快點告訴她我們獲勝的好消息！",
  ui_story_5037_50370701_117_option_content = "維克和菲雅",
  ui_story_5037_50370701_118_dialog_content = "我要去和維克說聲恭喜！",
  ui_story_5037_50370701_119_option_content = "薇絲和卡蓮",
  ui_story_5037_50370701_120_dialog_content = "我想向她們兩個道謝……",
  ui_story_5037_50370701_121_dialog_content = "要快點告訴歌爾蒂我們獲勝的好消息！",
  ui_story_5037_50370701_122_dialog_content = "然後把我想對她說的話……",
  ui_story_5037_50370701_123_dialog_content = "等等！",
  ui_story_5037_50370701_124_dialog_content = "那些話好像都在事前採訪裡說過了呀！？",
  ui_story_5037_50370701_125_dialog_content = "那……那就聊聊這筆獎金的話題？",
  ui_story_5037_50370701_126_dialog_content = "「歌爾蒂，有了這筆錢，妳就可以多買幾件裙子了！」",
  ui_story_5037_50370701_127_dialog_content = "呃，好奇怪……",
  ui_story_5037_50370701_128_dialog_content = "「歌爾蒂，我們能贏得獎金都是妳的功勞！」",
  ui_story_5037_50370701_129_dialog_content = "不行不行，這樣顯得有點見外？",
  ui_story_5037_50370701_130_dialog_content = "「歌爾蒂，辛苦了！」",
  ui_story_5037_50370701_131_dialog_content = "這樣也太輕描淡寫了……",
  ui_story_5037_50370701_132_dialog_content = "歌爾蒂！歌爾蒂！歌爾蒂！歌爾蒂！",
  ui_story_5037_50370701_133_dialog_content = "謝謝大家的支持喔~",
  ui_story_5037_50370701_134_dialog_content = "大家一個一個來，千萬不要摔倒喲。",
  ui_story_5037_50370701_135_dialog_content = "演唱會已經結束好久了，還有這麼多粉絲環繞在歌爾蒂身邊？",
  ui_story_5037_50370701_136_dialog_content = "歌爾蒂和粉絲似乎聊得很開心，應該沒有需要我出面的地方吧。",
  ui_story_5037_50370701_137_dialog_content = "我還是不要去打擾他們了。",
  ui_story_5037_50370701_138_dialog_content = "嗯，還可以趁機好好想想，待會要和歌爾蒂說些什麼！",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerName製作人！</size>",
  ui_story_5037_50370701_140_dialog_content = "欸，剛才是歌爾蒂在喊我的名字嗎？",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName製作人，快過來呀！</size>",
  ui_story_5037_50370701_142_dialog_content = "歌爾蒂是想要我也過去和粉絲聊天嗎？",
  ui_story_5037_50370701_143_dialog_content = "還是算了吧。大家都是歌爾蒂的粉絲，應該不會對我有什麼興趣吧。",
  ui_story_5037_50370701_144_dialog_content = "大家稍等我一下喔，我馬上就回來~",
  ui_story_5037_50370701_145_dialog_content = "歌爾蒂放心飛，蒂蒂人永相隨！",
  ui_story_5037_50370701_146_dialog_content = "欸？",
  ui_story_5037_50370701_147_dialog_content = "歌爾蒂怎麼朝我走過來了？",
  ui_story_5037_50370701_148_dialog_content = "PlayerName製作人，你站在這裡做什麼呢。",
  ui_story_5037_50370701_149_dialog_content = "我……我是想來告訴妳……",
  ui_story_5037_50370701_150_dialog_content = "我們贏了！",
  ui_story_5037_50370701_151_dialog_content = "PlayerName製作人，你怎麼現在才知道，會不會有點太晚啦？",
  ui_story_5037_50370701_152_dialog_content = "歌爾蒂早就知道了嗎？",
  ui_story_5037_50370701_153_dialog_content = "嘻嘻，在唱完最後一首歌的時候，我就知道……",
  ui_story_5037_50370701_154_dialog_content = "這三場演唱會，我們都沒有留下任何遺憾。",
  ui_story_5037_50370701_155_dialog_content = "我們戰勝了自己，就已經是這段旅程的大贏家啦。",
  ui_story_5037_50370701_156_dialog_content = "原來歌爾蒂是這麼想的。",
  ui_story_5037_50370701_157_dialog_content = "剛才有好多粉絲都誇這幾次的舞台設計很好看呢，不想過去和大家交流一下嗎？",
  ui_story_5037_50370701_158_dialog_content = "我還是……",
  ui_story_5037_50370701_159_dialog_content = "讓粉絲們等太久，可不是偶像和偶像製作人該做的喔~",
  ui_story_5037_50370701_160_dialog_content = "親愛的蒂蒂人，大家久等啦！",
  ui_story_5037_50370701_161_dialog_content = "接下來我想為大家慎重地介紹一個人。",
  ui_story_5037_50370701_162_dialog_content = "當當當當~！",
  ui_story_5037_50370701_163_dialog_content = "大……大家好！",
  ui_story_5037_50370701_164_dialog_content = "沒錯！我身邊這位有點害羞的人，就是傳說中的空裔——PlayerName喔~",
  ui_story_5037_50370701_165_dialog_content = "而且呀，PlayerName就是這段時間以來，陪伴在歌爾蒂左右的製作人！",
  ui_story_5037_50370701_166_dialog_content = "大家能看到這麼棒的演唱會，都是多虧了PlayerName呢。",
  ui_story_5037_50370701_167_dialog_content = "實在是過獎了。我……我其實也剛剛接觸這個職業沒多久。",
  ui_story_5037_50370701_168_dialog_content = "原來這個豆芽菜就是歌爾蒂的製作人，還真沒看出來啊。",
  ui_story_5037_50370701_169_dialog_content = "都說人不可貌相呢，小子挺厲害啊！",
  ui_story_5037_50370701_170_dialog_content = "我也算是看著歌爾蒂走到今天的資深粉了。",
  ui_story_5037_50370701_171_dialog_content = "雖說以前的歌爾蒂就已經在各方面都很出色了，但是有了製作人以後……",
  ui_story_5037_50370701_172_dialog_content = "歌爾蒂又進步了好多，而且也找到屬於自己的前進方向！",
  ui_story_5037_50370701_173_dialog_content = "你的說那些我都不懂。",
  ui_story_5037_50370701_174_dialog_content = "我只知道，我這輩子還沒看過這麼讓人暢快的演唱會！",
  ui_story_5037_50370701_175_dialog_content = "都是PlayerName製作人的功勞啊！",
  ui_story_5037_50370701_176_dialog_content = "PlayerName！製作人！PlayerName！製作人！PlayerName！製作人！",
  ui_story_5037_50370701_177_dialog_content = "……",
  ui_story_5037_50370701_178_dialog_content = "（突然被這麼多人喊名字……感覺好窘。）",
  ui_story_5037_50370701_179_dialog_content = "（我不過是在幕後做了力所能及的事，真的值得大家這樣追捧嗎？）",
  ui_story_5037_50370701_180_dialog_content = "PlayerName製作人……",
  ui_story_5037_50370701_181_dialog_content = "你當然值得得到大家的喜愛。",
  ui_story_5037_50370701_182_dialog_content = "這麼多天以來，真的辛苦你啦！",
  ui_story_5037_50370701_183_dialog_content = "（欸，歌爾蒂是怎麼看穿我的內心的？）",
  ui_story_5037_50370701_184_dialog_content = "（而且還搶走我想說的台詞啊！！！）",
  ui_story_5037_50370701_185_dialog_content = "PlayerName製作人，大家好像還有話要對你說喔~",
  ui_story_5037_50370701_186_dialog_content = "嗯？",
  ui_story_5037_50370701_187_dialog_content = "PlayerName製作人，麻煩幫我簽個名！",
  ui_story_5037_50370701_188_dialog_content = "雖然我不是「空心粉」，但我也想要PlayerName製作人的簽名！",
  ui_story_5037_50370701_189_dialog_content = "我也要！",
  ui_story_5037_50370701_190_dialog_content = "還有我！",
  ui_story_5037_50370701_191_dialog_content = "欸……欸！？",
  ui_story_5037_50370701_192_dialog_content = "早知道就該把簽名好好練一練了……",
  ui_story_5037_50370701_193_dialog_content = "哇！",
  ui_story_5037_50370701_194_dialog_content = "菲雅從來沒有數過這麼多白夜幣！",
  ui_story_5037_50370701_195_dialog_content = "數錢數到手軟原來是這種感覺？",
  ui_story_5037_50370701_196_dialog_content = "涉老闆真是太大方了吧！",
  ui_story_5037_50370701_197_dialog_content = "菲雅，妳這是在和誰說話呢？",
  ui_story_5037_50370701_198_dialog_content = "周圍好像沒有別人呀。",
  ui_story_5037_50370701_199_dialog_content = "還能有誰呀，當然是在跟臭師父說話啦！",
  ui_story_5037_50370701_200_dialog_content = "師父？",
  ui_story_5037_50370701_201_dialog_content = "欸？要不是PlayerName提醒，我都沒有發現……",
  ui_story_5037_50370701_202_dialog_content = "臭師父又躺在桌子底下睡著了！",
  ui_story_5037_50370701_203_dialog_content = "凱羅，快把師父給拖出來。",
  ui_story_5037_50370701_204_dialog_content = "囉！",
  ui_story_5037_50370701_205_dialog_content = "嗯？",
  ui_story_5037_50370701_206_dialog_content = "可話又說回來，PlayerName是從哪裡突然冒出來的？",
  ui_story_5037_50370701_207_dialog_content = "門開著，我就進來了呀。",
  ui_story_5037_50370701_208_dialog_content = "什麼！？菲雅竟然在數錢的時候忘記關門了？",
  ui_story_5037_50370701_209_dialog_content = "放心吧，我剛才已經幫妳關好了。",
  ui_story_5037_50370701_210_dialog_content = "也不知道剛才有沒有小偷進來？",
  ui_story_5037_50370701_211_dialog_content = "不行！我要再數一遍有多少白夜幣！",
  ui_story_5037_50370701_212_dialog_content = "囉囉！",
  ui_story_5037_50370701_213_dialog_content = "不要訓練了……",
  ui_story_5037_50370701_214_dialog_content = "維克？",
  ui_story_5037_50370701_215_dialog_content = "小毛球，我們快跑！",
  ui_story_5037_50370701_216_dialog_content = "這是還沒睡醒……在說夢話嗎？",
  ui_story_5037_50370701_217_dialog_content = "八十三、八十四、八十五……",
  ui_story_5037_50370701_218_dialog_content = "菲雅，再數多少次白夜幣也不會變多的。",
  ui_story_5037_50370701_219_dialog_content = "快看看妳師父這是怎麼了？",
  ui_story_5037_50370701_220_dialog_content = "凱羅把他從桌子底下拖出來，他竟然一點反應都沒有！",
  ui_story_5037_50370701_221_dialog_content = "等一下，等我數到一百再跟我說話……",
  ui_story_5037_50370701_222_dialog_content = "九十八、九十九、一百！",
  ui_story_5037_50370701_223_dialog_content = "你剛才問我什麼？",
  ui_story_5037_50370701_224_dialog_content = "呃，快看看妳師父這是怎麼了？",
  ui_story_5037_50370701_225_dialog_content = "怎麼一點反應都沒有。",
  ui_story_5037_50370701_226_dialog_content = "啊，師父只是在睡大覺而已啦。",
  ui_story_5037_50370701_227_dialog_content = "這幾天師父確實累壞了……",
  ui_story_5037_50370701_228_dialog_content = "畢竟是個以前從來都沒有勞動過的人！",
  ui_story_5037_50370701_229_dialog_content = "快跑啊！！！",
  ui_story_5037_50370701_230_dialog_content = "維克，你醒了？",
  ui_story_5037_50370701_231_dialog_content = "PlayerName？你怎麼也在這裡？",
  ui_story_5037_50370701_232_dialog_content = "快、快跑！凱羅發瘋了，一直催著要我訓練！",
  ui_story_5037_50370701_233_dialog_content = "有沒有可能，你剛剛是在做夢？",
  ui_story_5037_50370701_234_dialog_content = "嗯？菲雅也在……？",
  ui_story_5037_50370701_235_dialog_content = "菲雅前面怎麼有這麼多白夜幣？",
  ui_story_5037_50370701_236_dialog_content = "我現在才是在做夢吧！？",
  ui_story_5037_50370701_237_dialog_content = "不過這個夢比剛才的夢要讓人舒服多了呢。",
  ui_story_5037_50370701_238_dialog_content = "呃，要怎麼告訴維克他現在不是在做夢啊？",
  ui_story_5037_50370701_239_dialog_content = "哼哼，看來又到了凱羅出場的時候啦！",
  ui_story_5037_50370701_240_dialog_content = "！！！",
  ui_story_5037_50370701_241_dialog_content = "菲雅好徒兒，為師現在覺得無比清醒。",
  ui_story_5037_50370701_242_dialog_content = "可憐的維克已經患上凱羅恐懼症了嗎？",
  ui_story_5037_50370701_243_dialog_content = "啊，這些白夜幣是真的欸。",
  ui_story_5037_50370701_244_dialog_content = "涉老闆還真是慷慨。",
  ui_story_5037_50370701_245_dialog_content = "我和師父不過是參加了這幾天的實境秀拍攝，她就捨得給我們這麼多額外的獎金……",
  ui_story_5037_50370701_246_dialog_content = "這要是真正的偶像，該賺多少錢啊？",
  ui_story_5037_50370701_247_dialog_content = "菲雅，為什麼要在乎別人能賺多少錢呢？過好我們自己的生活就好啦。",
  ui_story_5037_50370701_248_dialog_content = "欸，好像有道理呢？",
  ui_story_5037_50370701_249_dialog_content = "師父真是難得這麼正徑……",
  ui_story_5037_50370701_250_dialog_content = "有了這些錢，我終於可以去影鎮新開的那家豪華餐廳享受一番了~",
  ui_story_5037_50370701_251_dialog_content = "……不可以！",
  ui_story_5037_50370701_252_dialog_content = "有什麼不可以的呢？",
  ui_story_5037_50370701_253_dialog_content = "這些日子以來，為師一直照妳說的做。",
  ui_story_5037_50370701_254_dialog_content = "又是訓練又是身材管理的，已經很久都沒吃過正經的菜色了。",
  ui_story_5037_50370701_255_dialog_content = "現在我們好不容易獲得了這麼豐厚的獎金，當然要好好犒勞犒勞自己啦。",
  ui_story_5037_50370701_256_dialog_content = "看來師父還是沒有意識到情況的嚴重性。",
  ui_story_5037_50370701_257_dialog_content = "雖然這份獎金看起來很豐厚。",
  ui_story_5037_50370701_258_dialog_content = "但是扣掉師父賒欠的蒼獅龍零食費用、平時的伙食費、房屋的修理費、菲雅的勞務費……",
  ui_story_5037_50370701_259_dialog_content = "就已經花掉一大半啦。",
  ui_story_5037_50370701_260_dialog_content = "想到師父平時都不太可靠，以後的收入來源還是個問題……",
  ui_story_5037_50370701_261_dialog_content = "這點獎金還不知道能支持多久呢！",
  ui_story_5037_50370701_262_dialog_content = "以後的收入來源？",
  ui_story_5037_50370701_263_dialog_content = "既然維克這麼有成為偶像的潛質，為什麼不繼續當偶像呢？",
  ui_story_5037_50370701_264_dialog_content = "PlayerName，你就饒了我吧。",
  ui_story_5037_50370701_265_dialog_content = "堅持這麼多天對我來說已經是奇蹟了，要我以後天天做這個？",
  ui_story_5037_50370701_266_dialog_content = "光想都要做惡夢。",
  ui_story_5037_50370701_267_dialog_content = "……PlayerName說的有道理啊！",
  ui_story_5037_50370701_268_dialog_content = "反正師父待在家裡，既不能保護神奇動物，也找不到工作賺錢……",
  ui_story_5037_50370701_269_dialog_content = "還不如出道成為真正的偶像呢。",
  ui_story_5037_50370701_270_dialog_content = "等實境秀播出之後，肯定會有更多粉絲喜歡上師父的！",
  ui_story_5037_50370701_271_dialog_content = "菲雅，好徒兒……",
  ui_story_5037_50370701_272_dialog_content = "妳就放過為師吧！",
  ui_story_5037_50370701_273_dialog_content = "嗯，讓師父正式出道做偶像，就這麼快樂地決定了。",
  ui_story_5037_50370701_274_dialog_content = "啊！？",
  ui_story_5037_50370701_275_dialog_content = "師父，現在還有時間，我們繼續訓練吧！",
  ui_story_5037_50370701_276_dialog_content = "我已經沒有力氣了啊……",
  ui_story_5037_50370701_277_dialog_content = "凱羅，我們一起陪師父訓練吧~",
  ui_story_5037_50370701_278_dialog_content = "不要啊——",
  ui_story_5037_50370701_279_dialog_content = "欸，師父你怎麼跑得那麼快？",
  ui_story_5037_50370701_280_dialog_content = "你這樣子不像沒有力氣了呀，還是把力氣用在訓練上吧！",
  ui_story_5037_50370701_281_dialog_content = "維克……",
  ui_story_5037_50370701_282_dialog_content = "真是辛苦了！",
  ui_story_5037_50370701_283_dialog_content = "最佳製作人……",
  ui_story_5037_50370701_284_dialog_content = "嘿嘿，真不敢相信涉女士竟然把這個獎項頒給了我。",
  ui_story_5037_50370701_285_dialog_content = "回想剛到星願事務所的時候，我什麼都不懂，還在擔心自己會連累歌爾蒂。",
  ui_story_5037_50370701_286_dialog_content = "沒想到，最後我不只真的幫助歌爾蒂辦完三場演唱會，竟然還得到了涉女士的認可！",
  ui_story_5037_50370701_287_dialog_content = "嗯，就把這個消息當作神祕驚喜，告訴薇絲和卡蓮吧。",
  ui_story_5037_50370701_288_dialog_content = "她們兩個應該就在這附近才對。",
  ui_story_5037_50370701_289_dialog_content = "難道是在這個房間裡？",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>咚咚咚！</color>",
  ui_story_5037_50370701_291_dialog_content = "我進來囉~",
  ui_story_5037_50370701_292_dialog_content = "這房間平時都會開著燈，怎麼今天這麼黑？",
  ui_story_5037_50370701_293_dialog_content = "薇絲？卡蓮？奇怪，她們也不在這嗎？",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>啪！</color>",
  ui_story_5037_50370701_295_dialog_content = "咦！？",
  ui_story_5037_50370701_296_dialog_content = "驚——喜——！",
  ui_story_5037_50370701_297_dialog_content = "畢業演唱會完美落幕~",
  ui_story_5037_50370701_298_dialog_content = "恭喜PlayerName成功完成了所有任務。",
  ui_story_5037_50370701_299_dialog_content = "這、這些是……",
  ui_story_5037_50370701_300_dialog_content = "這是我們委託新開業的豪華餐廳送來的美味餐點和果汁飲料。",
  ui_story_5037_50370701_301_dialog_content = "還有一個巨大的奶油蛋糕哦~！",
  ui_story_5037_50370701_302_dialog_content = "PlayerName自從開始學習如何當製作人之後，好像都沒怎麼認真吃飯。",
  ui_story_5037_50370701_303_dialog_content = "所以我們準備了這個驚喜慶功宴，這些應該都是PlayerName愛吃的吧。",
  ui_story_5037_50370701_304_dialog_content = "薇絲、卡蓮……",
  ui_story_5037_50370701_305_dialog_content = "妳們什麼時候開始準備的？",
  ui_story_5037_50370701_306_dialog_content = "我竟然一點都沒有發現！",
  ui_story_5037_50370701_307_dialog_content = "嘿嘿，其實我們早就有這個想法了~",
  ui_story_5037_50370701_308_dialog_content = "PlayerName今天一直在後台忙著演唱會的事情，也給了我們「可乘之機」。",
  ui_story_5037_50370701_309_dialog_content = "這麼說，妳們知道今天的對決結果了？",
  ui_story_5037_50370701_310_dialog_content = "還不知道喔~",
  ui_story_5037_50370701_311_dialog_content = "欸，如果是我輸了，還怎麼慶功呢？",
  ui_story_5037_50370701_312_dialog_content = "我和薇絲都覺得，無論今天的結果如何……",
  ui_story_5037_50370701_313_dialog_content = "你都做到了努力超越自己的極限。",
  ui_story_5037_50370701_314_dialog_content = "PlayerName能夠堅持學習，一直走到最後，這本來就是一件很厲害的事了~",
  ui_story_5037_50370701_315_dialog_content = "為了這個，也值得我們大肆慶祝一番啊！",
  ui_story_5037_50370701_316_dialog_content = "妳們……真是的，竟然說了這麼多讓我感動的話。",
  ui_story_5037_50370701_317_dialog_content = "弄得我眼睛都進沙子了！",
  ui_story_5037_50370701_318_dialog_content = "所以最後的結果如何呀？",
  ui_story_5037_50370701_319_dialog_content = "說好的不在意結果呢！？",
  ui_story_5037_50370701_320_dialog_content = "哈哈哈，因為我們都很相信PlayerName喔~",
  ui_story_5037_50370701_321_dialog_content = "你剛才在房外嘀咕什麼「把神祕驚喜告訴薇絲和卡蓮」，是什麼驚喜呢？",
  ui_story_5037_50370701_322_dialog_content = "嘿嘿嘿，我和歌爾蒂贏得了對決的勝利！",
  ui_story_5037_50370701_323_dialog_content = "而且，涉女士還把「最佳製作人獎」頒給了我！",
  ui_story_5037_50370701_324_dialog_content = "哇！竟然還有這種獎項嗎？",
  ui_story_5037_50370701_325_dialog_content = "看來涉女士也是眼光犀利之人，她一定也看到了PlayerName的巨大進步。",
  ui_story_5037_50370701_326_dialog_content = "所以這個獎項有額外的獎金嗎！？",
  ui_story_5037_50370701_327_dialog_content = "這個……好像沒有。",
  ui_story_5037_50370701_328_dialog_content = "哈哈哈，也是呢。這項榮譽本身是多少獎金都換不回來的嘛~",
  ui_story_5037_50370701_329_dialog_content = "有了這個獎項，PlayerName以後要找工作也許就容易多了。",
  ui_story_5037_50370701_330_dialog_content = "是呀，PlayerName現在的能力已經和專業的製作人不相上下啦。",
  ui_story_5037_50370701_331_dialog_content = "如果不是妳們一直在幫忙出謀劃策，我大概也沒有信心能夠走到今天。",
  ui_story_5037_50370701_332_dialog_content = "薇絲、卡蓮，謝謝妳們這些日子以來陪在我身邊，無條件地幫我惡補知識。",
  ui_story_5037_50370701_333_dialog_content = "欸，有一點說錯了喔。",
  ui_story_5037_50370701_334_dialog_content = "嗯？",
  ui_story_5037_50370701_335_dialog_content = "我們可不是只有這些日子才陪在你身邊的呀~！",
  ui_story_5037_50370701_336_dialog_content = "是啊，我們不是一直都在一起嗎？",
  ui_story_5037_50370701_337_dialog_content = "啊，也是呢。",
  ui_story_5037_50370701_338_dialog_content = "我重新說！",
  ui_story_5037_50370701_339_dialog_content = "好啦好啦，我們關係都這麼好了，你怎麼還在跟我們客氣呀。",
  ui_story_5037_50370701_340_dialog_content = "而且你知道嗎？",
  ui_story_5037_50370701_341_dialog_content = "這次我回啟光查資料的時候，發現啟光的大家也對偶像很感興趣。",
  ui_story_5037_50370701_342_dialog_content = "薇薇安長官好像還在籌劃什麼活動，想要選出一批代表啟光的偶像出道呢！",
  ui_story_5037_50370701_343_dialog_content = "欸！？啟光的偶像？",
  ui_story_5037_50370701_344_dialog_content = "嘶吼吧，讓這場演出更加生動！",
  ui_story_5037_50370701_345_dialog_content = "嗯？怎麼沒有聲音了？",
  ui_story_5037_50370701_346_dialog_content = "是被在下的歌聲所折服，而忘記歡呼鼓掌了嗎？",
  ui_story_5037_50370701_347_dialog_content = "哈哈哈哈哈哈哈哈哈哈哈哈！",
  ui_story_5037_50370701_348_dialog_content = "嘶……",
  ui_story_5037_50370701_349_dialog_content = "嗯？PlayerName你在想什麼，怎麼突然滿頭冷汗？",
  ui_story_5037_50370701_350_dialog_content = "沒什麼！",
  ui_story_5037_50370701_351_dialog_content = "我只是覺得啟光的偶像活動應該會很精彩的！",
  ui_story_5037_50370701_352_dialog_content = "我也開始認真地考慮要不要建議父親也在白夜城舉辦一場偶像比賽了。",
  ui_story_5037_50370701_353_dialog_content = "欸，白夜城的那些大貴族會同意嗎？",
  ui_story_5037_50370701_354_dialog_content = "想必會很難吧。",
  ui_story_5037_50370701_355_dialog_content = "但我覺得自己真的從這次經歷中學到了很多。",
  ui_story_5037_50370701_356_dialog_content = "我現在覺得，堂堂正正地展示自己的魅力，也不是什麼讓人討厭的事。",
  ui_story_5037_50370701_357_dialog_content = "一些困擾我許久的事情彷彿突然間煙消雲散了。",
  ui_story_5037_50370701_358_dialog_content = "喔~我明白啦！",
  ui_story_5037_50370701_359_dialog_content = "卡蓮距離自己所追求的「王道」又更近一步了呢~",
  ui_story_5037_50370701_360_dialog_content = "這也能和「王道」扯上關係嗎？",
  ui_story_5037_50370701_361_dialog_content = "認真思考的話，其實不無道理呢。",
  ui_story_5037_50370701_362_dialog_content = "欸？",
  ui_story_5037_50370701_363_dialog_content = "飯菜涼了就不好吃了，我們快點開動吧！",
  ui_story_5037_50370701_364_dialog_content = "有道理，我們先舉杯正式慶祝一下吧。",
  ui_story_5037_50370701_365_dialog_content = "恭喜PlayerName榮獲「最佳製作人獎」！",
  ui_story_5037_50370701_366_dialog_content = "乾杯！",
  ui_story_5037_50370701_367_option_content = "乾杯！",
  ui_story_5037_50370801_1_dialog_content = "舞蹈特訓、聲樂練習、約見記者，還要聯絡握手會的場地出租者……",
  ui_story_5037_50370801_2_dialog_content = "？",
  ui_story_5037_50370801_3_dialog_content = "想要聯絡上出租者，需要在午飯之後晚飯之前，但記者又是在下午到訪……",
  ui_story_5037_50370801_4_dialog_content = "……",
  ui_story_5037_50370801_5_dialog_content = "還要安排歌爾蒂的休息時間，還有換裝和補妝的時間，這樣的話只能這麼安排了……",
  ui_story_5037_50370801_6_dialog_content = "……？",
  ui_story_5037_50370801_7_dialog_content = "這樣！不就又要從早到晚忙一整天了嗎！",
  ui_story_5037_50370801_8_dialog_content = "PlayerName？",
  ui_story_5037_50370801_9_dialog_content = "唔哇！？",
  ui_story_5037_50370801_10_dialog_content = "原來是歌爾蒂啊，差點嚇死我了。",
  ui_story_5037_50370801_11_dialog_content = "你在嘀嘀咕咕地說些什麼呢？",
  ui_story_5037_50370801_12_dialog_content = "看你這麼沒有精神，要不要和歌爾蒂一起練練舞呢？",
  ui_story_5037_50370801_13_dialog_content = "多做運動，有助於保持身材和健康喔！",
  ui_story_5037_50370801_14_dialog_content = "製作人的健康，同樣攸關偶像活動和演唱會的最終成果呢！",
  ui_story_5037_50370801_15_dialog_content = "唉，我正在排計畫表呢……",
  ui_story_5037_50370801_16_dialog_content = "每天都有很多事項，辦完一件就要緊接著去辦下一件……",
  ui_story_5037_50370801_17_dialog_content = "想要擠出一點休息時間，都變得這麼困難！",
  ui_story_5037_50370801_18_dialog_content = "果然還是因為我是個菜鳥製作人吧……",
  ui_story_5037_50370801_19_dialog_content = "PlayerName已經很強了喔！",
  ui_story_5037_50370801_20_dialog_content = "明明只做了幾天製作人，但已經對日常工作相當熟練了，這可不是每個人都能做到的！",
  ui_story_5037_50370801_21_dialog_content = "所以說，不要灰心，要不要摸一摸棉花糖？",
  ui_story_5037_50370801_22_dialog_content = "它的毛毛可軟了，一定能夠治癒你的心靈。",
  ui_story_5037_50370801_23_dialog_content = "汪汪！",
  ui_story_5037_50370801_24_dialog_content = "謝謝，那就讓我摸摸它——",
  ui_story_5037_50370801_25_dialog_content = "等一下！",
  ui_story_5037_50370801_26_dialog_content = "怎麼了？",
  ui_story_5037_50370801_27_dialog_content = "我忘記聯絡明天要來採訪的報社，約定採訪時間了！",
  ui_story_5037_50370801_28_dialog_content = "不好意思，我先去忙了！",
  ui_story_5037_50370801_29_dialog_content = "……",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>不久之後</color>",
  ui_story_5037_50370801_31_dialog_content = "呼……還好趕上了。",
  ui_story_5037_50370801_32_dialog_content = "那可是一家大報社，要是不小心放了他們的鴿子，歌爾蒂在外面的評價就要降低了。",
  ui_story_5037_50370801_33_dialog_content = "PlayerName，你回來啦？",
  ui_story_5037_50370801_34_dialog_content = "啊，歌爾蒂！抱歉，剛才急急忙忙就跑出去了，都沒和妳好好打聲招呼……",
  ui_story_5037_50370801_35_dialog_content = "沒關係，我知道你是因為工作而這麼忙碌的。",
  ui_story_5037_50370801_36_dialog_content = "製作人的工作可真辛苦，雖然這幾天逐漸適應了工作的節奏——",
  ui_story_5037_50370801_37_dialog_content = "但還是很難適應工作的內容！",
  ui_story_5037_50370801_38_dialog_content = "如果只是單純安排時間，倒不是什麼困難的事情。",
  ui_story_5037_50370801_39_dialog_content = "但是除此之外還要應付狗仔隊，小心翼翼地提防他們套話……",
  ui_story_5037_50370801_40_dialog_content = "好難啊……",
  ui_story_5037_50370801_41_dialog_content = "真是辛苦你啦。",
  ui_story_5037_50370801_42_dialog_content = "不管多累，PlayerName還是好好完成了自己的工作！",
  ui_story_5037_50370801_43_dialog_content = "單憑這一點，就已經非常厲害了！",
  ui_story_5037_50370801_44_dialog_content = "謝謝誇獎！能被稱讚，疲勞感一下子減輕不少呢。",
  ui_story_5037_50370801_45_dialog_content = "沒錯，所以不管是誰，都需要有人鼓勵！",
  ui_story_5037_50370801_46_dialog_content = "這樣一想的話，歌爾蒂之前一直都是一個人在努力吧？",
  ui_story_5037_50370801_47_dialog_content = "既要當偶像，又要當自己的製作人……",
  ui_story_5037_50370801_48_dialog_content = "不僅要訓練，還要安排行程，應付狗仔……",
  ui_story_5037_50370801_49_option_content = "想想就覺得好厲害！",
  ui_story_5037_50370801_50_dialog_content = "哈哈……也不算什麼啦！",
  ui_story_5037_50370801_51_option_content = "想想就覺得好困難……",
  ui_story_5037_50370801_52_dialog_content = "但是，我成功堅持過來了。",
  ui_story_5037_50370801_53_dialog_content = "即使是我，要一個人肩負兩種不同的工作，也不是能輕鬆辦到的事情。",
  ui_story_5037_50370801_54_dialog_content = "從前的我也遇到過很多困難，甚至有好幾次都想要放棄了。",
  ui_story_5037_50370801_55_dialog_content = "歌爾蒂也會有想放棄的時候嗎？真想不到呢……",
  ui_story_5037_50370801_56_dialog_content = "這可是我的祕密，不許對別人說喔！",
  ui_story_5037_50370801_57_dialog_content = "絕對不會的，無論如何，我還是妳的製作人，可不會到處說妳的壞話呢！",
  ui_story_5037_50370801_58_dialog_content = "嗯嗯，那就好！",
  ui_story_5037_50370801_59_dialog_content = "從前的我在出道前，一直都是一個人自己努力。",
  ui_story_5037_50370801_60_dialog_content = "訓練和安排，哪一項都是不能耽誤的重要工作，更別提還要躲避神出鬼沒的狗仔隊。",
  ui_story_5037_50370801_61_dialog_content = "那時的我，經常忙到每天只能睡一兩個小時呢！",
  ui_story_5037_50370801_62_dialog_content = "而且常常隔天還要很早起床，補上前一天未完的訓練。",
  ui_story_5037_50370801_63_dialog_content = "那麼拼！？",
  ui_story_5037_50370801_64_dialog_content = "就算是熬夜習以為常的我，要是哪天只睡一兩個小時，第二天也會喪失鑽出被窩的意志……",
  ui_story_5037_50370801_65_dialog_content = "我也是差不多的情況啦！",
  ui_story_5037_50370801_66_dialog_content = "一天兩天沒什麼問題，但如果要持續更久，甚至好幾年呢？",
  ui_story_5037_50370801_67_dialog_content = "每次訓練結束，筋疲力竭的時候，我總是忍不住會這麼想……",
  ui_story_5037_50370801_68_dialog_content = "歌爾蒂最後還是克服困難，成為現在的知名偶像了吧？",
  ui_story_5037_50370801_69_dialog_content = "嗯！",
  ui_story_5037_50370801_70_dialog_content = "每次想要放棄的時候，我就會扔出我的幸運子彈，只要它彈頭朝下，就代表會發生好事情！",
  ui_story_5037_50370801_71_dialog_content = "每一次，它都是彈頭朝下的，所以我就這樣不斷堅持，最終成為了現在的樣子！",
  ui_story_5037_50370801_72_dialog_content = "還真是不屈不撓的毅力呢……",
  ui_story_5037_50370801_73_dialog_content = "嘿嘿。",
  ui_story_5037_50370801_74_dialog_content = "不過，現在情況不一樣啦。",
  ui_story_5037_50370801_75_dialog_content = "現在有了可靠的PlayerName製作人幫忙。",
  ui_story_5037_50370801_76_dialog_content = "我也能夠一心一意地專注訓練，不用考慮其他的事情！",
  ui_story_5037_50370801_77_dialog_content = "進步的速度也變得飛快了喔！",
  ui_story_5037_50370801_78_dialog_content = "我……真的有幫上忙嗎？",
  ui_story_5037_50370801_79_dialog_content = "千真萬確喔！",
  ui_story_5037_50370801_80_dialog_content = "那就好！",
  ui_story_5037_50370801_81_dialog_content = "之前我一直覺得自己是一個什麼都不會的新手，只會給妳添麻煩。",
  ui_story_5037_50370801_82_dialog_content = "但聽妳這麼說以後，我又找回自信了。",
  ui_story_5037_50370801_83_dialog_content = "以後我會繼續努力，當好一個製作人的。也請歌爾蒂多多指教！",
  ui_story_5037_50370801_84_dialog_content = "一言為定！",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>上午·訓練結束後</color>",
  ui_story_5037_50370901_2_dialog_content = "辛苦了，PlayerName！",
  ui_story_5037_50370901_3_dialog_content = "上午的訓練已經結束了，趁中午好好休息一下吧。",
  ui_story_5037_50370901_4_dialog_content = "妳也辛苦了，歌爾蒂！",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>咚咚咚！</color>",
  ui_story_5037_50370901_6_dialog_content = "請進——",
  ui_story_5037_50370901_7_dialog_content = "PlayerName！還有歌爾蒂~",
  ui_story_5037_50370901_8_dialog_content = "妳好啊，貢露！",
  ui_story_5037_50370901_9_dialog_content = "貢露？妳怎麼來了？",
  ui_story_5037_50370901_10_dialog_content = "我來這裡採購材料，聽說你正在影鎮當製作人，所以就順路過來看看~",
  ui_story_5037_50370901_11_dialog_content = "我還順便帶了最新設計的遊戲，怎麼樣，手下敗將，有興趣和我來場對決嗎？",
  ui_story_5037_50370901_12_dialog_content = "當然——",
  ui_story_5037_50370901_13_dialog_content = "呃，還是算了。",
  ui_story_5037_50370901_14_dialog_content = "嗯？竟然不打算挑戰我嗎？還真是難得呢。",
  ui_story_5037_50370901_15_dialog_content = "因為下午還有很多工作，我怕沉迷遊戲耽擱了時間。",
  ui_story_5037_50370901_16_dialog_content = "確實呢！那我就不打擾你工作啦。",
  ui_story_5037_50370901_17_dialog_content = "要好好加油喔，PlayerName，歌爾蒂。",
  ui_story_5037_50370901_18_dialog_content = "我期待你們的演唱會！",
  ui_story_5037_50370901_19_dialog_content = "好啊，敬請期待吧！",
  ui_story_5037_50370901_20_dialog_content = "拜拜~",
  ui_story_5037_50370901_21_dialog_content = "再見！",
  ui_story_5037_50370901_22_dialog_content = "好啦，我也要開始準備下午的工作了。",
  ui_story_5037_50370901_23_dialog_content = "等一下，現在是午休時間吧？休息時就要好好休息，不要想著工作呢。",
  ui_story_5037_50370901_24_dialog_content = "話是這麼說，但是，考核演唱會的時間也一天天靠近了呢？",
  ui_story_5037_50370901_25_dialog_content = "隨著時間靠近，要做的工作也越來越多，有時候不得不犧牲一點休息時間……",
  ui_story_5037_50370901_26_dialog_content = "PlayerName，你這幾天是不是午休和就寢時間都有在工作？",
  ui_story_5037_50370901_27_dialog_content = "嗯……算、算是吧……",
  ui_story_5037_50370901_28_dialog_content = "那可不行！",
  ui_story_5037_50370901_29_dialog_content = "得不到充足的休息，效率也會低落，長久而言不利於工作！",
  ui_story_5037_50370901_30_dialog_content = "為了彌補你之前犧牲的休息時間，今天下午PlayerName就休個假吧！",
  ui_story_5037_50370901_31_dialog_content = "出去走走，呼吸一下新鮮空氣，好好恢復精神！",
  ui_story_5037_50370901_32_dialog_content = "不，真的不用，我……",
  ui_story_5037_50370901_33_dialog_content = "不接受抗議喔！這是為了健康和工作效率著想而做出的決定。",
  ui_story_5037_50370901_34_dialog_content = "但是，我是妳的製作人，我不在的話，妳要怎麼辦？",
  ui_story_5037_50370901_35_dialog_content = "你放心吧，我之前都是自己當自己的製作人，這點小事難不倒我。",
  ui_story_5037_50370901_36_dialog_content = "快去休息吧，明天早上之前都不用來事務所！",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>砰</color>",
  ui_story_5037_50370901_38_dialog_content = "（被歌爾蒂強行推出門了呢……）",
  ui_story_5037_50370901_39_dialog_content = "（那就稍微散個步，休息一下好了。）",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>幾分鐘後·咖啡廳內</color>",
  ui_story_5037_50370901_41_dialog_content = "您想點些什麼？",
  ui_story_5037_50370901_42_dialog_content = "我先看看菜單……",
  ui_story_5037_50370901_43_dialog_content = "三色蛋糕？",
  ui_story_5037_50370901_44_dialog_content = "我們的目標是在規定的期限內，成功舉辦三場演唱會。",
  ui_story_5037_50370901_45_dialog_content = "接下來還要辦兩場啊……",
  ui_story_5037_50370901_46_dialog_content = "怎麼又開始想這些了，看菜單看菜單！",
  ui_story_5037_50370901_47_dialog_content = "這道甜品叫雙子……蛋糕？",
  ui_story_5037_50370901_48_dialog_content = "演出開始後，兩座舞台下方的觀眾可以根據自己喜好，在舞台之間自由流動。",
  ui_story_5037_50370901_49_dialog_content = "最終誰的舞台能留住更多的觀眾駐足，誰就是獲勝的一方。",
  ui_story_5037_50370901_50_dialog_content = "哎，要如何才能更加吸引觀眾目光呢……",
  ui_story_5037_50370901_51_dialog_content = "那隻叫做凱羅的神奇動物有這麼大的威力嗎？",
  ui_story_5037_50370901_52_dialog_content = "我是不是也該找一隻凱羅來咬咬自己的腳後跟了……",
  ui_story_5037_50370901_53_dialog_content = "果然還是沒辦法安心！",
  ui_story_5037_50370901_54_dialog_content = "不好意思，我先看看，您先忙。",
  ui_story_5037_50370901_55_dialog_content = "好的，如果有需要，請隨時叫我。",
  ui_story_5037_50370901_56_dialog_content = "就算不在事務所，腦子裡面想的也都是即將到來的考核演唱會……",
  ui_story_5037_50370901_57_dialog_content = "一想到還沒有幫歌爾蒂安排明天的行程，我的心情就會開始焦慮。",
  ui_story_5037_50370901_58_dialog_content = "唉，一旦心裡有了擔憂的事，咖啡和現烤蛋糕都食之無味了。",
  ui_story_5037_50370901_59_dialog_content = "也不知道歌爾蒂現在訓練得如何了……",
  ui_story_5037_50370901_60_dialog_content = "偷偷回去看一眼，應該沒關係吧？",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>偶像事務所外</color>",
  ui_story_5037_50370901_62_dialog_content = "到訓練室門口了，從這扇窗戶應該能看到裡面的情況。",
  ui_story_5037_50370901_63_dialog_content = "咦？那不是歌爾蒂嗎？她身邊的那個人是——",
  ui_story_5037_50370901_64_dialog_content = "您就是大偶像歌爾蒂吧？我是《八卦吃瓜瓜》的記者。",
  ui_story_5037_50370901_65_dialog_content = "我剛才看到您砰的一下把製作人關在了事務所的門外。",
  ui_story_5037_50370901_66_dialog_content = "聽說這是因為您和您的製作人關係不和，他拒絕繼續協助您，這是真的嗎？",
  ui_story_5037_50370901_67_dialog_content = "我與PlayerName的合作非常順利，我們的關係也一直非常友好。",
  ui_story_5037_50370901_68_dialog_content = "那您怎麼解釋我剛才看到的那一幕？",
  ui_story_5037_50370901_69_dialog_content = "您的製作人被您趕出事務所，孤零零地站在街上，那身影真是孤單可憐！",
  ui_story_5037_50370901_70_dialog_content = "那是因為——",
  ui_story_5037_50370901_71_dialog_content = "糟了，是那個怎麼甩都甩不掉的煩人狗仔！",
  ui_story_5037_50370901_72_dialog_content = "歌爾蒂沒有見過這個記者，還沒有應付他的經驗，再這樣下去，那傢伙又要胡亂報導了！",
  ui_story_5037_50370901_73_dialog_content = "得去幫歌爾蒂才行！",
  ui_story_5037_50370901_74_dialog_content = "製作人真是可憐，就這樣被您拒之門外，沒有任何的——",
  ui_story_5037_50370901_75_dialog_content = "你們，在說什麼呢？",
  ui_story_5037_50370901_76_dialog_content = "PlayerName！？",
  ui_story_5037_50370901_77_dialog_content = "是……是你！？",
  ui_story_5037_50370901_78_dialog_content = "我剛才似乎聽到你說，我和歌爾蒂關係不和？",
  ui_story_5037_50370901_79_option_content = "堅決否認",
  ui_story_5037_50370901_80_dialog_content = "無稽之談，我和歌爾蒂可是黃金搭檔！",
  ui_story_5037_50370901_81_option_content = "努力解釋",
  ui_story_5037_50370901_82_dialog_content = "我們的合作非常有默契，關係也很好。",
  ui_story_5037_50370901_83_dialog_content = "呃！",
  ui_story_5037_50370901_84_dialog_content = "沒錯！",
  ui_story_5037_50370901_85_dialog_content = "你若敢造謠生事，就等著挨罰吧！",
  ui_story_5037_50370901_86_dialog_content = "我……我知道了！",
  ui_story_5037_50370901_87_dialog_content = "對不起，我這就走！",
  ui_story_5037_50370901_88_dialog_content = "呼……PlayerName，幸虧你回來了。",
  ui_story_5037_50370901_89_dialog_content = "不然還真不知道該拿出什麼樣的證據，我才能有力反駁那個傢伙。",
  ui_story_5037_50370901_90_dialog_content = "我也沒想到，現在的八卦記者竟然這麼「敬業」。",
  ui_story_5037_50370901_91_dialog_content = "我只離開一下子，他就跑來準備造謠了。",
  ui_story_5037_50370901_92_dialog_content = "說起來，PlayerName你現在不是應該還在休息嗎？",
  ui_story_5037_50370901_93_dialog_content = "怎麼又跑回事務所來了？",
  ui_story_5037_50370901_94_dialog_content = "我……這是因為我……",
  ui_story_5037_50370901_95_dialog_content = "唉，就算妳要我好好休息，我也總是沒辦法放下心休息。",
  ui_story_5037_50370901_96_dialog_content = "說實話，我很擔心不久之後的考核演唱會。",
  ui_story_5037_50370901_97_dialog_content = "只要一想到它，我就吃不下飯、喝不下水，更別提好好休息了。",
  ui_story_5037_50370901_98_dialog_content = "原來是這樣嗎？",
  ui_story_5037_50370901_99_dialog_content = "所以，還是先通過考核演唱會，之後再好好休息吧？",
  ui_story_5037_50370901_100_dialog_content = "唔……",
  ui_story_5037_50370901_101_dialog_content = "其實，我也有類似的感覺。",
  ui_story_5037_50370901_102_dialog_content = "明明之前自己一個人的時候都能順利應付八卦記者，保護自己不受虛假報導困擾。",
  ui_story_5037_50370901_103_dialog_content = "但是，自從和PlayerName搭檔以後，我就逐漸開始依靠你來幫忙處理這些。",
  ui_story_5037_50370901_104_dialog_content = "現在再讓我去應付他們，已經變得有些生疏了。",
  ui_story_5037_50370901_105_dialog_content = "是我讓妳變弱了嗎……？",
  ui_story_5037_50370901_106_dialog_content = "不！PlayerName的出現反而讓我變強了喔！",
  ui_story_5037_50370901_107_dialog_content = "自從和你搭檔以後，我能夠專注於訓練，各項能力都在飛速提升！",
  ui_story_5037_50370901_108_dialog_content = "現在的我已經不是從前的我了，而是歌爾蒂☆超級進化了！",
  ui_story_5037_50370901_109_dialog_content = "太好了，還好我沒有拖妳後腿！",
  ui_story_5037_50370901_110_dialog_content = "PlayerName這麼優秀的製作人，才不會拖後腿呢！",
  ui_story_5037_50370901_111_dialog_content = "但是，關於休息的事情……",
  ui_story_5037_50370901_112_dialog_content = "不用擔心我，雖然很忙碌，但我保證會按時睡覺和鍛鍊身體，不會有問題的！",
  ui_story_5037_50370901_113_dialog_content = "那這一次，我也會聽從製作人的決定！",
  ui_story_5037_50370901_114_dialog_content = "我相信你！",
  ui_story_5037_50371001_1_dialog_content = "終於通過考核演唱會了！",
  ui_story_5037_50371001_2_dialog_content = "太好了！最大的考驗終於過去了！",
  ui_story_5037_50371001_3_dialog_content = "一旦放鬆下來，疲憊的感覺就會湧現呢……",
  ui_story_5037_50371001_4_dialog_content = "那就利用今天的時間，好好休息吧！",
  ui_story_5037_50371001_5_dialog_content = "嗯！也是要好好休息一下了。",
  ui_story_5037_50371001_6_dialog_content = "那麼，要做些什麼好呢？",
  ui_story_5037_50371001_7_dialog_content = "對了，PlayerName，想聽我唱歌嗎？",
  ui_story_5037_50371001_8_dialog_content = "我為之後的「畢業演唱會」準備了新歌喔！",
  ui_story_5037_50371001_9_dialog_content = "雖然副歌還沒有全部寫好，但其他部分已經沒問題了。",
  ui_story_5037_50371001_10_dialog_content = "好啊！歌爾蒂寫的新歌，一定很好聽。",
  ui_story_5037_50371001_11_dialog_content = "那我唱啦。",
  ui_story_5037_50371001_12_dialog_content = "♪即使暫時分別也沒關係",
  ui_story_5037_50371001_13_dialog_content = "♪相隔遙遠距離的我們，被同一顆星星照耀著",
  ui_story_5037_50371001_14_dialog_content = "♪不要為此哭泣，因為未來還在前方",
  ui_story_5037_50371001_15_dialog_content = "♪告別的歌，也是再次相見的約定",
  ui_story_5037_50371001_16_dialog_content = "（好好聽啊……）",
  ui_story_5037_50371001_17_dialog_content = "（但是，歌詞提到了分別，旋律也比歌爾蒂之前唱過的歌更柔和。）",
  ui_story_5037_50371001_18_dialog_content = "PlayerName，怎麼樣？",
  ui_story_5037_50371001_19_option_content = "很好聽！",
  ui_story_5037_50371001_20_dialog_content = "謝謝誇獎！",
  ui_story_5037_50371001_21_option_content = "感覺和之前的歌不太一樣？",
  ui_story_5037_50371001_22_dialog_content = "咦？你聽出來啦。",
  ui_story_5037_50371001_23_dialog_content = "畢竟是為「畢業演唱會」準備的歌，當然要懷著全心全意的感激來寫啦！",
  ui_story_5037_50371001_24_dialog_content = "但是，這首歌中除了感激，似乎也有別的感情？",
  ui_story_5037_50371001_25_dialog_content = "更像是傷心或不捨？我不太確定……",
  ui_story_5037_50371001_26_dialog_content = "因為這是一首關於告別的歌啊。",
  ui_story_5037_50371001_27_dialog_content = "告別？歌爾蒂要和誰告別？",
  ui_story_5037_50371001_28_dialog_content = "而且我一直不太明白，「畢業演唱會」中的「畢業」究竟是什麼意思？",
  ui_story_5037_50371001_29_dialog_content = "所謂的畢業就是退出偶像事務所，不再當偶像的意思喔。",
  ui_story_5037_50371001_30_dialog_content = "所以畢業演唱會也是對粉絲的告別演唱會。",
  ui_story_5037_50371001_31_dialog_content = "啊！？",
  ui_story_5037_50371001_32_dialog_content = "這不就代表，歌爾蒂在這次演唱會之後，就不當偶像了？",
  ui_story_5037_50371001_33_dialog_content = "不會那麼早，我的偶像之路可還很漫長的！",
  ui_story_5037_50371001_34_dialog_content = "這只是為了拍宣傳片才特別設定的啦，不是真正的「畢業演唱會」！",
  ui_story_5037_50371001_35_dialog_content = "是為了讓新人製作人PlayerName，體驗製作人陪伴偶像從出道到畢業的過程！",
  ui_story_5037_50371001_36_dialog_content = "之後我還是會繼續當偶像喔！",
  ui_story_5037_50371001_37_dialog_content = "嚇死我了……",
  ui_story_5037_50371001_38_dialog_content = "我還以為歌爾蒂以後就不當偶像了呢。",
  ui_story_5037_50371001_39_dialog_content = "才不是呢！",
  ui_story_5037_50371001_40_dialog_content = "對現在的我來說，這更像是一個具有總結意義的演唱會。",
  ui_story_5037_50371001_41_dialog_content = "對這段時間裡，我和PlayerName共同經歷的事情和取得的進步的總結！",
  ui_story_5037_50371001_42_dialog_content = "原來如此。",
  ui_story_5037_50371001_43_dialog_content = "我還真想像不出來歌爾蒂不當偶像的樣子呢……",
  ui_story_5037_50371001_44_dialog_content = "歌爾蒂在我心中的形象，已經完完全全和「偶像」分不開了呢。",
  ui_story_5037_50371001_45_dialog_content = "能聽PlayerName這麼說，我很高興！",
  ui_story_5037_50371001_46_dialog_content = "這代表我的偶像形像已經深植人心了！",
  ui_story_5037_50371001_47_dialog_content = "不過就算是這樣，在「偶像」這層身分之下，我仍是一個普通人。",
  ui_story_5037_50371001_48_dialog_content = "終有一天，我也會迎來真正的「畢業演唱會」，向粉絲們告別，不再當偶像了。",
  ui_story_5037_50371001_49_dialog_content = "別說這麼感傷的話題……",
  ui_story_5037_50371001_50_dialog_content = "感傷嗎？我不覺得喔。",
  ui_story_5037_50371001_51_dialog_content = "欸？",
  ui_story_5037_50371001_52_dialog_content = "畢竟這是每個偶像的必經之路，就算不去想，也終究會來臨。",
  ui_story_5037_50371001_53_dialog_content = "相比逃避，我更願意去努力思考，要怎麼辦好這場終究會到來的「畢業演唱會」！",
  ui_story_5037_50371001_54_dialog_content = "該怎麼做，才能讓自己和粉絲的大家不留遺憾。",
  ui_story_5037_50371001_55_dialog_content = "該怎麼做，才能讓自己最後的、最耀眼的光芒永遠映在粉絲的心中。",
  ui_story_5037_50371001_56_dialog_content = "為此我可是會從出道一直努力到畢業哦！",
  ui_story_5037_50371001_57_dialog_content = "真不愧是歌爾蒂！",
  ui_story_5037_50371001_58_dialog_content = "如果歌爾蒂不當偶像了，會做什麼呢？",
  ui_story_5037_50371001_59_dialog_content = "嗯……我還沒想好！",
  ui_story_5037_50371001_60_dialog_content = "我想過很多，不過，最想做的事情還是開寵物咖啡廳！",
  ui_story_5037_50371001_61_dialog_content = "因為這樣就能一邊工作一邊陪伴棉花糖，不會讓它感到孤單了！",
  ui_story_5037_50371001_62_dialog_content = "這個主意真不錯！",
  ui_story_5037_50371001_63_dialog_content = "能一邊和小動物玩耍一邊喝咖啡，真是太幸福了。",
  ui_story_5037_50371001_64_dialog_content = "我也這麼覺得！",
  ui_story_5037_50371001_65_dialog_content = "每次感到累的時候，只要摸摸棉花糖柔軟的毛毛，我就會覺得輕鬆很多。",
  ui_story_5037_50371001_66_dialog_content = "如果說偶像是用唱歌跳舞帶給大家歡樂的話……",
  ui_story_5037_50371001_67_dialog_content = "開寵物咖啡廳，就是和小動物們一起帶給大家溫暖和幸福！",
  ui_story_5037_50371001_68_dialog_content = "不管哪種生活，都是我喜歡的！",
  ui_story_5037_50371101_1_dialog_content = "（今天在事務所發現一封維克給我的信。）",
  ui_story_5037_50371101_2_dialog_content = "（信上說，讓我今天一個人在舞蹈訓練室等著，有些事要向我問清楚。）",
  ui_story_5037_50371101_3_dialog_content = "你果然來了！",
  ui_story_5037_50371101_4_dialog_content = "嗯？這個聲音是菲雅？",
  ui_story_5037_50371101_5_dialog_content = "唉喲……唉喲喲……菲雅，慢點，不要扯為師的耳朵！",
  ui_story_5037_50371101_6_dialog_content = "你們這是在做什麼？",
  ui_story_5037_50371101_7_dialog_content = "我明明已經對小菲雅說不要這麼做了。",
  ui_story_5037_50371101_8_dialog_content = "就算PlayerName和我師父是朋友，這種事情也要講清楚才行吧！",
  ui_story_5037_50371101_9_dialog_content = "所以，到底是什麼事啊？",
  ui_story_5037_50371101_10_dialog_content = "PlayerName，那個每天都往這邊跑的八卦記者到底是怎麼回事？",
  ui_story_5037_50371101_11_dialog_content = "八卦記者？",
  ui_story_5037_50371101_12_dialog_content = "啊，妳是說那個滿臉鬍子，一看就不是正經人士的大叔？",
  ui_story_5037_50371101_13_dialog_content = "沒錯，你果然知道他！",
  ui_story_5037_50371101_14_dialog_content = "那個傢伙每天都往訓練室跑，打擾廢柴師父訓練。",
  ui_story_5037_50371101_15_dialog_content = "而且每天把他轟走以後，第二天就會出現詆毀廢柴師父，誇獎歌爾蒂的報導！",
  ui_story_5037_50371101_16_dialog_content = "這傢伙真的不是你們派來的嗎？",
  ui_story_5037_50371101_17_dialog_content = "怎麼可能是我派的……",
  ui_story_5037_50371101_18_dialog_content = "我和歌爾蒂每天都被他煩得不行！",
  ui_story_5037_50371101_19_dialog_content = "是嗎？",
  ui_story_5037_50371101_20_dialog_content = "哎呀，我就說不是了。",
  ui_story_5037_50371101_21_dialog_content = "那份報紙上除了刊登過詆毀我的消息，也刊登過攻擊歌爾蒂的新聞啊。",
  ui_story_5037_50371101_22_dialog_content = "是……是嗎？",
  ui_story_5037_50371101_23_dialog_content = "我每次只會仔細閱讀關於廢柴師父的報導……",
  ui_story_5037_50371101_24_dialog_content = "這麼一說，除了詆毀歌爾蒂，我似乎也看過詆毀維克的報導。",
  ui_story_5037_50371101_25_dialog_content = "如果不是你們的話，那個八卦記者究竟是誰派來的？",
  ui_story_5037_50371101_26_dialog_content = "大概是他自己覺得這裡有八卦可寫，所以才摸過來的吧。",
  ui_story_5037_50371101_27_dialog_content = "我每次離開事務所前都會關緊訓練室的門窗，但他還是不知道從哪裡鑽進來。",
  ui_story_5037_50371101_28_dialog_content = "真是太煩人了！",
  ui_story_5037_50371101_29_dialog_content = "沒錯沒錯，還害我們失去粉絲！",
  ui_story_5037_50371101_30_dialog_content = "原來這是一場誤會……",
  ui_story_5037_50371101_31_dialog_content = "對不起。",
  ui_story_5037_50371101_32_dialog_content = "沒關係，不用在意。你們還有別的事嗎？",
  ui_story_5037_50371101_33_dialog_content = "沒有了，我要帶廢柴師父回去訓練了。",
  ui_story_5037_50371101_34_dialog_content = "你們也要加油。",
  ui_story_5037_50371101_35_dialog_content = "嗯，那就——",
  ui_story_5037_50371101_36_dialog_content = "<size=45>等等！</size>",
  ui_story_5037_50371101_37_dialog_content = "欸？又怎麼了？",
  ui_story_5037_50371101_38_dialog_content = "不瞞你說，PlayerName，我還有一事相求。",
  ui_story_5037_50371101_39_dialog_content = "你……你說說看？",
  ui_story_5037_50371101_40_dialog_content = "請你教我該怎麼應付八卦記者！",
  ui_story_5037_50371101_41_dialog_content = "唔哇！？你你你，離我遠點！",
  ui_story_5037_50371101_42_dialog_content = "不要用我的頭帶擦眼淚啊！",
  ui_story_5037_50371101_43_dialog_content = "嗚嗚……",
  ui_story_5037_50371101_44_dialog_content = "那個八卦記者每次都會放出很多不實報導，害得我失去粉絲！",
  ui_story_5037_50371101_45_dialog_content = "為了彌補減少的粉絲數量，我只能更加拼命地訓練和進行偶像活動。",
  ui_story_5037_50371101_46_dialog_content = "就連菲雅也不放過我，每次都盯著我訓練，連一點偷懶的時間都沒有。",
  ui_story_5037_50371101_47_dialog_content = "上次我想稍微休息一下的時候，菲雅竟然叫凱羅咬我的腿！",
  ui_story_5037_50371101_48_dialog_content = "我的腿已經被它咬得坑坑巴巴的了，嗚嗚，PlayerName，你要救救我——",
  ui_story_5037_50371101_49_dialog_content = "好了好了，我教，我教！",
  ui_story_5037_50371101_50_dialog_content = "我就知道PlayerName一定不會放著我不管的！",
  ui_story_5037_50371101_51_dialog_content = "該從哪裡開始呢……",
  ui_story_5037_50371101_52_dialog_content = "讓我看看這期的《八卦吃瓜瓜》寫了什麼吧——",
  ui_story_5037_50371101_53_dialog_content = "「維克曾聲稱自己是永遠的十八歲，實際年齡遠大於此！？」",
  ui_story_5037_50371101_54_dialog_content = "呃，怎麼感覺這確實像是維克會說的話。",
  ui_story_5037_50371101_55_dialog_content = "你說那次啊，我記得！我確實說自己是永遠的十八歲。",
  ui_story_5037_50371101_56_dialog_content = "這怎麼聽都不像是真話吧！",
  ui_story_5037_50371101_57_dialog_content = "我的年齡可是祕密哦~",
  ui_story_5037_50371101_58_dialog_content = "好吧，那下次你只需要堅持這是不能透露的祕密就好了。",
  ui_story_5037_50371101_59_dialog_content = "但那篇報導還寫說：「維克認為自己比當紅偶像歌爾蒂更加年輕有活力！」",
  ui_story_5037_50371101_60_dialog_content = "嗯？這句可不是我說的！那是他誇我的時候說的話。",
  ui_story_5037_50371101_61_dialog_content = "你是怎麼回答的？",
  ui_story_5037_50371101_62_dialog_content = "誇讚的話，我當然是認同了！",
  ui_story_5037_50371101_63_dialog_content = "你順著他的話回應，不就是在雙手奉上抹黑你的藉口嗎？",
  ui_story_5037_50371101_64_dialog_content = "那……那要怎麼回答？",
  ui_story_5037_50371101_65_dialog_content = "他這是在給你下圈套，讓你承認自己比別人優秀。",
  ui_story_5037_50371101_66_dialog_content = "以後再遇到這種情況就要謙虛，說別人比自己更優秀，這樣八卦記者才會沒辦法有機可趁！",
  ui_story_5037_50371101_67_dialog_content = "好吧好吧，我下次注意！",
  ui_story_5037_50371101_68_dialog_content = "我再看看……",
  ui_story_5037_50371101_69_dialog_content = "「維克的製作人使用危險的野生動物，威脅手無寸鐵的記者？」",
  ui_story_5037_50371101_70_dialog_content = "菲雅，這是妳吧？",
  ui_story_5037_50371101_71_dialog_content = "看……看我幹嘛？",
  ui_story_5037_50371101_72_dialog_content = "我只是覺得那傢伙太煩了，讓凱羅叼起他扔到大街上了而已！",
  ui_story_5037_50371101_73_dialog_content = "下回可別這麼做了。",
  ui_story_5037_50371101_74_dialog_content = "就算八卦記者再煩人，也不能用暴力手段對付他們。",
  ui_story_5037_50371101_75_dialog_content = "那樣只會留下把柄，讓他們更加肆無忌憚地報導。",
  ui_story_5037_50371101_76_dialog_content = "那要怎麼應付他們？",
  ui_story_5037_50371101_77_dialog_content = "趕也趕不走，防也防不住，簡直比野外的蚊子還討厭！",
  ui_story_5037_50371101_78_dialog_content = "這種時候只需要堅持不接受採訪，嚴正拒絕就行了。",
  ui_story_5037_50371101_79_dialog_content = "這樣的話，就算他們做出抹黑維克的報導，也會因為無憑無據而不可信。",
  ui_story_5037_50371101_80_dialog_content = "還有就是，要繼續提升維克的實力，在實力面前，一切抹黑都會顯得無力。",
  ui_story_5037_50371101_81_dialog_content = "好吧，我知道了。",
  ui_story_5037_50371101_82_dialog_content = "謝謝你，PlayerName，你可真是救了我的命！",
  ui_story_5037_50371101_83_dialog_content = "沒問題，雖然現在是對手，但我們依然還是朋友。",
  ui_story_5037_50371101_84_dialog_content = "我不會因為比賽這種事情，就讓朋友處於困擾之中呢！",
  ui_story_5037_50371101_85_dialog_content = "嗚嗚，你真是個大好人！",
  ui_story_5037_50371101_86_dialog_content = "PlayerName，這次謝謝你了……",
  ui_story_5037_50371101_87_dialog_content = "身為偶像兼神奇動物專家，我也不會讓你白白幫忙的！",
  ui_story_5037_50371101_88_dialog_content = "菲雅之前在研究如何當製作人的時候找到兩本書，應該對你有用。",
  ui_story_5037_50371101_89_dialog_content = "你挑一本吧，當作幫忙的報酬。",
  ui_story_5037_50371101_90_dialog_content = "這不是我的書嗎？原來被你藏在衣服裡了！難怪找不到！",
  ui_story_5037_50371101_91_dialog_content = "不過現在這兩本書對我也沒用了，PlayerName，你就放心挑吧。",
  ui_story_5037_50371101_92_dialog_content = "謝謝，那我就拿這本吧——",
  ui_story_5037_50371101_93_option_content = "《新人偶像速成法》",
  ui_story_5037_50371101_94_option_content = "《職業製作人的自我修養》",
  ui_story_5037_50371101_95_dialog_content = "好，那我們也回去了！",
  ui_story_5037_50371101_96_dialog_content = "走了，廢柴師父，回去繼續訓練！",
  ui_story_5037_50371101_97_dialog_content = "欸！？還……還來啊！？",
  ui_story_5037_50371101_98_dialog_content = "當然了，接下來要把剛才與PlayerName聊天花掉的時間都補回來！",
  ui_story_5037_50371101_99_dialog_content = "饒——了——我——吧——",
  ui_story_5037_50371201_1_dialog_content = "明明是準備考核演唱會的關鍵時期，維克卻約我在這裡等他。",
  ui_story_5037_50371201_2_dialog_content = "而且還要我別告訴菲雅，一個人悄悄地來！",
  ui_story_5037_50371201_3_dialog_content = "他到底在謀劃什麼呢？",
  ui_story_5037_50371201_4_dialog_content = "哎呀，我就知道PlayerName是個守時的人！",
  ui_story_5037_50371201_5_dialog_content = "維克，你把我叫出來，到底是想做什麼？",
  ui_story_5037_50371201_6_dialog_content = "其實也沒什麼特別緊急的事情啦，就是——",
  ui_story_5037_50371201_7_dialog_content = "請讓我在這裡躲個一天！",
  ui_story_5037_50371201_8_dialog_content = "哈……！？",
  ui_story_5037_50371201_9_dialog_content = "馬上就要到考核演唱會的日子了，你不去訓練，在這裡藏著幹嘛？",
  ui_story_5037_50371201_10_dialog_content = "事情就是出在訓練上，你先聽聽我每天的行程吧……",
  ui_story_5037_50371201_11_dialog_content = "每天早上太陽還沒出來的時候，我就會被菲雅叫醒訓練。",
  ui_story_5037_50371201_12_dialog_content = "臭師父，趕快起床訓練！",
  ui_story_5037_50371201_13_dialog_content = "首先是繞著整座森林跑十圈，鍛鍊體能！",
  ui_story_5037_50371201_14_dialog_content = "睏……好睏……呼啊——",
  ui_story_5037_50371201_15_dialog_content = "能不能讓我再睡一會兒……",
  ui_story_5037_50371201_16_dialog_content = "不想起床？也行啊，凱羅，咬他！",
  ui_story_5037_50371201_17_dialog_content = "囉——！",
  ui_story_5037_50371201_18_dialog_content = "嗷！！！",
  ui_story_5037_50371201_19_dialog_content = "別、別咬我了！我馬上起床！",
  ui_story_5037_50371201_20_dialog_content = "跑完步之後是盥洗和吃早飯的時間。",
  ui_story_5037_50371201_21_dialog_content = "今天的早飯是鋸末麵包配牛奶和水煮胡蘿蔔！",
  ui_story_5037_50371201_22_dialog_content = "已經連續吃了三天水煮胡蘿蔔了，就不能換換口味嗎……",
  ui_story_5037_50371201_23_dialog_content = "比如烤得滋滋冒油的、刷滿辣醬的沙蟲肉烤串。",
  ui_story_5037_50371201_24_dialog_content = "你現在是一個偶像，偶像就要好好管理自己的身材！午飯和晚飯也都是水煮胡蘿蔔！",
  ui_story_5037_50371201_25_dialog_content = "嗚！",
  ui_story_5037_50371201_26_dialog_content = "還有——",
  ui_story_5037_50371201_27_dialog_content = "呃，我大概已經能想像你的悲慘遭遇了……",
  ui_story_5037_50371201_28_dialog_content = "所以，為了我的人身安全著想，PlayerName，請讓我藏在這裡休息一天吧！",
  ui_story_5037_50371201_29_dialog_content = "真的只要一天就好，現在這種日子根本不是光靈過的！",
  ui_story_5037_50371201_30_dialog_content = "再這麼下去，這個世界就要失去一位偉大的神奇動物專家了！",
  ui_story_5037_50371201_31_dialog_content = "你……唉……",
  ui_story_5037_50371201_32_dialog_content = "菲雅為了讓你能夠完成考核下足了功夫，但是她的訓練也確實有一點太嚴苛了。",
  ui_story_5037_50371201_33_dialog_content = "我可以讓你在這裡休息一會，但你得答應我兩個條件——",
  ui_story_5037_50371201_34_dialog_content = "休息好了早點回去找你的製作人，不要讓她擔心。",
  ui_story_5037_50371201_35_dialog_content = "還有就是，把你認為承受不了的訓練和菲雅好好說清楚。",
  ui_story_5037_50371201_36_dialog_content = "沒問題！只要能讓我偷……不對，休息一天，不管什麼條件我都答應！",
  ui_story_5037_50371201_37_dialog_content = "那你好好休息吧，我等一下還要幫歌爾蒂安排今天的行程，就先不管你了。",
  ui_story_5037_50371201_38_dialog_content = "嗯嗯，你去忙吧，我自己一個人就可以！",
  ui_story_5037_50371201_39_dialog_content = "這張沙發看起來真不錯，很適合睡覺。",
  ui_story_5037_50371201_40_dialog_content = "小毛球，變大吧，讓我抱著你睡一會兒~",
  ui_story_5037_50371201_41_dialog_content = "嗚啾！",
  ui_story_5037_50371201_42_dialog_content = "呼……呼……",
  ui_story_5037_50371201_43_dialog_content = "（竟然這麼快就睡著了，真不愧是維克……）",
  ui_story_5037_50371201_44_dialog_content = "（那麼，我也要接著工作了。）",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371201_46_dialog_content = "（行程安排得差不多了，這份工作我也越來越得心應手了呢！）",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>咚咚咚！</color>",
  ui_story_5037_50371201_48_dialog_content = "（嗯？有人在敲門？）",
  ui_story_5037_50371201_49_dialog_content = "是誰啊？",
  ui_story_5037_50371201_50_dialog_content = "PlayerName，是我，菲雅！",
  ui_story_5037_50371201_51_dialog_content = "（是菲雅！？）",
  ui_story_5037_50371201_52_dialog_content = "（等一下，維克還在這裡呢！）",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>咚咚咚！</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName？",
  ui_story_5037_50371201_55_dialog_content = "稍等，馬上就來！",
  ui_story_5037_50371201_56_dialog_content = "維克，快醒醒！",
  ui_story_5037_50371201_57_dialog_content = "呼……哈，小毛球，哈哈，別鬧……",
  ui_story_5037_50371201_58_dialog_content = "怎麼睡得比我還熟啊！？",
  ui_story_5037_50371201_59_dialog_content = "（沒辦法了，只能先把他藏起來了。）",
  ui_story_5037_50371201_60_dialog_content = "（我看看，這邊的雜誌堆似乎不錯，就把維克藏在裡面好了！）",
  ui_story_5037_50371201_61_dialog_content = "來了來了，菲雅，我這就來！",
  ui_story_5037_50371201_62_dialog_content = "怎麼這麼慢啊？",
  ui_story_5037_50371201_63_dialog_content = "抱歉抱歉，我剛才在……在整理房間！",
  ui_story_5037_50371201_64_dialog_content = "你這裡這麼亂，雜物都堆成山了，確實要好好收拾一下。",
  ui_story_5037_50371201_65_dialog_content = "啊哈哈……說起來，菲雅，妳找我有什麼事嗎？",
  ui_story_5037_50371201_66_dialog_content = "你有沒有看到維克師父？",
  ui_story_5037_50371201_67_dialog_content = "啊……啊？沒、沒有啊。",
  ui_story_5037_50371201_68_dialog_content = "嗯？",
  ui_story_5037_50371201_69_dialog_content = "我一直在這裡收拾東西，還要安排歌爾蒂的行程，確實沒有看到維克。",
  ui_story_5037_50371201_70_dialog_content = "唉，好吧。沒想到他竟然沒來找你，真是奇怪。",
  ui_story_5037_50371201_71_dialog_content = "廢柴師父究竟跑到哪裡去了……",
  ui_story_5037_50371201_72_dialog_content = "說不定他只是跑出去偷個懶，過不了多久就會回來了。",
  ui_story_5037_50371201_73_dialog_content = "剩沒幾天就是考核演唱會了，這個傢伙竟然還有心情偷懶。",
  ui_story_5037_50371201_74_dialog_content = "等他回來，一定要好好訓練才行。",
  ui_story_5037_50371201_75_dialog_content = "會不會就是因為訓練太嚴苛了，所以維克才不見的？",
  ui_story_5037_50371201_76_dialog_content = "菲雅的訓練一向以嚴格著稱，這雖然不錯，但也要注意訓練和休息的平衡。",
  ui_story_5037_50371201_77_dialog_content = "是嗎？",
  ui_story_5037_50371201_78_dialog_content = "明明我今天還打算放他一天假，讓他好好休息的呢……",
  ui_story_5037_50371201_79_dialog_content = "結果他竟然不見了，我跑遍了整個影鎮都沒找到他。",
  ui_story_5037_50371201_80_dialog_content = "（原來菲雅打算給維克放假嗎？看來她也有妥當安排維克的訓練計畫。）",
  ui_story_5037_50371201_81_dialog_content = "妳也別太擔心，我會找大家幫妳一起找的。",
  ui_story_5037_50371201_82_dialog_content = "嗯，那我再去找找師父。",
  ui_story_5037_50371201_83_dialog_content = "等一下，這是……",
  ui_story_5037_50371201_84_dialog_content = "（糟了，菲雅注意到藏著維克的書堆了！）",
  ui_story_5037_50371201_85_dialog_content = "呃！這……這是我之前看的雜誌，還沒來得及收拾，我一會兒就——",
  ui_story_5037_50371201_86_dialog_content = "這堆雜誌怎麼看起來鼓鼓的？而且裡面好像還埋著什麼。",
  ui_story_5037_50371201_87_dialog_content = "先別——！",
  ui_story_5037_50371201_88_dialog_content = "廢柴師父！？",
  ui_story_5037_50371201_89_dialog_content = "呼……呼……",
  ui_story_5037_50371201_90_dialog_content = "他怎麼在這裡睡覺？",
  ui_story_5037_50371201_91_dialog_content = "PlayerName，你剛才是不是在騙我？",
  ui_story_5037_50371201_92_dialog_content = "我……呃……",
  ui_story_5037_50371201_93_option_content = "坦白",
  ui_story_5037_50371201_94_dialog_content = "好吧，我招了，我剛才確實騙了妳。",
  ui_story_5037_50371201_95_dialog_content = "對不起……",
  ui_story_5037_50371201_96_dialog_content = "沒關係，菲雅知道PlayerName不是有意騙菲雅的。",
  ui_story_5037_50371201_97_option_content = "辯解",
  ui_story_5037_50371201_98_dialog_content = "他大概是在我來之前就在這裡了，應該是這樣吧……",
  ui_story_5037_50371201_99_dialog_content = "PlayerName的表情，一看就是在說謊。",
  ui_story_5037_50371201_100_dialog_content = "不過菲雅已經猜到大概的情況了。",
  ui_story_5037_50371201_101_dialog_content = "一定是廢柴師父自己賴在你這裡不走的吧？",
  ui_story_5037_50371201_102_dialog_content = "實際上是這樣的……",
  ui_story_5037_50371201_103_dialog_content = "維克早上的時候來找我，希望能在這裡躲一陣，休息一下。",
  ui_story_5037_50371201_104_dialog_content = "嚴格的偶像訓練似乎使他很疲憊，他來這裡沒多久，就倒頭睡著了。",
  ui_story_5037_50371201_105_dialog_content = "廢柴師父就算瞞著我偷跑到你這裡休息，也不願意跟我說明情況……",
  ui_story_5037_50371201_106_dialog_content = "菲雅明明已經幫他安排好休息時間了！",
  ui_story_5037_50371201_107_dialog_content = "等他醒了再好好和他說吧？",
  ui_story_5037_50371201_108_dialog_content = "唉……算了，還是讓他在你這裡繼續休息吧。",
  ui_story_5037_50371201_109_dialog_content = "記得等他醒了，就讓他回來我這裡繼續訓練。",
  ui_story_5037_50371201_110_dialog_content = "之後我會整理一套偶像訓練技巧給你，就當是PlayerName照顧廢柴師父的謝禮了。",
  ui_story_5037_50371201_111_dialog_content = "嗯，放心吧！",
  ui_story_5037_50371201_112_dialog_content = "對了，還有，別把我來過的事情告訴他！",
  ui_story_5037_50371201_113_dialog_content = "為什麼？",
  ui_story_5037_50371201_114_dialog_content = "因為……",
  ui_story_5037_50371201_115_dialog_content = "<size=45>廢柴師父一點都不可靠！</size>",
  ui_story_5037_50371201_116_dialog_content = "咦！？",
  ui_story_5037_50371201_117_dialog_content = "一旦讓他知道我放了他一馬，他就會得寸進尺！",
  ui_story_5037_50371201_118_dialog_content = "不只會完全打亂已經養成的生活習慣，還會在訓練的時候找機會摸魚。",
  ui_story_5037_50371201_119_dialog_content = "對付這種人，唯一的方法就是嚴格監督，毫不留情！",
  ui_story_5037_50371201_120_dialog_content = "好……好的！",
  ui_story_5037_50371201_121_dialog_content = "等他一醒，我就把他送回去繼續訓練！",
  ui_story_5037_50371301_1_dialog_content = "沒想到，竟然會在這種時候遇到這樣的問題。",
  ui_story_5037_50371301_2_dialog_content = "我覺得這樣也未嘗不可哦~",
  ui_story_5037_50371301_3_dialog_content = "只有廢柴師父會覺得這樣的狀態不錯吧！",
  ui_story_5037_50371301_4_dialog_content = "PlayerName，情況真的已經如此嚴重了嗎？",
  ui_story_5037_50371301_5_dialog_content = "恐怕是的……",
  ui_story_5037_50371301_6_dialog_content = "我們正遭遇嚴重的危機！",
  ui_story_5037_50371301_7_dialog_content = "不管多麼努力，歌爾蒂和維克提升能力的速度，都開始變得緩慢了！",
  ui_story_5037_50371301_8_dialog_content = "也就是遇到了所謂的「平台期」！",
  ui_story_5037_50371301_9_dialog_content = "為了解決這個問題，以最好的狀態迎接「畢業演唱會」，我和菲雅想到了一個辦法！",
  ui_story_5037_50371301_10_dialog_content = "那就是——交換製作人！",
  ui_story_5037_50371301_11_dialog_content = "欸！？",
  ui_story_5037_50371301_12_dialog_content = "沒錯，由PlayerName來訓練廢柴師父，而我和歌爾蒂姐姐搭檔！",
  ui_story_5037_50371301_13_dialog_content = "然後進行為期一天的交換訓練！",
  ui_story_5037_50371301_14_dialog_content = "新的訓練方式、搭檔和環境有益於催生新靈感，有助於迅速突破平台期哦！",
  ui_story_5037_50371301_15_dialog_content = "也就是說，由我來訓練維克？",
  ui_story_5037_50371301_16_dialog_content = "哎呀？聽上去真不錯啊，這樣我就能稍微輕鬆一些了——",
  ui_story_5037_50371301_17_dialog_content = "痛痛痛！菲雅不要踩我的腳！",
  ui_story_5037_50371301_18_dialog_content = "為了防止師父偷懶，PlayerName，我會把凱羅也一起託付給你。",
  ui_story_5037_50371301_19_dialog_content = "囉！",
  ui_story_5037_50371301_20_dialog_content = "它會在師父偷懶的時候咬他的腿，提醒他好好訓練，所以你就放心吧。",
  ui_story_5037_50371301_21_dialog_content = "菲雅想得還真周全……",
  ui_story_5037_50371301_22_dialog_content = "那麼，就這麼愉快地決定啦。",
  ui_story_5037_50371301_23_dialog_content = "PlayerName，就像平時幫我安排訓練一樣，好好指導維克訓練吧！",
  ui_story_5037_50371301_24_dialog_content = "我相信你能做到的！",
  ui_story_5037_50371301_25_dialog_content = "嗯，就交給我吧。",
  ui_story_5037_50371301_26_dialog_content = "那我們先走啦。拜拜~",
  ui_story_5037_50371301_27_dialog_content = "那我也去休息——",
  ui_story_5037_50371301_28_dialog_content = "嗷！！！",
  ui_story_5037_50371301_29_dialog_content = "凱羅！快放開！我的腿不能吃！！！",
  ui_story_5037_50371301_30_dialog_content = "囉！",
  ui_story_5037_50371301_31_dialog_content = "它一定是見到你想偷懶，所以在努力阻止你吧。",
  ui_story_5037_50371301_32_dialog_content = "唉……真是有了菲雅就忘了我啊，凱羅……",
  ui_story_5037_50371301_33_dialog_content = "明明是為師把你從小養到大，教你生存的方法——",
  ui_story_5037_50371301_34_dialog_content = "嗷——！！！",
  ui_story_5037_50371301_35_dialog_content = "你還是趕快開始訓練吧，不然凱羅又要咬你了……",
  ui_story_5037_50371301_36_dialog_content = "嗚嗚，為什麼受傷的總是我……",
  ui_story_5037_50371301_37_dialog_content = "我安排的訓練都有適當的休息時間，不會為難你的。",
  ui_story_5037_50371301_38_dialog_content = "今天的第一項訓練是聲樂。",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371301_40_dialog_content = "♪又到了萬物復甦的春天♪",
  ui_story_5037_50371301_41_dialog_content = "♪動物們忙碌地走出家園♪",
  ui_story_5037_50371301_42_dialog_content = "♪無論在森林還是在那荒原♪",
  ui_story_5037_50371301_43_dialog_content = "好的，唱完這首歌就可以休息了。",
  ui_story_5037_50371301_44_dialog_content = "太好了！終於可以休息了！",
  ui_story_5037_50371301_45_dialog_content = "囉……",
  ui_story_5037_50371301_46_dialog_content = "這可不是偷懶哦，凱羅，這是真正的休息時間！",
  ui_story_5037_50371301_47_dialog_content = "說起來，我一直很好奇，為什麼你也會想當偶像呢？",
  ui_story_5037_50371301_48_dialog_content = "嗯？這句話從根本上就錯了喔。",
  ui_story_5037_50371301_49_dialog_content = "啊？",
  ui_story_5037_50371301_50_dialog_content = "因為我根本就不是偶像啊，我的身分只有神奇動物專家這一個~",
  ui_story_5037_50371301_51_dialog_content = "那你們是為了什麼參賽？",
  ui_story_5037_50371301_52_dialog_content = "完全是為了白夜幣喔！",
  ui_story_5037_50371301_53_dialog_content = "還真是為了獎金啊……",
  ui_story_5037_50371301_54_dialog_content = "雖然我能理解維克一直過著貧窮的生活，涉女士開出的獎金又很高……",
  ui_story_5037_50371301_55_dialog_content = "但為什麼連菲雅都參加了？",
  ui_story_5037_50371301_56_dialog_content = "因為是菲雅看到宣傳海報，拉著我一起來參加的啊。",
  ui_story_5037_50371301_57_dialog_content = "畢竟用來保護神奇動物的經費確實不夠了……",
  ui_story_5037_50371301_58_dialog_content = "有多不夠？",
  ui_story_5037_50371301_59_dialog_content = "比卡和蒼獅龍上個月的零食費還欠著呢！",
  ui_story_5037_50371301_60_dialog_content = "這麼慘！？",
  ui_story_5037_50371301_61_dialog_content = "不對，經濟上過不去就少吃點零食啊！",
  ui_story_5037_50371301_62_dialog_content = "那可不行！",
  ui_story_5037_50371301_63_dialog_content = "神奇動物們都是我的夥伴，我才捨不得讓它們吃苦呢~",
  ui_story_5037_50371301_64_dialog_content = "平時都是菲雅和詩燁在一邊研究一邊打工賺錢，還不至於走到欠錢的地步。",
  ui_story_5037_50371301_65_dialog_content = "但是之前我派菲雅去調查一種稀有的神奇動物，花了很長的時間也沒得到結果。",
  ui_story_5037_50371301_66_dialog_content = "收入沒辦法維持支出，所以欠了很多錢呢！",
  ui_story_5037_50371301_67_dialog_content = "那段時間，維克你在做什麼？",
  ui_story_5037_50371301_68_dialog_content = "我？當然是在照顧神奇動物，還有就是好好休息啦。",
  ui_story_5037_50371301_69_dialog_content = "那不就是完全沒有幫忙嗎！",
  ui_story_5037_50371301_70_dialog_content = "突然體會到菲雅和詩燁平時有多辛苦呢……",
  ui_story_5037_50371301_71_dialog_content = "我這不是也來幫忙賺錢了，而且還是作為登台表演的那個人哪！",
  ui_story_5037_50371301_72_dialog_content = "甚至還好好努力到了現在！",
  ui_story_5037_50371301_73_dialog_content = "是啊，確實少見，我還以為你會半途而廢，想辦法逃跑呢。",
  ui_story_5037_50371301_74_dialog_content = "這可是關乎神奇動物伙食費的大事，怎麼可能逃跑呢！",
  ui_story_5037_50371301_75_dialog_content = "如果是為了神奇動物，什麼困難我都不會退縮的。",
  ui_story_5037_50371301_76_dialog_content = "要是PlayerName給出夠多的報酬，我可以帶著菲雅和詩燁一起幫你跑腿！",
  ui_story_5037_50371301_77_dialog_content = "還是算了吧！你可別再給菲雅和詩燁添麻煩了。",
  ui_story_5037_50371301_78_dialog_content = "真搞不懂，有時候覺得你對兩個徒弟，還不如對小毛球用心呢。",
  ui_story_5037_50371301_79_dialog_content = "那你可就大錯特錯了，她們可是我為之自豪的徒弟喔！",
  ui_story_5037_50371301_80_dialog_content = "不僅承襲了我關於神奇動物的所有知識，也能賺錢養活自己。",
  ui_story_5037_50371301_81_dialog_content = "而且還很強大，就算遇到暗鬼也不會害怕~",
  ui_story_5037_50371301_82_dialog_content = "或許再過不久，我就能把全艾斯特拉的神奇動物研究課題交給她們了。",
  ui_story_5037_50371301_83_dialog_content = "那你要做什麼？找地方睡大覺？",
  ui_story_5037_50371301_84_dialog_content = "這個想法很不錯哦，我會考慮的！",
  ui_story_5037_50371301_85_dialog_content = "不過，在那之前我還有別的事情要做。",
  ui_story_5037_50371301_86_dialog_content = "這個世界上，除了艾斯特拉大陸以外，一定還有別的大陸存在。",
  ui_story_5037_50371301_87_dialog_content = "我想到那裡去，尋找更多的神奇動物，記錄並研究它們的特點。",
  ui_story_5037_50371301_88_dialog_content = "沒想到你的理想還挺遠大的……",
  ui_story_5037_50371301_89_dialog_content = "那當然了，畢竟我可是——",
  ui_story_5037_50371301_90_dialog_content = "嗷！！！",
  ui_story_5037_50371301_91_dialog_content = "凱羅，你怎麼又咬我！？",
  ui_story_5037_50371301_92_dialog_content = "我看看，休息時間已經結束，凱羅這是在提醒你開始訓練呢！",
  ui_story_5037_50371301_93_dialog_content = "凱羅，你跟著菲雅學壞了，竟然變得比她還嚴格！",
  ui_story_5037_50371301_94_dialog_content = "既然今天是由PlayerName擔任我的製作人，那能不能請你稍微延長一點休息時間呢？",
  ui_story_5037_50371301_95_dialog_content = "唔……",
  ui_story_5037_50371301_96_dialog_content = "我可以把小毛球借你摸一天！",
  ui_story_5037_50371301_97_dialog_content = "既然你都這麼說了，那麼今天的訓練就——",
  ui_story_5037_50371301_98_option_content = "加倍！",
  ui_story_5037_50371301_99_option_content = "超級加倍！",
  ui_story_5037_50371301_100_dialog_content = "我幫歌爾蒂制定了用來突破平台期的訓練計畫。",
  ui_story_5037_50371301_101_dialog_content = "只不過因為強度太高，所以一直沒有嘗試，正好拿維克你來測試效果！",
  ui_story_5037_50371301_102_dialog_content = "什麼！？",
  ui_story_5037_50371301_103_dialog_content = "別擔心，我只是想試驗一下效果，方便之後調整歌爾蒂的訓練強度。",
  ui_story_5037_50371301_104_dialog_content = "當然了，這也有助於提升你自己。",
  ui_story_5037_50371301_105_dialog_content = "為了不辜負菲雅的一片苦心，你就拼盡全力、努力訓練吧！",
  ui_story_5037_50371301_106_dialog_content = "不要啊——！！！",
  ui_story_5037_50371401_1_dialog_content = "PlayerName組的緊急會議，三、二、一、開拍！",
  ui_story_5037_50371401_2_dialog_content = "這也要拍嗎？",
  ui_story_5037_50371401_3_dialog_content = "當然了！優秀的導演可不會放過任何一個珍貴的片段！",
  ui_story_5037_50371401_4_dialog_content = "好吧……",
  ui_story_5037_50371401_5_dialog_content = "那麼，第一次「製作人速成研討會」，開始。",
  ui_story_5037_50371401_6_dialog_content = "……",
  ui_story_5037_50371401_7_dialog_content = "（事務所的這個角落已經堆滿了書……）",
  ui_story_5037_50371401_8_dialog_content = "（這些都是薇絲和卡蓮帶來的書嗎？）",
  ui_story_5037_50371401_9_dialog_content = "（她們也都緊繃著表情，真令人不安……）",
  ui_story_5037_50371401_10_dialog_content = "妳們怎麼都這麼嚴肅……",
  ui_story_5037_50371401_11_dialog_content = "因為事關PlayerName能不能順利成為製作人，所以我們必須認真對待！",
  ui_story_5037_50371401_12_dialog_content = "沒錯，只有這件事，絕對不能輕忽。",
  ui_story_5037_50371401_13_dialog_content = "讓妳們費心了，本來這應該是我要努力的部分……",
  ui_story_5037_50371401_14_dialog_content = "這是哪裡的話，身為PlayerName的好搭檔，我們兩個永遠都是你的後盾！",
  ui_story_5037_50371401_15_dialog_content = "為了幫助你盡快理解「製作人」需要做的事情，我和薇絲一起做了研究。",
  ui_story_5037_50371401_16_dialog_content = "沒錯，從「偶像」到「製作人」，所有相關的資料都在這裡了！",
  ui_story_5037_50371401_17_dialog_content = "從今天開始，這裡就是「製作人速成班」的場地了！",
  ui_story_5037_50371401_18_dialog_content = "這些……都是筆記和剪報！？",
  ui_story_5037_50371401_19_dialog_content = "嗯！卡蓮去圖書館翻遍了關於培養歌手和舞蹈家的書籍，寫了這些筆記。",
  ui_story_5037_50371401_20_dialog_content = "而我把影鎮近幾年的報紙都買了一份，收集了裡面所有關於偶像和製作人的報導！",
  ui_story_5037_50371401_21_dialog_content = "好厲害……！？",
  ui_story_5037_50371401_22_dialog_content = "太辛苦了吧……看完所有的書還要做筆記，這要花多少時間啊……",
  ui_story_5037_50371401_23_dialog_content = "在整理筆記的時候，路過的克蘿伊和基汀也來幫忙了。",
  ui_story_5037_50371401_24_dialog_content = "他們比我更熟悉音樂方面的知識，在寫筆記的時候幫了我不少忙。",
  ui_story_5037_50371401_25_dialog_content = "我也有拜託珀蘭蒂小姐一起幫忙。",
  ui_story_5037_50371401_26_dialog_content = "她是職業記者，對各種新聞報導比我更加熟悉！",
  ui_story_5037_50371401_27_dialog_content = "沒錯，現在的這份成果，是大家為了幫助PlayerName，一起努力獲得的。",
  ui_story_5037_50371401_28_dialog_content = "確實呢……",
  ui_story_5037_50371401_29_dialog_content = "這份努力，我絕不會辜負的！",
  ui_story_5037_50371401_30_dialog_content = "那我們就開始進一步討論吧。",
  ui_story_5037_50371401_31_dialog_content = "這次會議的第二件事，是定好這段時間PlayerName的培養方案！",
  ui_story_5037_50371401_32_dialog_content = "培養方案？",
  ui_story_5037_50371401_33_dialog_content = "是的，我們為你制定了兩套不同的培養方案，希望你能自己選擇適合的一種。",
  ui_story_5037_50371401_34_dialog_content = "這一套方案叫做「製作人：從入門到精通」。",
  ui_story_5037_50371401_35_dialog_content = "好厚！？",
  ui_story_5037_50371401_36_dialog_content = "裡面匯集了從基礎知識到專業技巧的規劃知識，但是內容繁瑣，學起來比較花時間。",
  ui_story_5037_50371401_37_dialog_content = "另一套呢？",
  ui_story_5037_50371401_38_dialog_content = "這套方案叫做「職業製作人進階技巧」，裡面是我整理的歷代著名學者規劃時間的技巧。",
  ui_story_5037_50371401_39_dialog_content = "不過，這套方案需要一定的基礎才能較為順利地讀懂。",
  ui_story_5037_50371401_40_dialog_content = "PlayerName，請根據你自己的情況，挑選適合的方案吧！",
  ui_story_5037_50371401_41_dialog_content = "適合我自己的方案……",
  ui_story_5037_50371401_42_dialog_content = "我目前還是一個新手製作人，所以就選這套方案吧——",
  ui_story_5037_50371401_43_option_content = "「製作人：從入門到精通」",
  ui_story_5037_50371401_44_dialog_content = "從基礎開始學習，這種選擇最穩妥！",
  ui_story_5037_50371401_45_dialog_content = "我也同意你的觀點。",
  ui_story_5037_50371401_46_dialog_content = "那麼從現在開始，按照這套方案學習如何成為製作人吧！",
  ui_story_5037_50371401_47_dialog_content = "我會努力的！",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371401_49_dialog_content = "製作人的主要工作……規劃進度……策劃……",
  ui_story_5037_50371401_50_dialog_content = "還有什麼來著？我怎麼又忘記了……",
  ui_story_5037_50371401_51_dialog_content = "休息一下吧，PlayerName。",
  ui_story_5037_50371401_52_dialog_content = "你已經記住很多東西了，接下來該做的，就是在平時實際運用這些知識。",
  ui_story_5037_50371401_53_option_content = "「職業製作人進階技巧」",
  ui_story_5037_50371401_54_dialog_content = "既然決定挑戰自己，那就從高難度的部分開始吧！",
  ui_story_5037_50371401_55_dialog_content = "直接從高難度開始嗎！？",
  ui_story_5037_50371401_56_dialog_content = "既然你做出選擇了，那我們也會盡全力幫忙。",
  ui_story_5037_50371401_57_dialog_content = "我……我應該沒問題的！",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371401_59_dialog_content = "好難！",
  ui_story_5037_50371401_60_dialog_content = "這套方案對於PlayerName來說，確實難了點……",
  ui_story_5037_50371401_61_dialog_content = "我在整理的時候也注意到了，裡面有許多複雜的事項，彼此之間還會互相影響。",
  ui_story_5037_50371401_62_dialog_content = "看來還是要循序漸進，慢慢學習才行。",
  ui_story_5037_50371401_63_dialog_content = "現在時間已經不早了，就先到這裡吧。",
  ui_story_5037_50371401_64_dialog_content = "辛苦啦，PlayerName！",
  ui_story_5037_50371401_65_dialog_content = "辛苦了。",
  ui_story_5037_50371401_66_dialog_content = "明明是妳們比我更辛苦才對，準備這麼多資料，肯定很不容易。",
  ui_story_5037_50371401_67_dialog_content = "我們關係這麼好，就不用多說客套話啦。",
  ui_story_5037_50371401_68_dialog_content = "趕快去休息吧！",
  ui_story_5037_50371401_69_dialog_content = "妳們也好好休息！",
  ui_story_5037_50371401_70_dialog_content = "我們等一下還有別的事情，還要再出門一趟。",
  ui_story_5037_50371401_71_dialog_content = "咦？還要出門嗎？去哪裡？",
  ui_story_5037_50371401_72_dialog_content = "我們兩個約好一起去採訪幾位以唱功出名的光靈，向他們學習演唱的技巧。",
  ui_story_5037_50371401_73_dialog_content = "雖然每個人的情況各不相同，但許多演唱技巧是互通的。",
  ui_story_5037_50371401_74_dialog_content = "如果這些技巧能帶給歌爾蒂啟發，就能幫上你們的忙。",
  ui_story_5037_50371401_75_dialog_content = "但是，妳們之前也為準備培養方案，奔波了很久吧？",
  ui_story_5037_50371401_76_dialog_content = "我覺得妳們才是真正需要休息的……",
  ui_story_5037_50371401_77_dialog_content = "不用擔心，我可是精力十足哦！",
  ui_story_5037_50371401_78_dialog_content = "這是一次新鮮的體驗，我們都非常期待。",
  ui_story_5037_50371401_79_dialog_content = "或許正因如此，不管有多忙，都不會覺得疲倦。",
  ui_story_5037_50371401_80_dialog_content = "PlayerName也有這樣的感覺吧？",
  ui_story_5037_50371401_81_dialog_content = "確實是呢……",
  ui_story_5037_50371401_82_dialog_content = "從開始擔任製作人到現在，我幾乎每天過的都是從早忙到晚的生活。",
  ui_story_5037_50371401_83_dialog_content = "但是因為每天都能遇到各種新鮮的事情，所以一點也沒覺得累！",
  ui_story_5037_50371401_84_dialog_content = "就好像剛從地底出來，與大家相遇的那幾天。",
  ui_story_5037_50371401_85_dialog_content = "明明一直被暗鬼追著跑，卻一點也不會感到沮喪和疲倦。",
  ui_story_5037_50371401_86_dialog_content = "這就是新的旅程帶來的新鮮感！",
  ui_story_5037_50371401_87_dialog_content = "嗯！",
  ui_story_5037_50371401_88_dialog_content = "不過，即使是這樣，我也不會只讓妳們兩人忙碌的！",
  ui_story_5037_50371401_89_dialog_content = "欸？",
  ui_story_5037_50371401_90_dialog_content = "為什麼？",
  ui_story_5037_50371401_91_dialog_content = "因為我們一直是一起行動的啊。",
  ui_story_5037_50371401_92_dialog_content = "不管是旅行還是冒險，我們三個人一直都是夥伴。",
  ui_story_5037_50371401_93_dialog_content = "所以，這次我也要一起！",
  ui_story_5037_50371401_94_dialog_content = "可是——",
  ui_story_5037_50371401_95_dialog_content = "不用擔心我！大家一起努力吧，就像一直以來的那樣。",
  ui_story_5037_50371401_96_dialog_content = "嗯，就像一直以來那樣！",
  ui_story_5037_50371501_1_dialog_content = "PlayerName組的臨時會議，三、二、一、開拍！",
  ui_story_5037_50371501_2_dialog_content = "抱歉，我來遲了！",
  ui_story_5037_50371501_3_dialog_content = "沒關係！只要你來了就好！",
  ui_story_5037_50371501_4_dialog_content = "咦？歌爾蒂呢？",
  ui_story_5037_50371501_5_dialog_content = "她去找涉女士商量接下來的計畫了，暫時還走不開。",
  ui_story_5037_50371501_6_dialog_content = "欸？真可惜……",
  ui_story_5037_50371501_7_dialog_content = "可惜？",
  ui_story_5037_50371501_8_dialog_content = "恭喜你和歌爾蒂，順利舉辦了出道演唱會。",
  ui_story_5037_50371501_9_dialog_content = "我們準備了一些點心和茶飲，想等你和歌爾蒂回來後一起享用。",
  ui_story_5037_50371501_10_dialog_content = "謝謝！沒關係，我可以留一些點心，等一會帶給歌爾蒂。",
  ui_story_5037_50371501_11_dialog_content = "歌爾蒂不在，還真是有點可惜呢。",
  ui_story_5037_50371501_12_dialog_content = "我花了很多時間烤了不少餅乾，打算和大家一起吃。",
  ui_story_5037_50371501_13_dialog_content = "烤壞了好幾次，才終於有一次成功了。",
  ui_story_5037_50371501_14_dialog_content = "真是辛苦妳了……",
  ui_story_5037_50371501_15_dialog_content = "（薇絲努力烤好的餅乾，應該沒問題吧？）",
  ui_story_5037_50371501_16_dialog_content = "時間過得真快啊，沒想到出道演唱會已經結束了。",
  ui_story_5037_50371501_17_dialog_content = "是啊，「製作人速成班」也開設了這麼久呢。",
  ui_story_5037_50371501_18_dialog_content = "剛開始幫PlayerName成為製作人的時候，大家都手忙腳亂的。",
  ui_story_5037_50371501_19_dialog_content = "但是現在，PlayerName已經幫歌爾蒂成功舉辦了出道演唱會。",
  ui_story_5037_50371501_20_dialog_content = "PlayerName成為了一位可靠的製作人。",
  ui_story_5037_50371501_21_dialog_content = "沒錯，PlayerName取得了明顯的進步呢！",
  ui_story_5037_50371501_22_dialog_content = "嘿嘿，謝謝！說得我都有點不好意思了。",
  ui_story_5037_50371501_23_dialog_content = "恭喜！",
  ui_story_5037_50371501_24_dialog_content = "恭喜你，PlayerName。",
  ui_story_5037_50371501_25_dialog_content = "謝謝！",
  ui_story_5037_50371501_26_dialog_content = "那我們快開始慶祝吧！",
  ui_story_5037_50371501_27_dialog_content = "再晚一點，茶就要放涼了！",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>窸窸窣窣——</color>",
  ui_story_5037_50371501_29_dialog_content = "你們有沒有聽到什麼奇怪的聲音？",
  ui_story_5037_50371501_30_dialog_content = "嗯？有嗎？",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>窸窸窣窣——</color>",
  ui_story_5037_50371501_32_dialog_content = "聽，又出現了，好像是從放樂器的牆角傳來的。",
  ui_story_5037_50371501_33_dialog_content = "是風聲嗎？",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>窸窸窣窣——</color>",
  ui_story_5037_50371501_35_dialog_content = "……",
  ui_story_5037_50371501_36_dialog_content = "鼓後面好像藏著什麼東西？",
  ui_story_5037_50371501_37_dialog_content = "難道……是暗鬼？",
  ui_story_5037_50371501_38_dialog_content = "先試探一下好了。",
  ui_story_5037_50371501_39_dialog_content = "冰花——",
  ui_story_5037_50371501_40_dialog_content = "囉！囉囉囉！",
  ui_story_5037_50371501_41_dialog_content = "哎呀？是凱羅？",
  ui_story_5037_50371501_42_dialog_content = "它不是總和菲雅黏在一起嗎，怎麼跑到這裡來了？",
  ui_story_5037_50371501_43_dialog_content = "囉……（翻譯：菲雅派我來打探PlayerName組的情報囉。）",
  ui_story_5037_50371501_44_dialog_content = "囉囉！（翻譯：但是她沒有說這裡有這麼多人囉！）",
  ui_story_5037_50371501_45_dialog_content = "囉，囉。（翻譯：現在被發現囉，要找機會逃跑才行囉。）",
  ui_story_5037_50371501_46_dialog_content = "難不成，是來打探情報的？",
  ui_story_5037_50371501_47_dialog_content = "囉，囉囉！",
  ui_story_5037_50371501_48_dialog_content = "它好像在否認呢。",
  ui_story_5037_50371501_49_dialog_content = "也對呢，以凱羅平時的表現，大概只是想找吃的，結果迷路到這裡的吧。",
  ui_story_5037_50371501_50_dialog_content = "難道凱羅是受不了菲雅給維克制定的高強度訓練計畫，偷跑出來了嗎？",
  ui_story_5037_50371501_51_dialog_content = "囉！",
  ui_story_5037_50371501_52_dialog_content = "凱羅好像是在表示肯定。",
  ui_story_5037_50371501_53_dialog_content = "可憐的小傢伙，每天監督維克訓練，一定累壞了吧……",
  ui_story_5037_50371501_54_dialog_content = "囉……",
  ui_story_5037_50371501_55_dialog_content = "就讓它在這裡休息一下吧，我們準備的茶點還有很多，可以分給它一份。",
  ui_story_5037_50371501_56_dialog_content = "嗯，就這麼辦吧！之後我再把它送還給菲雅。",
  ui_story_5037_50371501_57_dialog_content = "囉~囉~（翻譯：太好了，他們似乎沒有發現我是來打探消息的。）",
  ui_story_5037_50371501_58_dialog_content = "囉！（而且還有點心吃，是什麼呢？）",
  ui_story_5037_50371501_59_dialog_content = "我記得菲雅之前說過，凱羅喜歡吃動物餅乾。",
  ui_story_5037_50371501_60_dialog_content = "不知道我烤的餅乾凱羅會不會喜歡……",
  ui_story_5037_50371501_61_dialog_content = "（呃，這個感覺……！）",
  ui_story_5037_50371501_62_dialog_content = "（簡直和「那個」一樣！）",
  ui_story_5037_50371501_63_dialog_content = "囉！（翻譯：這這這，看起來就非常不妙！）",
  ui_story_5037_50371501_64_dialog_content = "凱羅，吃吃看我烤的餅乾吧！",
  ui_story_5037_50371501_65_dialog_content = "雖然不如白夜城的甜品店賣的餅乾好看，但做法是完全一樣的喔！",
  ui_story_5037_50371501_66_dialog_content = "囉，囉！（翻譯：妳不要過來啊！）",
  ui_story_5037_50371501_67_dialog_content = "來，張嘴~",
  ui_story_5037_50371501_68_dialog_content = "囉！！！",
  ui_story_5037_50371501_69_dialog_content = "凱羅突然掙脫了！？",
  ui_story_5037_50371501_70_dialog_content = "唔哇，那個方向是書堆！",
  ui_story_5037_50371501_71_dialog_content = "快抓住凱羅，它身上黏糊糊的，會把書都弄濕的！",
  ui_story_5037_50371501_72_dialog_content = "凱羅，快停下！",
  ui_story_5037_50371501_73_dialog_content = "囉！！！",
  ui_story_5037_50371501_74_dialog_content = "（糟了，凱羅直接朝書堆飛過去了！）",
  ui_story_5037_50371501_75_option_content = "保護專業書",
  ui_story_5037_50371501_76_option_content = "保護雜誌",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>咚！！！</color>",
  ui_story_5037_50371501_78_dialog_content = "嗚噗——！",
  ui_story_5037_50371501_79_dialog_content = "<size=45>好痛！！！</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName！？",
  ui_story_5037_50371501_81_dialog_content = "我沒事……只是，痛……",
  ui_story_5037_50371501_82_dialog_content = "囉……",
  ui_story_5037_50371501_83_dialog_content = "囉囉囉！",
  ui_story_5037_50371501_84_dialog_content = "這個傢伙，跑得還真快！",
  ui_story_5037_50371501_85_dialog_content = "我們的書怎麼樣，沒事吧？",
  ui_story_5037_50371501_86_dialog_content = "噗，咳咳咳，至少有保護到一部分。",
  ui_story_5037_50371501_87_dialog_content = "我也保護了筆記和剪報。",
  ui_story_5037_50371501_88_dialog_content = "但是其他的書就全被弄濕了。",
  ui_story_5037_50371501_89_dialog_content = "這樣消沉下去也不是辦法，先把弄濕的書都挑出來吧。",
  ui_story_5037_50371501_90_dialog_content = "一本、兩本……",
  ui_story_5037_50371501_91_dialog_content = "這邊的看起來只要仔細晾乾，還能繼續閱讀。",
  ui_story_5037_50371501_92_dialog_content = "但這幾本的字跡已經全部糊掉，沒辦法看了。",
  ui_story_5037_50371501_93_dialog_content = "裡面似乎還有從別處借來的書呢！",
  ui_story_5037_50371501_94_dialog_content = "沒辦法了，先統計好借來的書目，然後向書的主人道歉和賠償吧。",
  ui_story_5037_50371501_95_dialog_content = "只能這麼辦了。",
  ui_story_5037_50371501_96_dialog_content = "不知道我存的白夜幣夠不夠賠……",
  ui_story_5037_50371501_97_dialog_content = "我也會出一些的。",
  ui_story_5037_50371501_98_dialog_content = "嗯，我也沒能阻止凱羅，我也會出一部分的錢。",
  ui_story_5037_50371501_99_dialog_content = "不用擔心，PlayerName，我們會幫你一起承擔的。",
  ui_story_5037_50371501_100_dialog_content = "謝謝妳們，薇絲，卡蓮。",
  ui_story_5037_50371501_101_dialog_content = "不過，還有一件最重要的事——",
  ui_story_5037_50371501_102_dialog_content = "找到菲雅，讓她好好教育一下自己的夥伴！",
  ui_story_5037_50371601_1_dialog_content = "PlayerName組的最終會議，三、二、一、開拍！",
  ui_story_5037_50371601_2_dialog_content = "「最終會議」嗎？不知不覺已經到了這個時候呢。",
  ui_story_5037_50371601_3_dialog_content = "是啊，再過幾天就是「畢業演唱會」了呢。",
  ui_story_5037_50371601_4_dialog_content = "時間過得真快，彷彿昨天我們才把書搬過來，開始「製作人速成班」的課程。",
  ui_story_5037_50371601_5_dialog_content = "我們今天要做什麼呢？",
  ui_story_5037_50371601_6_dialog_content = "今天的主要任務只有一項——收拾整理！",
  ui_story_5037_50371601_7_dialog_content = "PlayerName已經完成了計畫上的所有項目，成長為一名出色的製作人啦！",
  ui_story_5037_50371601_8_dialog_content = "所以，「製作人速成班」正式結業啦！",
  ui_story_5037_50371601_9_dialog_content = "是的，今天要做的事情，就是將書本都收拾整齊。",
  ui_story_5037_50371601_10_dialog_content = "這樣也方便盡快把借來的部分物歸原主。",
  ui_story_5037_50371601_11_dialog_content = "原來如此，我也來幫忙！",
  ui_story_5037_50371601_12_dialog_content = "我們一起盡快整理好這些書吧。",
  ui_story_5037_50371601_13_dialog_content = "嗯！",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371601_15_dialog_content = "這套《養成好習慣：從頭開始學規劃》應該放哪裡？",
  ui_story_5037_50371601_16_dialog_content = "放我這邊吧。",
  ui_story_5037_50371601_17_dialog_content = "這套書是從薇薇安長官借來的，是長官的力薦之作！",
  ui_story_5037_50371601_18_dialog_content = "薇薇安長官說，她就是讀過之後，才慢慢開始學會時間的安排。",
  ui_story_5037_50371601_19_dialog_content = "這裡面的知識確實很有用，幫了我不少忙！",
  ui_story_5037_50371601_20_dialog_content = "PlayerName，能把你手邊那本《合唱技巧三百條》遞給我嗎？",
  ui_story_5037_50371601_21_dialog_content = "沒問題，給！",
  ui_story_5037_50371601_22_dialog_content = "我猜這本書是基汀他們借妳的？",
  ui_story_5037_50371601_23_dialog_content = "你怎麼知道？",
  ui_story_5037_50371601_24_dialog_content = "因為這本書雖然封面很乾淨，但裡面的書頁畫滿了塗鴉。",
  ui_story_5037_50371601_25_dialog_content = "更過分的是，當中還有把我畫成黑眼圈很重的簡筆畫！！！",
  ui_story_5037_50371601_26_dialog_content = "……噗。",
  ui_story_5037_50371601_27_dialog_content = "確實像是他們會做的事情。",
  ui_story_5037_50371601_28_dialog_content = "如果你介意，我就叫他們擦掉好了。",
  ui_story_5037_50371601_29_dialog_content = "這倒不必……",
  ui_story_5037_50371601_30_dialog_content = "要是叫他們擦掉，肯定還會編一些更過分的詩歌嘲諷我。",
  ui_story_5037_50371601_31_dialog_content = "所以就留著吧。",
  ui_story_5037_50371601_32_dialog_content = "那些孩子確實很擅長讓別人頭疼呢。",
  ui_story_5037_50371601_33_dialog_content = "這樣一來，書籍應該都收拾得差不多了吧？",
  ui_story_5037_50371601_34_dialog_content = "已經全都分類收好了！",
  ui_story_5037_50371601_35_dialog_content = "除了書籍以外，還有一大堆筆記。",
  ui_story_5037_50371601_36_dialog_content = "這些筆記是從開始到現在，一直積存下來的。",
  ui_story_5037_50371601_37_dialog_content = "沒錯，上面的每一個字都見證了我們的努力和付出呢！",
  ui_story_5037_50371601_38_dialog_content = "有厚厚一大疊呢！",
  ui_story_5037_50371601_39_dialog_content = "寫的時候沒什麼感覺，大多只是順手拿了張紙記下學到的東西。",
  ui_story_5037_50371601_40_dialog_content = "沒想到積存起來竟然有這麼多！",
  ui_story_5037_50371601_41_dialog_content = "這就是積少成多的成果。",
  ui_story_5037_50371601_42_dialog_content = "不過，感覺已經很久沒有寫過這麼多筆記了，真像是回到了學生時代！",
  ui_story_5037_50371601_43_dialog_content = "和卡蓮一起上課、記筆記、吃飯……每天都過得非常悠閒呢！",
  ui_story_5037_50371601_44_dialog_content = "當然啦，除了考試之前的那幾天。",
  ui_story_5037_50371601_45_dialog_content = "學生時代嗎？有點難想像……",
  ui_story_5037_50371601_46_dialog_content = "畢竟我完全沒有經歷過校園生活。",
  ui_story_5037_50371601_47_dialog_content = "一直以來，都是臨空者號在當PlayerName的老師吧？",
  ui_story_5037_50371601_48_dialog_content = "如果是這樣，和別人一起學習生活的經歷確實有些難以想像呢。",
  ui_story_5037_50371601_49_dialog_content = "那種感覺和一起旅行很像，唯一的區別大概在於不用對付暗鬼？",
  ui_story_5037_50371601_50_dialog_content = "以後有機會，一起去參觀黎明學院吧。",
  ui_story_5037_50371601_51_dialog_content = "就像現在體驗當製作人一樣，體驗一下校園生活。",
  ui_story_5037_50371601_52_dialog_content = "好啊！不過能不能不用考試？",
  ui_story_5037_50371601_53_dialog_content = "忙碌了這麼久，我整個人都已經感到疲憊了……",
  ui_story_5037_50371601_54_dialog_content = "最想做的事情，還是拋開考試和考核，好好休息一番！",
  ui_story_5037_50371601_55_option_content = "但還不能放鬆",
  ui_story_5037_50371601_56_dialog_content = "為了籌備最後的演唱會，我還有很多工作要做。",
  ui_story_5037_50371601_57_dialog_content = "現在鬆懈下來，就前功盡棄了！",
  ui_story_5037_50371601_58_dialog_content = "PlayerName總是對新鮮的事物抱持很高的熱情呢！",
  ui_story_5037_50371601_59_dialog_content = "因為之前在地下住了17年嘛……",
  ui_story_5037_50371601_60_dialog_content = "所以總想要親自嘗試每件事嗎？",
  ui_story_5037_50371601_61_dialog_content = "沒錯！",
  ui_story_5037_50371601_62_option_content = "我現在就想躺下",
  ui_story_5037_50371601_63_dialog_content = "剛開始當製作人的時候還覺得頗新鮮，現在已經逐漸習慣了。",
  ui_story_5037_50371601_64_dialog_content = "每天都在重複相同的工作，雖然有成就感，但難免會感到無趣……",
  ui_story_5037_50371601_65_dialog_content = "我能理解這種心情……",
  ui_story_5037_50371601_66_dialog_content = "就算是再有趣的事，每天重複也會變得索然無味。",
  ui_story_5037_50371601_67_dialog_content = "所以，我們才需要不斷進行新的挑戰。",
  ui_story_5037_50371601_68_dialog_content = "無論如何，當製作人的經歷對我來說很寶貴！",
  ui_story_5037_50371601_69_dialog_content = "不只幫助歌爾蒂舉辦了演唱會，還能和妳們一起學習！",
  ui_story_5037_50371601_70_dialog_content = "能有這種經歷，我非常開心！",
  ui_story_5037_50371601_71_dialog_content = "感覺現在的PlayerName就算留下來繼續擔任製作人，也一定能有一番成就！",
  ui_story_5037_50371601_72_dialog_content = "PlayerName，當製作人和到處旅行相比，你更喜歡哪種生活？",
  ui_story_5037_50371601_73_dialog_content = "這個問題的答案……當然很明確了！",
  ui_story_5037_50371601_74_dialog_content = "！",
  ui_story_5037_50371601_75_dialog_content = "當然是和大家一起旅行最開心了！",
  ui_story_5037_50371701_1_dialog_content = "芙洛琳？沒想到妳來了！歡迎！",
  ui_story_5037_50371701_2_dialog_content = "不過，如果妳是來聽歌爾蒂的演唱會，恐怕還要再等幾天，現在她還在訓練中。",
  ui_story_5037_50371701_3_dialog_content = "我不是來聽演唱會的。",
  ui_story_5037_50371701_4_dialog_content = "欸？",
  ui_story_5037_50371701_5_dialog_content = "我是來提供幫助的。",
  ui_story_5037_50371701_6_dialog_content = "我聽說你正在嘗試一種叫做製作人的新工作，似乎是一種新興職業。",
  ui_story_5037_50371701_7_dialog_content = "作為朋友，我想詢問你。",
  ui_story_5037_50371701_8_dialog_content = "空之末裔，有什麼我能幫忙的嗎？",
  ui_story_5037_50371701_9_dialog_content = "其實也沒什麼需要幫忙的……",
  ui_story_5037_50371701_10_dialog_content = "是嗎……",
  ui_story_5037_50371701_11_dialog_content = "（欸？芙洛琳看起來有些失落？）",
  ui_story_5037_50371701_12_dialog_content = "（難道她因為幫不上忙而難過嗎……）",
  ui_story_5037_50371701_13_dialog_content = "不，其……其實還是有的！",
  ui_story_5037_50371701_14_dialog_content = "是什麼呢？",
  ui_story_5037_50371701_15_dialog_content = "（該說些什麼才好呢？）",
  ui_story_5037_50371701_16_dialog_content = "（我不希望芙洛琳失望，但也不想太麻煩她……）",
  ui_story_5037_50371701_17_dialog_content = "（對了，我記得芙洛琳之前似乎是學生會長，那就——）",
  ui_story_5037_50371701_18_option_content = "請教編曲問題",
  ui_story_5037_50371701_19_dialog_content = "歌爾蒂最近寫了首新歌，但還沒想好用什麼伴奏。芙洛琳能提供一點意見嗎？",
  ui_story_5037_50371701_20_dialog_content = "音樂的伴奏嗎……問到我不太擅長的方面了。",
  ui_story_5037_50371701_21_dialog_content = "不過我經常去聽歌劇，也算是對這方面有一點自己的領悟，我會盡力的！",
  ui_story_5037_50371701_22_dialog_content = "太感謝妳了！",
  ui_story_5037_50371701_23_option_content = "請教學習問題",
  ui_story_5037_50371701_24_dialog_content = "歌爾蒂想要我提出一些演唱會方面的建設性建議，但是我自己都還不太懂。",
  ui_story_5037_50371701_25_dialog_content = "怎麼才能讓我快速地掌握聲樂知識，好給歌爾蒂提出更有幫助的建議呢？",
  ui_story_5037_50371701_26_dialog_content = "你算是問對人了，我對「如何系統性地自學」這方面頗有心得。我會毫無保留地教給你的！",
  ui_story_5037_50371701_27_dialog_content = "好的，拜託了！",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5037_50371701_29_dialog_content = "我已經把所知道的，全都教給你了。",
  ui_story_5037_50371701_30_dialog_content = "等等，我還有一些地方沒弄清楚。",
  ui_story_5037_50371701_31_dialog_content = "讓我翻一下剛才的筆記……",
  ui_story_5037_50371701_32_dialog_content = "你的筆記寫得很全面，這是一個良好的習慣。",
  ui_story_5037_50371701_33_dialog_content = "因為我經常忘記事情，所以在學習的時候會邊學邊記。",
  ui_story_5037_50371701_34_dialog_content = "寫日記也是同樣的緣故，因為不想忘記生活中經歷的一些事情，所以才會寫下來。",
  ui_story_5037_50371701_35_dialog_content = "這大概就是所謂的「長記性不如練筆勁」。",
  ui_story_5037_50371701_36_dialog_content = "那麼，加油學習吧，空之末裔。",
  ui_story_5037_50371701_37_dialog_content = "努力會成為前進的助力。",
  ui_story_5037_50371701_38_dialog_content = "謝謝妳的鼓勵，芙洛琳！",
  ui_story_5037_50371701_39_dialog_content = "這不是在鼓勵。",
  ui_story_5037_50371701_40_dialog_content = "不是鼓勵嗎……？",
  ui_story_5037_50371701_41_dialog_content = "這是我在學生時代總結出的經驗。",
  ui_story_5037_50371701_42_dialog_content = "「努力」能讓平凡的人完成不平凡的成就，所以，請重視「努力」這件事。",
  ui_story_5037_50371701_43_dialog_content = "原來如此，我會的！",
  ui_story_5037_50371701_44_dialog_content = "說起來，芙洛琳至今仍穿著這身舊時代的服裝，沒有換下來呢。",
  ui_story_5037_50371701_45_dialog_content = "嗯，因為這身衣服很輕便，而且，它讓我想起學生時代。",
  ui_story_5037_50371701_46_dialog_content = "我穿著它，就是在時時提醒自己——",
  ui_story_5037_50371701_47_dialog_content = "要像學生一樣謙虛正直，時刻努力上進，成為能夠擔負重任的人。",
  ui_story_5037_50371701_48_dialog_content = "PlayerName也可以穿穿看，一定可以起到督促作用的。",
  ui_story_5037_50371701_49_dialog_content = "我……我還是算了吧！",
  ui_story_5037_50371701_50_dialog_content = "還是我自己的衣服穿起來最舒適！",
  ui_story_5037_50371701_51_dialog_content = "是嗎，那就按你自己的方式來吧。",
  ui_story_5037_50371701_52_dialog_content = "只要能時時保持努力不鬆懈，就不會有問題。",
  ui_story_5037_50371701_53_dialog_content = "芙洛琳對自己真嚴格啊……",
  ui_story_5037_50371701_54_dialog_content = "嚴格嗎？我不這麼認為。",
  ui_story_5037_50371701_55_dialog_content = "我憧憬的是海蒂前輩那樣，能夠幫助大家的人。",
  ui_story_5037_50371701_56_dialog_content = "如果能變得和前輩一樣可靠，不管過程多艱難，我都會去努力。",
  ui_story_5037_50371701_57_dialog_content = "現在的我，還不夠好。",
  ui_story_5037_50371701_58_dialog_content = "我認為芙洛琳已經很厲害了！",
  ui_story_5037_50371701_59_dialog_content = "能夠一直堅持不懈怠，這本身就是一件非常了不起的事！",
  ui_story_5037_50371701_60_dialog_content = "如果我也能像芙洛琳一樣就好了。",
  ui_story_5037_50371701_61_dialog_content = "那麼，我們就一起朝各自憧憬的方向努力吧。",
  ui_story_5037_50371701_62_dialog_content = "好！",
  ui_story_5037_50371701_63_dialog_content = "對了，還有，提醒歌爾蒂多喝水，注意身體。",
  ui_story_5037_50371701_64_dialog_content = "唱歌需要長時間地使用喉嚨，水能保持喉嚨濕潤。",
  ui_story_5037_50371701_65_dialog_content = "跳舞也是高強度的運動，需要及時補充水分。",
  ui_story_5037_50371701_66_dialog_content = "沒問題，我會記得提醒她的！",
  ui_story_5037_50371701_67_dialog_content = "還有，你自己也是，空之末裔。",
  ui_story_5037_50371701_68_dialog_content = "不管工作多忙碌，也要注意健康。",
  ui_story_5037_50371701_69_dialog_content = "好……",
  ui_story_5037_50371701_70_dialog_content = "願光之神庇佑你，讓你之後的工作能夠順利。",
  ui_story_5037_50371701_71_dialog_content = "嗯！",
  ui_story_5037_50371801_1_dialog_content = "這是難得一次的合拍！塞洛洛，要把我、歌爾蒂和PlayerName一起拍清楚！",
  ui_story_5037_50371801_2_dialog_content = "三、二、一、開拍！",
  ui_story_5037_50371801_3_dialog_content = "大家好——！我是你們的著名導演莉莉卡！",
  ui_story_5037_50371801_4_dialog_content = "今天我要作為指導者，和知名偶像歌爾蒂及其製作人PlayerName合作——",
  ui_story_5037_50371801_5_dialog_content = "一起進行表演方面的特訓喔！",
  ui_story_5037_50371801_6_dialog_content = "歌爾蒂，PlayerName，和大家打個招呼吧！",
  ui_story_5037_50371801_7_dialog_content = "我可愛的粉絲們，你們好呀！",
  ui_story_5037_50371801_8_dialog_content = "大、大家好……",
  ui_story_5037_50371801_9_dialog_content = "（一想到會錄下自己的表現讓很多人看到，就覺得有些不自在呢……）",
  ui_story_5037_50371801_10_dialog_content = "為了今天的特訓，我準備了一個特別的遊戲喔！",
  ui_story_5037_50371801_11_dialog_content = "遊戲？好呀，我最喜歡遊戲了！",
  ui_story_5037_50371801_12_dialog_content = "是什麼樣的遊戲？",
  ui_story_5037_50371801_13_dialog_content = "這個遊戲的名字叫做——「你演我猜」！",
  ui_story_5037_50371801_14_dialog_content = "在表演中，服裝、化妝、台詞和神態，皆會影響表演的最終效果。",
  ui_story_5037_50371801_15_dialog_content = "演員能做的，就是盡可能加深自己對角色的理解，讓台詞和神態貼合角色！",
  ui_story_5037_50371801_16_dialog_content = "說得沒錯呢！",
  ui_story_5037_50371801_17_dialog_content = "我觀察了PlayerName身邊的很多朋友，歸納了他們的特點。也寫了對應台詞。",
  ui_story_5037_50371801_18_dialog_content = "接下來在遊戲中，由歌爾蒂挑選其中一個人，模仿對方的言行舉止。",
  ui_story_5037_50371801_19_dialog_content = "然後，由PlayerName負責猜歌爾蒂扮演的是誰！",
  ui_story_5037_50371801_20_dialog_content = "只要PlayerName能猜出來，歌爾蒂的扮演就成功了！",
  ui_story_5037_50371801_21_dialog_content = "聽起來真有意思！",
  ui_story_5037_50371801_22_dialog_content = "原來是這樣！",
  ui_story_5037_50371801_23_dialog_content = "鑒於歌爾蒂還是表演新人，我也會提供PlayerName包含正確答案的選擇題。",
  ui_story_5037_50371801_24_dialog_content = "總之，遊戲不會很難，請放鬆心情參與吧！",
  ui_story_5037_50371801_25_dialog_content = "好！",
  ui_story_5037_50371801_26_dialog_content = "請期待我的扮演吧！",
  ui_story_5037_50371801_27_dialog_content = "歌爾蒂，請從這份名單中挑選一個扮演對象吧。",
  ui_story_5037_50371801_28_dialog_content = "嗯……我就選這個吧！",
  ui_story_5037_50371801_29_dialog_content = "PlayerName，我要開始扮演啦。",
  ui_story_5037_50371801_30_dialog_content = "「唷，小子！」",
  ui_story_5037_50371801_31_dialog_content = "（這個感覺，好熟悉！）",
  ui_story_5037_50371801_32_dialog_content = "「準備好和我一起去搶點什麼了嗎？」",
  ui_story_5037_50371801_33_dialog_content = "PlayerName，猜猜看歌爾蒂扮演的是誰吧！",
  ui_story_5037_50371801_34_option_content = "巴頓？",
  ui_story_5037_50371801_35_dialog_content = "雖然很接近，但是回答錯誤！",
  ui_story_5037_50371801_36_dialog_content = "正確答案是醒山！",
  ui_story_5037_50371801_37_dialog_content = "竟然猜錯了",
  ui_story_5037_50371801_38_dialog_content = "是我演得不夠像嗎？下次我會加油的！",
  ui_story_5037_50371801_39_option_content = "醒山？",
  ui_story_5037_50371801_40_dialog_content = "正確！",
  ui_story_5037_50371801_41_dialog_content = "看來歌爾蒂的扮演很成功！",
  ui_story_5037_50371801_42_dialog_content = "歌爾蒂演得真好，非常像醒山！",
  ui_story_5037_50371801_43_dialog_content = "像到我差點以為妳要從背後抽出一個紅色大扳手了……",
  ui_story_5037_50371801_44_dialog_content = "我就當作是在誇獎我囉？",
  ui_story_5037_50371801_45_option_content = "克萊肯？",
  ui_story_5037_50371801_46_dialog_content = "完全——不對！",
  ui_story_5037_50371801_47_dialog_content = "正確答案是醒山才對喔！",
  ui_story_5037_50371801_48_dialog_content = "PlayerName，你要認真看歌爾蒂的扮演啦！",
  ui_story_5037_50371801_49_dialog_content = "對、對不起……",
  ui_story_5037_50371801_50_dialog_content = "我也會努力扮演的！",
  ui_story_5037_50371801_51_dialog_content = "下一題開始要增加難度了喔！",
  ui_story_5037_50371801_52_dialog_content = "歌爾蒂，來試試看扮演這個人吧！",
  ui_story_5037_50371801_53_dialog_content = "這個人？和我的差距有點大呢……我試試看！",
  ui_story_5037_50371801_54_dialog_content = "「年輕人，你在做什麼呢？」",
  ui_story_5037_50371801_55_dialog_content = "（這次她扮演的是……？）",
  ui_story_5037_50371801_56_dialog_content = "「你有空的話，請把下午茶送到我的房間吧，因為我實在是懶得去拿了。」",
  ui_story_5037_50371801_57_dialog_content = "來猜猜看吧，PlayerName！",
  ui_story_5037_50371801_58_option_content = "彌加德？",
  ui_story_5037_50371801_59_dialog_content = "正確！",
  ui_story_5037_50371801_60_dialog_content = "還真是有點難呢……",
  ui_story_5037_50371801_61_dialog_content = "我也覺得很難，她的神態和氣質都與眾不同，難以表現。",
  ui_story_5037_50371801_62_dialog_content = "可我還是猜出來了，證明歌爾蒂扮演成功了喔！",
  ui_story_5037_50371801_63_option_content = "城主大人？",
  ui_story_5037_50371801_64_dialog_content = "雖然從年齡上來說，他確實也可以叫你年輕人……",
  ui_story_5037_50371801_65_dialog_content = "但正確答案是彌加德！",
  ui_story_5037_50371801_66_dialog_content = "看來我還需要努力呢……",
  ui_story_5037_50371801_67_dialog_content = "不，也可能是因為我的疏忽大意……",
  ui_story_5037_50371801_68_option_content = "塔塔？",
  ui_story_5037_50371801_69_dialog_content = "錯！塔塔年紀那麼小，怎麼可能會叫你「年輕人」嘛！",
  ui_story_5037_50371801_70_dialog_content = "正確答案是彌加德才對！",
  ui_story_5037_50371801_71_dialog_content = "雖然她是位很漂亮的大姐姐，但說話卻總像個大叔一樣……",
  ui_story_5037_50371801_72_dialog_content = "確、確實呢……",
  ui_story_5037_50371801_73_dialog_content = "每次遇到她，總有種受到審視的感覺！",
  ui_story_5037_50371801_74_dialog_content = "PlayerName，下一題我們再一起加油吧！",
  ui_story_5037_50371801_75_dialog_content = "接下來是最後一題！",
  ui_story_5037_50371801_76_dialog_content = "歌爾蒂，請扮演一下這位吧！",
  ui_story_5037_50371801_77_dialog_content = "欸！？真……真的沒問題嗎？",
  ui_story_5037_50371801_78_dialog_content = "嗯，請盡情發揮吧！",
  ui_story_5037_50371801_79_dialog_content = "那……我要開始演了！",
  ui_story_5037_50371801_80_dialog_content = "「PlayerName……」",
  ui_story_5037_50371801_81_dialog_content = "（已經開始了嗎！？）",
  ui_story_5037_50371801_82_dialog_content = "「今天，我們也要一起加油哦！」",
  ui_story_5037_50371801_83_dialog_content = "來吧，PlayerName，來猜猜看吧！",
  ui_story_5037_50371801_84_option_content = "莉莉卡？",
  ui_story_5037_50371801_85_dialog_content = "莉莉卡確實很像！但不是她……",
  ui_story_5037_50371801_86_dialog_content = "欸？竟然不是嗎……",
  ui_story_5037_50371801_87_dialog_content = "PlayerName，答案其實就站在你眼前！",
  ui_story_5037_50371801_88_dialog_content = "難道……歌爾蒂剛才，其實是在扮演她自己！？",
  ui_story_5037_50371801_89_dialog_content = "正確！",
  ui_story_5037_50371801_90_option_content = "歌爾蒂？",
  ui_story_5037_50371801_91_dialog_content = "猜對啦！",
  ui_story_5037_50371801_92_dialog_content = "沒想到PlayerName竟然真的猜出來了！",
  ui_story_5037_50371801_93_dialog_content = "因為平常歌爾蒂也是這樣，一直充滿活力啊！",
  ui_story_5037_50371801_94_dialog_content = "只是我不太明白，為什麼要安排這道題目呢？",
  ui_story_5037_50371801_95_dialog_content = "製作人自身對於表演的洞察力，也會影響偶像在表演方面的訓練。",
  ui_story_5037_50371801_96_dialog_content = "優秀的製作人除了需要理解偶像所扮演的角色，還需要具備一項重要的技能——",
  ui_story_5037_50371801_97_dialog_content = "那就是認識偶像自身的特點和實力！",
  ui_story_5037_50371801_98_dialog_content = "只有這樣，才有辦法幫偶像進行針對性訓練。",
  ui_story_5037_50371801_99_dialog_content = "所以最後這道題，其實是在考驗你喔，PlayerName！",
  ui_story_5037_50371801_100_dialog_content = "原來如此！我總算明白了！",
  ui_story_5037_50371801_101_dialog_content = "我也得到很多收穫！",
  ui_story_5037_50371801_102_dialog_content = "不同的角色原來有這麼大的差異，我還要多多努力！",
  ui_story_5037_50371801_103_dialog_content = "今天的訓練就先到這裡了，兩位要好好加油喔！",
  ui_story_5037_50371801_104_dialog_content = "記得回去好好將你們今天體會到的付諸實踐！",
  ui_story_5037_50371801_105_dialog_content = "明白了！",
  ui_story_5037_50371801_106_dialog_content = "是，莉莉卡導演！",
  ui_story_5037_50371901_1_dialog_content = "雲島的巫女……究竟是什麼樣子的呢？",
  ui_story_5037_50371901_2_dialog_content = "聽說巫女們能歌善舞，既優雅又神祕，還擁有強大的光能術。",
  ui_story_5037_50371901_3_dialog_content = "真讓人浮想聯翩啊！",
  ui_story_5037_50371901_4_dialog_content = "馬上就能見到她了喔！",
  ui_story_5037_50371901_5_dialog_content = "為了這次見面，我很努力地擠出時間，從事務所跑到PlayerName的巨像上來了！",
  ui_story_5037_50371901_6_dialog_content = "一想到能夠向真正的巫女請教舞蹈技巧，我的心就開始激動得怦怦跳了呢！",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5037_50371901_8_dialog_content = "抱歉，讓兩位久等了。",
  ui_story_5037_50371901_9_dialog_content = "哪裡的話，妳從雲島遠道而來指導我跳舞，我的心裡只有感激！",
  ui_story_5037_50371901_10_dialog_content = "想必這位就是歌爾蒂吧？",
  ui_story_5037_50371901_11_dialog_content = "是的，妳好，凜音小姐，我就是歌爾蒂，一名偶像歌手。",
  ui_story_5037_50371901_12_dialog_content = "妳好，我是凜音，一名來自雲島的巫女。",
  ui_story_5037_50371901_13_dialog_content = "偶像歌手，是否像是歌唱家般呢？",
  ui_story_5037_50371901_14_dialog_content = "還是有不一樣的地方，偶像除了唱歌以外，還要學習舞蹈和表演之類的才藝！",
  ui_story_5037_50371901_15_dialog_content = "原來如此，所以妳才會想學習神樂舞吧？",
  ui_story_5037_50371901_16_dialog_content = "是的，可以請凜音小姐教我嗎？",
  ui_story_5037_50371901_17_dialog_content = "當然可以，那麼，我現在先來舞一段，作為示範吧。",
  ui_story_5037_50371901_18_dialog_content = "真的嗎！能親眼看到巫女跳神樂舞，太幸運了！",
  ui_story_5037_50371901_19_dialog_content = "呵呵……",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>叮鈴鈴——</color>",
  ui_story_5037_50371901_22_dialog_content = "好美……",
  ui_story_5037_50371901_23_dialog_content = "彷彿只是聽著這鈴聲，看著凜音小姐跳舞，心情就能平靜下來……",
  ui_story_5037_50371901_24_dialog_content = "這是神樂舞最基本的幾個動作，歌爾蒂也可略作嘗試。",
  ui_story_5037_50371901_25_dialog_content = "我來試試！",
  ui_story_5037_50371901_26_dialog_content = "是這樣嗎？",
  ui_story_5037_50371901_27_dialog_content = "沒錯，歌爾蒂的動作非常標準！",
  ui_story_5037_50371901_28_dialog_content = "我對模仿動作可是很有信心的！",
  ui_story_5037_50371901_29_dialog_content = "但是，我跳出來的神樂舞，總感覺少了點什麼……",
  ui_story_5037_50371901_30_dialog_content = "確實，好像沒辦法像凜音的舞蹈那般，使人覺得平靜。",
  ui_story_5037_50371901_31_dialog_content = "難道凜音小姐在跳舞的時候，使用了特別的光能術嗎？",
  ui_story_5037_50371901_32_dialog_content = "我並未使用任何光能術，只是純粹的跳舞。",
  ui_story_5037_50371901_33_dialog_content = "那究竟是差在哪裡呢？",
  ui_story_5037_50371901_34_dialog_content = "能否冒昧詢問一下，歌爾蒂，妳在跳舞的時候，心中所想為何呢？",
  ui_story_5037_50371901_35_dialog_content = "我心裡在想什麼……？",
  ui_story_5037_50371901_36_dialog_content = "想的事情很多，比如這個動作標不標準，下個動作是什麼之類的……",
  ui_story_5037_50371901_37_dialog_content = "因為這是我第一次跳神樂舞，所以總是擔心做得不標準。",
  ui_story_5037_50371901_38_dialog_content = "哎呀，或許這就是問題所在了。",
  ui_story_5037_50371901_39_dialog_content = "神樂舞是獻給神明的舞蹈，跳舞的時候，要全心全意地想著神明。",
  ui_story_5037_50371901_40_dialog_content = "唯有這樣，虔誠心意才會透過舞蹈呈現出來。",
  ui_story_5037_50371901_41_dialog_content = "嗯……嗯！我理解了！",
  ui_story_5037_50371901_42_dialog_content = "這麼快！？",
  ui_story_5037_50371901_43_dialog_content = "這和我平時舉辦演唱會的時候差不多啊！",
  ui_story_5037_50371901_44_dialog_content = "唱歌跳舞的時候，我也是全心全意地想著粉絲們，希望帶給他們快樂。",
  ui_story_5037_50371901_45_dialog_content = "這樣想著的時候，唱出的歌和腳下的舞步也會變得順暢自然！",
  ui_story_5037_50371901_46_dialog_content = "即使舞蹈不同，也是具有共通之處的。",
  ui_story_5037_50371901_47_dialog_content = "請妳懷抱著這樣的心情，重新跳一次吧？",
  ui_story_5037_50371901_48_dialog_content = "明白了！",
  ui_story_5037_50371901_49_dialog_content = "全心全意地，想著粉絲們……",
  ui_story_5037_50371901_50_dialog_content = "（好厲害，和剛才的感覺完全不同了！）",
  ui_story_5037_50371901_51_dialog_content = "（但是，歌爾蒂的舞蹈和凜音的舞蹈似乎仍有些差別？）",
  ui_story_5037_50371901_52_dialog_content = "怎麼樣，凜音小姐、PlayerName？",
  ui_story_5037_50371901_53_option_content = "和凜音的舞蹈很像！",
  ui_story_5037_50371901_54_dialog_content = "是嗎？太好了！",
  ui_story_5037_50371901_55_dialog_content = "不，還是有一些差異的。",
  ui_story_5037_50371901_56_dialog_content = "欸？",
  ui_story_5037_50371901_57_option_content = "有歌爾蒂獨特的韻味！",
  ui_story_5037_50371901_58_dialog_content = "欸？",
  ui_story_5037_50371901_59_dialog_content = "歌爾蒂的舞蹈，感覺要更活潑輕快一些。",
  ui_story_5037_50371901_60_dialog_content = "畢竟我和歌爾蒂的舞蹈，是獻給不同對象的。",
  ui_story_5037_50371901_61_dialog_content = "歌爾蒂的舞蹈是獻給人們的，是對他人熱情的回應。",
  ui_story_5037_50371901_62_dialog_content = "因此就算是同樣的動作，傳達出的感情也會隨著舞者而千差萬別。",
  ui_story_5037_50371901_63_dialog_content = "這不是壞事，而是再正常不過的情況，所以無需擔心。",
  ui_story_5037_50371901_64_dialog_content = "妳的舞蹈和心意，本就是獨一無二的。",
  ui_story_5037_50371901_65_dialog_content = "嗯！",
  ui_story_5037_50371901_66_dialog_content = "謝謝妳的指導！",
  ui_story_5037_50372001_1_dialog_content = "今天來到了不同的地方呢，我要開始拍了哦，請各位留意自己的表現。",
  ui_story_5037_50372001_2_dialog_content = "三、二、一、開拍！",
  ui_story_5037_50372001_3_dialog_content = "已經開始拍了嗎？咳咳……",
  ui_story_5037_50372001_4_dialog_content = "從現在開始，就是本小姐的聲樂課堂了。",
  ui_story_5037_50372001_5_dialog_content = "妮娜老師好！",
  ui_story_5037_50372001_6_dialog_content = "但我還是不明白……",
  ui_story_5037_50372001_7_dialog_content = "不是說要進行聲樂方面的訓練嗎，怎麼從聲樂訓練室跑到劇場裡來了？",
  ui_story_5037_50372001_8_dialog_content = "好問題，PlayerName同學。",
  ui_story_5037_50372001_9_dialog_content = "這次的課程不是以練習為主，而是以聆聽為主。",
  ui_story_5037_50372001_10_dialog_content = "聆聽……嗎？",
  ui_story_5037_50372001_11_dialog_content = "聽別人的歌曲也是偶像訓練的重要一環！",
  ui_story_5037_50372001_12_dialog_content = "只有了解當下的粉絲們喜歡什麼，才能創作出受歡迎的歌！",
  ui_story_5037_50372001_13_dialog_content = "沒錯！掌握流行趨勢、緊跟潮流，進而引領潮流，這就是商業的命脈！",
  ui_story_5037_50372001_14_dialog_content = "比如今天我們將聆賞的這場舞台劇，名為《舞台劇魅影》。",
  ui_story_5037_50372001_15_dialog_content = "這齣劇目是演繹一名永生的舞台劇演員的故事。",
  ui_story_5037_50372001_16_dialog_content = "劇中透過演員表演劇目的變化，串聯影鎮的每一個時代。",
  ui_story_5037_50372001_17_dialog_content = "感覺好厲害！？",
  ui_story_5037_50372001_18_dialog_content = "畢竟流行文化也會反應當時的情況！",
  ui_story_5037_50372001_19_dialog_content = "正確，歌爾蒂同學加十分。",
  ui_story_5037_50372001_20_dialog_content = "米洛斯，把教材分發給他們吧。",
  ui_story_5037_50372001_21_dialog_content = "是，大小姐。",
  ui_story_5037_50372001_22_dialog_content = "這是……？",
  ui_story_5037_50372001_23_dialog_content = "這是大小姐精心準備的教材，囊括了近十幾年來影鎮所有的流行曲目和歌劇劇本。",
  ui_story_5037_50372001_24_dialog_content = "還請你們務必拿好。",
  ui_story_5037_50372001_25_dialog_content = "好、好的……",
  ui_story_5037_50372001_26_dialog_content = "在本小姐的課堂上，你們將會了解這裡面的每一首歌，了解影鎮十幾年來的流行趨勢。",
  ui_story_5037_50372001_27_dialog_content = "這有助於提升你們的品位，創作出更符合潮流的歌曲。",
  ui_story_5037_50372001_28_dialog_content = "妮娜，雖然很感謝妳的努力，但是……",
  ui_story_5037_50372001_29_dialog_content = "這些書也太多了！？",
  ui_story_5037_50372001_30_dialog_content = "我們難道要在今天內讀完它們嗎？",
  ui_story_5037_50372001_31_dialog_content = "全都讀完？不，本小姐當然不會這麼要求，畢竟這太為難你們了。",
  ui_story_5037_50372001_32_dialog_content = "這當中的歌曲皆會在今天的這場舞台劇中提及。",
  ui_story_5037_50372001_33_dialog_content = "你們可以參考我整理的完整資料，深刻體會每個時代流行文化的不同！",
  ui_story_5037_50372001_34_dialog_content = "太感謝了！",
  ui_story_5037_50372001_35_dialog_content = "我們會好好學習的！",
  ui_story_5037_50372001_36_dialog_content = "表演也快開始了，我們盡快就座吧。",
  ui_story_5037_50372001_37_dialog_content = "各位，這邊請。",
  ui_story_5037_50372001_38_dialog_content = "大小姐為各位購買了貴賓席。",
  ui_story_5037_50372001_39_dialog_content = "離舞台好近啊……這裡一定能看到最好的演出效果！",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>……</color>",
  ui_story_5037_50372001_41_dialog_content = "「良辰美景，樂聲陣陣，時光稍縱即逝。」",
  ui_story_5037_50372001_42_dialog_content = "「美麗的小姐，是否願意與我共舞？」",
  ui_story_5037_50372001_43_dialog_content = "這段是表演最早在影鎮上演的舞台劇，劇目名叫《克里歐與潔茜卡》。",
  ui_story_5037_50372001_44_dialog_content = "這個我知道，我小時候有聽過這齣舞台劇改編而成的故事！",
  ui_story_5037_50372001_45_dialog_content = "它講述了兩個光靈分處敵對家族卻互生戀情的悲劇愛情故事。",
  ui_story_5037_50372001_46_dialog_content = "沒錯。如妳所說，這個時期的影鎮文化深受白夜城的影響。",
  ui_story_5037_50372001_47_dialog_content = "劇中大量表現了當時白夜城貴族的生活習慣，例如……",
  ui_story_5037_50372001_48_dialog_content = "（妮娜和歌爾蒂似乎聊得很開心。）",
  ui_story_5037_50372001_49_dialog_content = "（舞台劇雖然好看，但我對白夜城和影鎮的歷史都不太熟悉……）",
  ui_story_5037_50372001_50_dialog_content = "（好睏……果然看自己不是很懂的表演，就會忍不住犯睏……）",
  ui_story_5037_50372001_51_dialog_content = "（但是，這又是妮娜認真準備的……）",
  ui_story_5037_50372001_52_option_content = "忍住不睡",
  ui_story_5037_50372001_53_dialog_content = "（不行，不能睡著，要認真看完全程才行！）",
  ui_story_5037_50372001_54_dialog_content = "（這是珍貴的參考資料！）",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>強忍睡意看完了舞台劇</color>",
  ui_story_5037_50372001_56_dialog_content = "原來影鎮的文化發展過程這麼複雜，我現在才知道呢！",
  ui_story_5037_50372001_57_dialog_content = "我也學到了很多知識！",
  ui_story_5037_50372001_58_dialog_content = "雖然有很多聽得一知半解……",
  ui_story_5037_50372001_59_dialog_content = "不用擔心，本小姐已在教材中標註所有重點了。",
  ui_story_5037_50372001_60_dialog_content = "你們可以隨時翻閱複習。",
  ui_story_5037_50372001_61_dialog_content = "真是辛苦妳了，妮娜小姐！",
  ui_story_5037_50372001_62_option_content = "放棄掙扎",
  ui_story_5037_50372001_63_dialog_content = "（我要忍住，我要……呼……）",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>不知過了多久</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName？PlayerName！",
  ui_story_5037_50372001_66_dialog_content = "歌爾蒂小姐，請容我一試。",
  ui_story_5037_50372001_67_dialog_content = "PlayerName，您請醒醒！",
  ui_story_5037_50372001_68_dialog_content = "咦！？",
  ui_story_5037_50372001_69_dialog_content = "PlayerName，你怎麼睡著了？表演已經結束了。",
  ui_story_5037_50372001_70_dialog_content = "什麼！？結束了！？",
  ui_story_5037_50372001_71_dialog_content = "我太專注於為歌爾蒂講解，竟然沒察覺你睡著……",
  ui_story_5037_50372001_72_dialog_content = "辜負大小姐的好意，可是深重的罪過……",
  ui_story_5037_50372001_73_dialog_content = "對……對不起！",
  ui_story_5037_50372001_74_dialog_content = "是我不好……",
  ui_story_5037_50372001_75_dialog_content = "沒關係。",
  ui_story_5037_50372001_76_dialog_content = "雖然你沒能一邊欣賞舞台劇一邊學習知識，這有些可惜。",
  ui_story_5037_50372001_77_dialog_content = "但是，本小姐已在教材中標註了所有重點知識。",
  ui_story_5037_50372001_78_dialog_content = "只要你回去仔細閱讀教材，多少也能學到一些。",
  ui_story_5037_50372001_79_dialog_content = "我會認真看的，不會睡著了！",
  ui_story_5037_50372001_80_dialog_content = "希望你們都能從這次的表演中有所收穫。",
  ui_story_5037_50372001_81_dialog_content = "流行文化的關鍵在於掌握大眾的喜好，所以絕對不能閉目塞聽。",
  ui_story_5037_50372001_82_dialog_content = "我也只能幫你們到這裡了，接下來，還請兩位繼續加油吧。",
  ui_story_5037_50372001_83_dialog_content = "謝謝，妮娜小姐、米洛斯先生！",
  ui_story_5037_50372001_84_dialog_content = "嗯，辛苦二位了！",
  ui_story_5037_50372101_1_dialog_content = "弗勞爾，謝謝你願意來指導我和歌爾蒂——",
  ui_story_5037_50372101_2_dialog_content = "噓——！",
  ui_story_5037_50372101_3_dialog_content = "欸？弗勞爾先生，你趴在門上是在做什麼？",
  ui_story_5037_50372101_4_dialog_content = "PlayerName、歌爾蒂小姐，麻煩你們先稍微安靜一下……",
  ui_story_5037_50372101_5_dialog_content = "……",
  ui_story_5037_50372101_6_dialog_content = "……",
  ui_story_5037_50372101_7_dialog_content = "呼，看來那些人已經走了。",
  ui_story_5037_50372101_8_dialog_content = "難道弗勞爾又被人纏上了嗎？",
  ui_story_5037_50372101_9_dialog_content = "是啊……",
  ui_story_5037_50372101_10_dialog_content = "明明只是在來的路上和幾個幫助過的人打了聲招呼……",
  ui_story_5037_50372101_11_dialog_content = "您好。",
  ui_story_5037_50372101_12_dialog_content = "嗯？這不是弗勞爾嗎？上次你幫了我大忙，真是太感謝了！",
  ui_story_5037_50372101_13_dialog_content = "結果聽到那個人喊了我的名字以後，越來越多的人湊了過來……",
  ui_story_5037_50372101_14_dialog_content = "什麼？弗勞爾哥哥來了？上次真是太謝謝你了——",
  ui_story_5037_50372101_15_dialog_content = "弗勞爾，我是你的粉絲！！！",
  ui_story_5037_50372101_16_dialog_content = "我費了好大勁才從人們的包圍中逃出來，又繞了很遠的路，確定沒有人跟著才來到這裡……",
  ui_story_5037_50372101_17_dialog_content = "有時候太受歡迎也是一種麻煩呢……",
  ui_story_5037_50372101_18_dialog_content = "好羨慕啊，我也想像弗勞爾先生那樣受歡迎！",
  ui_story_5037_50372101_19_dialog_content = "這可是一件非常辛苦的事情。",
  ui_story_5037_50372101_20_dialog_content = "我不怕辛苦！",
  ui_story_5037_50372101_21_dialog_content = "如果能吸引更多人的注意，讓大家看到我的舞蹈、聽到我的歌曲，那就太好了！",
  ui_story_5037_50372101_22_dialog_content = "妳這樣想的話，我也不會再說什麼。",
  ui_story_5037_50372101_23_dialog_content = "只是，我之所以受歡迎，是因為我的特殊體質。",
  ui_story_5037_50372101_24_dialog_content = "這種體質是沒辦法透過教學讓別人學會的……",
  ui_story_5037_50372101_25_dialog_content = "欸？",
  ui_story_5037_50372101_26_dialog_content = "而且，其實我也不清楚到底該怎麼做才能受歡迎。",
  ui_story_5037_50372101_27_dialog_content = "因為特殊體質的問題，我大部分時間的研究反而是關於怎麼變得不引人矚目，甚至被討厭。",
  ui_story_5037_50372101_28_dialog_content = "竟然是這樣嗎……",
  ui_story_5037_50372101_29_dialog_content = "這可怎麼辦才好呢……",
  ui_story_5037_50372101_30_dialog_content = "有了！",
  ui_story_5037_50372101_31_dialog_content = "妳想到什麼了？",
  ui_story_5037_50372101_32_dialog_content = "既然弗勞爾先生對變得不受歡迎的方法有深入的研究，那我們只需要反過來不就好了？",
  ui_story_5037_50372101_33_dialog_content = "妳是想讓弗勞爾把他的方法教給妳，然後妳再反過來用？",
  ui_story_5037_50372101_34_dialog_content = "這樣不受歡迎的方法就能變成受歡迎的方法了？",
  ui_story_5037_50372101_35_dialog_content = "沒錯，不愧是我的製作人，理解得真快！",
  ui_story_5037_50372101_36_dialog_content = "這樣真的可以嗎？",
  ui_story_5037_50372101_37_dialog_content = "不試試看怎麼知道呢？弗勞爾先生，請教教我吧！",
  ui_story_5037_50372101_38_dialog_content = "好吧……你們要學不引人矚目的方法，還是被人討厭的方法？",
  ui_story_5037_50372101_39_dialog_content = "PlayerName，學哪種比較好呢？",
  ui_story_5037_50372101_40_dialog_content = "（如果要反著用的話，越不受人喜歡，反向使用的效果應該越強吧？）",
  ui_story_5037_50372101_41_option_content = "不引人矚目的方法",
  ui_story_5037_50372101_42_dialog_content = "不引人矚目的方法其實非常簡單，只要像別人一樣就好了。",
  ui_story_5037_50372101_43_dialog_content = "與他人沒有區別的行為，隱藏自己獨具的特徵，就可辦到。",
  ui_story_5037_50372101_44_dialog_content = "聽起來好像很容易呢！",
  ui_story_5037_50372101_45_dialog_content = "一般而言，不想引人矚目的人會穿著普通的衣服，低頭走路。",
  ui_story_5037_50372101_46_dialog_content = "有的還會戴帽子遮臉！",
  ui_story_5037_50372101_47_dialog_content = "那麼只要反過來，昂首闊步地走路，並展現我的舞蹈和歌聲，應該就可以了？",
  ui_story_5037_50372101_48_dialog_content = "雖然聽起來有點怪，但是歌爾蒂的舞蹈很好看，歌聲也動聽……",
  ui_story_5037_50372101_49_dialog_content = "應該沒問題吧！",
  ui_story_5037_50372101_50_option_content = "被人討厭的方法",
  ui_story_5037_50372101_51_dialog_content = "想要被人討厭其實有點難度。",
  ui_story_5037_50372101_52_dialog_content = "我嘗試過幾種方法，比如鬼鬼祟祟地走路、穿得破破爛爛、把臉弄髒等。",
  ui_story_5037_50372101_53_dialog_content = "效果還不錯，只不過有好幾次被當成了小偷……",
  ui_story_5037_50372101_54_dialog_content = "不過由於體質問題，一旦被人發現我是弗勞爾，再怎麼假裝都沒用了。",
  ui_story_5037_50372101_55_dialog_content = "我大概明白了。",
  ui_story_5037_50372101_56_dialog_content = "反過來的話，只要姿態端莊、服裝整潔，保持儀表堂堂的樣子就可以了吧？",
  ui_story_5037_50372101_57_dialog_content = "還有隨時保持樂觀，露出偶像歌手的招牌微笑！",
  ui_story_5037_50372101_58_dialog_content = "應該是這樣沒錯！",
  ui_story_5037_50372101_59_dialog_content = "不管哪種方法，「儀態」都是非常重要的部分。",
  ui_story_5037_50372101_60_dialog_content = "歌爾蒂小姐很擅長舞蹈，應該有同樣的體會吧？",
  ui_story_5037_50372101_61_dialog_content = "確實呢！舞蹈很重視「儀態」，挺直腰板和彎腰駝背，跳出來的舞是完全不同的！",
  ui_story_5037_50372101_62_dialog_content = "總之，謝謝你，弗勞爾先生！",
  ui_story_5037_50372101_63_dialog_content = "不用客氣，如果還有什麼可以幫忙的地方，請儘管告訴我吧。",
  ui_story_5037_50372101_64_dialog_content = "弗勞爾之所以這麼受歡迎，樂於助人也是原因之一吧。",
  ui_story_5037_50372101_65_dialog_content = "是……是這樣嗎？",
  ui_story_5037_50372101_66_dialog_content = "可是，我沒辦法放著需要幫忙的人不管……",
  ui_story_5037_50372101_67_dialog_content = "弗勞爾這樣就很好，不需要改變！",
  ui_story_5037_50372101_68_dialog_content = "嗯，我知道了。",
  ui_story_5037_50372101_69_dialog_content = "謝謝你，PlayerName。",
  ui_story_5037_50372101_70_dialog_content = "幫助別人、行俠仗義，當然會大受歡迎啦！",
  ui_story_5037_50372101_71_dialog_content = "PlayerName，我們也快去外面嘗試一下新學到的技巧吧！",
  ui_story_5037_50372101_72_dialog_content = "現在！？",
  ui_story_5037_50372101_73_dialog_content = "心動不如馬上行動，我們現在就出去——",
  ui_story_5037_50372101_74_dialog_content = "等一下，歌爾蒂小姐，先別開門！",
  ui_story_5037_50372101_75_dialog_content = "欸？",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>吱嘎——</color>",
  ui_story_5037_50372101_77_dialog_content = "（門外有好多人！？）",
  ui_story_5037_50372101_78_dialog_content = "弗勞爾先生在這裡？",
  ui_story_5037_50372101_79_dialog_content = "我剛才好像聽見有人叫了弗勞爾哥哥的名字！",
  ui_story_5037_50372101_80_dialog_content = "弗勞爾親~！你為什麼要跑！",
  ui_story_5037_50372101_81_dialog_content = "各位，請、請冷靜一點……",
  ui_story_5037_50372101_82_dialog_content = "請接受我們的讚美！！！",
  ui_story_5037_50372101_83_dialog_content = "好強的吸引力！",
  ui_story_5037_50372101_84_dialog_content = "看來太受歡迎確實是一種麻煩呢……",
  ui_story_5037_50372201_1_dialog_content = "「天才，總是孤獨的。」",
  ui_story_5037_50372201_2_dialog_content = "「他們以孤獨為食糧，在孤獨中探求，以孤獨為土壤開出藝術之花。」",
  ui_story_5037_50372201_3_dialog_content = "「正因如此，孤獨並非敵人，而是同伴，是摯友！」",
  ui_story_5037_50372201_4_dialog_content = "好厲害！",
  ui_story_5037_50372201_5_dialog_content = "這是舞台劇《夜訪影帝》中的台詞吧？",
  ui_story_5037_50372201_6_dialog_content = "謝謝，美麗的小姐，懂得欣賞在下的表演，證明妳有極高的藝術素養。",
  ui_story_5037_50372201_7_dialog_content = "等等，卡戎，能不能請你解釋一下——",
  ui_story_5037_50372201_8_dialog_content = "明明我們只離開了十分鐘，為什麼你能在訓練室裡搭出空之山谷的布景！？",
  ui_story_5037_50372201_9_dialog_content = "不要大驚小怪，我的朋友，啟光的工兵可是艾斯特拉最優秀的。",
  ui_story_5037_50372201_10_dialog_content = "工兵不是這樣用的吧……",
  ui_story_5037_50372201_11_dialog_content = "這布景可真厲害，我剛才走進訓練室時，還以為自己一下子來到空之山谷了呢！",
  ui_story_5037_50372201_12_dialog_content = "朋友，請你相信，在下所做的一切，皆是為了幫助這位小姐學習表演技巧。",
  ui_story_5037_50372201_13_dialog_content = "真的？",
  ui_story_5037_50372201_14_dialog_content = "正所謂實踐出真知，只有親自嘗試，才能對表演有所體悟。",
  ui_story_5037_50372201_15_dialog_content = "在下已親自準備好布景和劇本，希望能讓兩位體驗表演的美妙之處。",
  ui_story_5037_50372201_16_dialog_content = "太好了！正好偶像活動偶爾需要演出舞台劇。",
  ui_story_5037_50372201_17_dialog_content = "如果能得到專業演員的指導，我的表演能力一定會有很大的進步！",
  ui_story_5037_50372201_18_dialog_content = "那麼，我們現在就開始吧。",
  ui_story_5037_50372201_19_dialog_content = "請看，這是在下準備的劇本。",
  ui_story_5037_50372201_20_dialog_content = "這是……",
  ui_story_5037_50372201_21_dialog_content = "雖然台詞略有變化，但這不是《艾達與巨像》嗎？",
  ui_story_5037_50372201_22_dialog_content = "沒錯，這一次，在下特地選擇了由童話故事改編而成的劇本。",
  ui_story_5037_50372201_23_dialog_content = "童話故事劇情較為簡單，方便理解，不會對表演初心者太困難。",
  ui_story_5037_50372201_24_dialog_content = "你想得還真周到！",
  ui_story_5037_50372201_25_dialog_content = "那是自然。畢竟，在下也是從一無所知的表演新人，成長為如今的天才演員的！",
  ui_story_5037_50372201_26_dialog_content = "PlayerName，我們來分配角色吧？",
  ui_story_5037_50372201_27_dialog_content = "好。我對巨像比較熟悉，可以由我來扮演風行者號。",
  ui_story_5037_50372201_28_dialog_content = "那我就來扮演艾達吧！",
  ui_story_5037_50372201_29_dialog_content = "這個角色好奇心強，還很活潑，是個可愛的角色！",
  ui_story_5037_50372201_30_dialog_content = "旁白和其他角色就由在下來擔任吧。",
  ui_story_5037_50372201_31_dialog_content = "既然已經安排完畢，那就開始表演吧。",
  ui_story_5037_50372201_32_dialog_content = "「在寧靜的空之山谷中，停泊著一艘名為『風行者號』的巨像。」",
  ui_story_5037_50372201_33_dialog_content = "「它十分嚮往天空，卻因為沒有導航員，只能停留在地上。」",
  ui_story_5037_50372201_34_dialog_content = "「巨像就是為了天空而生的！」",
  ui_story_5037_50372201_35_dialog_content = "「雖然也有陸地型號，還有適用於海洋的型號，但是天空才是巨像的歸宿！」",
  ui_story_5037_50372201_36_dialog_content = "「真好啊……有導航員究竟是什麼樣的感覺啊……」",
  ui_story_5037_50372201_37_dialog_content = "「有導航員，應該就是有了朋友的感覺吧。」",
  ui_story_5037_50372201_38_dialog_content = "「嚇！是誰！？為什麼能和我對話……」",
  ui_story_5037_50372201_39_dialog_content = "「難道是幽靈？畢竟不會有空裔靠近廢舊巨像的停靠場……」",
  ui_story_5037_50372201_40_dialog_content = "「可在你面前的就是一名空裔！」",
  ui_story_5037_50372201_41_dialog_content = "「艾達走近風行者號，觀察它長滿小花的頭，伸手摸了摸。」",
  ui_story_5037_50372201_42_dialog_content = "（等等，摸頭？我的劇本裡沒有這段啊……）",
  ui_story_5037_50372201_43_dialog_content = "（怎麼辦，要繼續演嗎？）",
  ui_story_5037_50372201_44_option_content = "繼續表演",
  ui_story_5037_50372201_45_dialog_content = "「我摸——」",
  ui_story_5037_50372201_46_dialog_content = "「喂喂喂，空裔就可以偷聽人家的悄悄話，見面第一眼亂摸人家的頭嗎？」",
  ui_story_5037_50372201_47_dialog_content = "「我漂亮的頭可不是誰都能碰的。」",
  ui_story_5037_50372201_48_dialog_content = "「但是很漂亮啊，而且還開著可愛的小花！」",
  ui_story_5037_50372201_48X1_dialog_content = "卡——！",
  ui_story_5037_50372201_49_dialog_content = "接得漂亮，PlayerName！",
  ui_story_5037_50372201_50_dialog_content = "欸？",
  ui_story_5037_50372201_51_option_content = "提出疑問",
  ui_story_5037_50372201_52_dialog_content = "等一下，劇本裡沒有這段啊？",
  ui_story_5037_50372201_52X1_dialog_content = "卡——！",
  ui_story_5037_50372201_53_dialog_content = "劇本裡確實沒有這段。",
  ui_story_5037_50372201_54_dialog_content = "我的劇本裡也沒有……",
  ui_story_5037_50372201_55_dialog_content = "到底怎麼回事，卡戎？",
  ui_story_5037_50372201_56_dialog_content = "表演雖然有劇本，但表演的終究是人。",
  ui_story_5037_50372201_57_dialog_content = "表演過程總是會伴隨各種各樣的突發情況，不會全盤按照劇本演出。",
  ui_story_5037_50372201_58_dialog_content = "因此，優秀的演員就要具備隨機應變的本領！",
  ui_story_5037_50372201_59_dialog_content = "原來如此！",
  ui_story_5037_50372201_60_dialog_content = "確實！我之前看過的舞台劇表演中，有時候也會出現台詞與劇本不同的情況。",
  ui_story_5037_50372201_61_dialog_content = "但是表演者們都表現得很自然，讓人根本感覺不出來！",
  ui_story_5037_50372201_62_dialog_content = "隨機應變也是演技的一部分。",
  ui_story_5037_50372201_63_dialog_content = "理解角色，成為角色，只有這樣，才能表現出角色最自然的模樣。",
  ui_story_5037_50372201_64_dialog_content = "嗯，我明白了！",
  ui_story_5037_50372201_65_dialog_content = "我會照著這個方向繼續努力，磨練我的演技！",
  ui_story_5037_50379901_1_dialog_content = "奇怪……",
  ui_story_5037_50379901_2_dialog_content = "太奇怪了！",
  ui_story_5037_50379901_3_dialog_content = "這幾天薇絲和卡蓮為什麼一直在故意躲著我。",
  ui_story_5037_50379901_4_dialog_content = "是我什麼時候不小心得罪過她們兩個人嗎？",
  ui_story_5037_50379901_5_dialog_content = "難道是上一次……",
  ui_story_5037_50379901_6_option_content = "在艦橋",
  ui_story_5037_50379901_7_dialog_content = "嗯~久違地換上這身衣服，感覺還不錯呢。",
  ui_story_5037_50379901_8_dialog_content = "PlayerName覺得呢？這身衣服和我平時穿的啟光制服，哪件好看呀？",
  ui_story_5037_50379901_9_dialog_content = "嗯？不知道。",
  ui_story_5037_50379901_10_dialog_content = "……",
  ui_story_5037_50379901_11_dialog_content = "我當時就應該說都好看的啊！",
  ui_story_5037_50379901_12_option_content = "在休息室",
  ui_story_5037_50379901_13_dialog_content = "PlayerName？！",
  ui_story_5037_50379901_14_dialog_content = "快轉過身去！你怎麼在這裡？",
  ui_story_5037_50379901_15_dialog_content = "我、我半夜起來想來找點飲料喝。",
  ui_story_5037_50379901_16_dialog_content = "你剛才都看見什麼了？",
  ui_story_5037_50379901_17_dialog_content = "啊？我看見卡蓮穿著睡衣在開心地照鏡子？",
  ui_story_5037_50379901_18_dialog_content = "你看錯了！",
  ui_story_5037_50379901_19_dialog_content = "我當時就應該說我什麼都沒看見的啊！",
  ui_story_5037_50379901_20_dialog_content = "可是這也不至於兩個人都不理我吧……",
  ui_story_5037_50379901_21_dialog_content = "啊啊啊，到底是因為哪件事啊？越想腦子越亂！",
  ui_story_5037_50379901_22_dialog_content = "馬上就要跨年了，不能把這種尷尬的氛圍延續到新的一年。",
  ui_story_5037_50379901_23_dialog_content = "不然，不然我去找她們問清楚好了？",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>咚咚咚！</color>",
  ui_story_5037_50379901_25_dialog_content = "薇絲、卡蓮，妳們在嗎？",
  ui_story_5037_50379901_26_dialog_content = "<size=33>欸？是PlayerName？！他怎麼在這個節骨眼上來了？</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>……快！快點！</size>",
  ui_story_5037_50379901_28_dialog_content = "PlayerName，你來得正好。",
  ui_story_5037_50379901_29_dialog_content = "我和卡蓮正準備去找你呢，請進吧。",
  ui_story_5037_50379901_30_dialog_content = "前幾天妳們還躲著我不跟我說話，怎麼現在忽然就轉變了態度？",
  ui_story_5037_50379901_31_dialog_content = "這個嘛，你進來就知道囉~",
  ui_story_5037_50379901_32_dialog_content = "那個……屋子裡為什麼不開燈啊？黑乎乎地怪嚇人的。",
  ui_story_5037_50379901_33_dialog_content = "不開燈，才有效果啊。",
  ui_story_5037_50379901_34_dialog_content = "效果？什麼效果？！",
  ui_story_5037_50379901_35_dialog_content = "仔細看前面，要開始了。",
  ui_story_5037_50379901_36_dialog_content = "欸？",
  ui_story_5037_50379901_38_dialog_content = "哎呀，時間怎麼過得這麼快？",
  ui_story_5037_50379901_39_dialog_content = "不知不覺這一年又要過去了。",
  ui_story_5037_50379901_40_dialog_content = "能覺得時間飛逝，其實是件好事。",
  ui_story_5037_50379901_41_dialog_content = "這恰恰說明我們這一年過得非常充實。",
  ui_story_5037_50379901_42_dialog_content = "哈哈，自從和PlayerName開始冒險之後，我們的每一天都非常充實呢！",
  ui_story_5037_50379901_43_dialog_content = "是嗎？那我考考妳。",
  ui_story_5037_50379901_44_dialog_content = "妳還記得我們這一年都去過哪裡嗎？",
  ui_story_5037_50379901_45_dialog_content = "哼哼，當然記得啦！",
  ui_story_5037_50379901_46_dialog_content = "去年的這個時候，我們穿越了重重風暴抵達北境。",
  ui_story_5037_50379901_47_dialog_content = "那是我第一次親眼見到極光下晶瑩剔透的冬宮！",
  ui_story_5037_50379901_48_dialog_content = "也是第一次知道北境的炸肉丸蘸草莓醬竟然那麼美味！",
  ui_story_5037_50379901_49_dialog_content = "PlayerName一直待在鏡湖旁邊，說是看到了女王的過去……",
  ui_story_5037_50379901_50_dialog_content = "究竟是怎樣的過去？我也很想親眼看看。",
  ui_story_5037_50379901_51_dialog_content = "接著我們一起在裝飾華麗的燈螢木下倒計時，迎來了新年！",
  ui_story_5037_50379901_52_dialog_content = "真是懷念呀。",
  ui_story_5037_50379901_53_dialog_content = "懷念炸肉丸嗎？",
  ui_story_5037_50379901_54_dialog_content = "呃嘿嘿嘿……",
  ui_story_5037_50379901_55_dialog_content = "從北境返程的路上，我們不小心跌入了一座位於地下的「遠古城市」。",
  ui_story_5037_50379901_56_dialog_content = "在那裡，我們被迫換上了遠古服飾以躲避機器人的攻擊。",
  ui_story_5037_50379901_57_dialog_content = "哈哈，我到現在都還記得PlayerName穿裙子的樣子！",
  ui_story_5037_50379901_58_dialog_content = "後來我們遇到了同樣被困在遠古城市裡的朋友們。",
  ui_story_5037_50379901_59_dialog_content = "起先大家因為觀點的不同而產生了爭執。",
  ui_story_5037_50379901_60_dialog_content = "但後來大家齊心協力，說服了住在遠古城市的兩位少女……",
  ui_story_5037_50379901_61_dialog_content = "在地下城瀕臨毀滅之前，一起逃出生天。",
  ui_story_5037_50379901_62_dialog_content = "PlayerName回來之後還收到過來自那座城市的通訊。",
  ui_story_5037_50379901_63_dialog_content = "未來的某一天，也許我們還能有機會去看看那座城市。",
  ui_story_5037_50379901_64_dialog_content = "嗯……後來嘛，我們也沒閑著！",
  ui_story_5037_50379901_65_dialog_content = "手 · 折 · 紅 · 花 · 贈 · 伊 · 人——",
  ui_story_5037_50379901_66_dialog_content = "眉 · 前 · 花 · 落 · 玉 · 上 · 雪。",
  ui_story_5037_50379901_67_dialog_content = "我們因為一個委託，來到了江富城，認識了這座城市的巫女。",
  ui_story_5037_50379901_68_dialog_content = "那個時候正巧是「春日祭」，整個城市都被櫻花染成了粉紅色。",
  ui_story_5037_50379901_69_dialog_content = "可是沒想到在那樣的一片祥和之中……",
  ui_story_5037_50379901_70_dialog_content = "竟然也暗藏殺機。",
  ui_story_5037_50379901_71_dialog_content = "一把仇火燃盡了舊日的繁華。",
  ui_story_5037_50379901_72_dialog_content = "留給那座城市的……",
  ui_story_5037_50379901_73_dialog_content = "又會是怎樣的生死離別呢？",
  ui_story_5037_50379901_74_dialog_content = "我又沒去過，這個問題我可回答不了。",
  ui_story_5037_50379901_75_dialog_content = "那個時候妳不是回白夜城了嘛……",
  ui_story_5037_50379901_76_dialog_content = "下次！下次我們一定記得叫妳！",
  ui_story_5037_50379901_77_dialog_content = "欸，不對呀？後來妳邀請PlayerName去白夜城看演出，不是也沒叫我嗎？",
  ui_story_5037_50379901_78_dialog_content = "確切地說是為了找失蹤的葛莉特。",
  ui_story_5037_50379901_79_dialog_content = "我們根據線索來到了一座「真實之館」。",
  ui_story_5037_50379901_80_dialog_content = "說是真實，但裡面都是些像假人一樣沒有理智的人。",
  ui_story_5037_50379901_81_dialog_content = "相信我……",
  ui_story_5037_50379901_82_dialog_content = "妳一定會慶幸自己沒看過那場演出。",
  ui_story_5037_50379901_83_dialog_content = "哼？妳這樣說我只會愈來愈好奇啦！",
  ui_story_5037_50379901_84_dialog_content = "話說回來，我們是不是漏掉了什麼？",
  ui_story_5037_50379901_85_dialog_content = "妳是說PlayerName去紅油沙漠的那次？妳不是也跟著去了嗎？",
  ui_story_5037_50379901_86_dialog_content = "啊，對……熾焰拉力賽！那時我還以為PlayerName被醒山綁架了。",
  ui_story_5037_50379901_87_dialog_content = "不過我也是在拉力賽的最後一刻才趕到的。",
  ui_story_5037_50379901_88_dialog_content = "至於前面PlayerName是怎麼坐在副駕駛上看風景的……",
  ui_story_5037_50379901_89_dialog_content = "又是怎麼聽大姐姐講過去的故事的……",
  ui_story_5037_50379901_90_dialog_content = "那些細節我就不知道了。",
  ui_story_5037_50379901_91_dialog_content = "我只知道我竟然開始覺得紅油燒烤好吃了！",
  ui_story_5037_50379901_92_dialog_content = "是嗎？看來妳距離頂級美食家又邁進了一步。",
  ui_story_5037_50379901_93_dialog_content = "卡蓮，連妳也這麼覺得嗎？",
  ui_story_5037_50379901_94_dialog_content = "我就知道我在煮飯這件事上很有天賦！",
  ui_story_5037_50379901_95_dialog_content = "PlayerName就等著吃我研發的新菜品吧~",
  ui_story_5037_50379901_96_dialog_content = "但我聽說PlayerName趁我們不在的時候，請了專業的管家過來。",
  ui_story_5037_50379901_97_dialog_content = "在那段時間裡……",
  ui_story_5037_50379901_98_dialog_content = "PlayerName恐怕沒有少吃山珍海味吧。",
  ui_story_5037_50379901_99_dialog_content = "一開始我還擔心，沒有我們陪在PlayerName身邊他該怎麼辦。",
  ui_story_5037_50379901_100_dialog_content = "現在看來，PlayerName完全可以自食其力嘛。",
  ui_story_5037_50379901_101_dialog_content = "他已經可以作為空庭的主人招待來訪者……",
  ui_story_5037_50379901_102_dialog_content = "還把空庭管理得井井有條！",
  ui_story_5037_50379901_103_dialog_content = "PlayerName的管理能力的確得到了長足的進步。",
  ui_story_5037_50379901_104_dialog_content = "但依我看，他還是需要有人能陪在身邊。",
  ui_story_5037_50379901_105_dialog_content = "要不然被人綁架走了，他都還會給別人數錢。",
  ui_story_5037_50379901_106_dialog_content = "幸好PlayerName還算幸運，只是遇到了一群神奇動物專家。",
  ui_story_5037_50379901_107_dialog_content = "至於中間又發生了什麼嘛……",
  ui_story_5037_50379901_108_dialog_content = "我們只能透過《神奇動物大冒險》這本書來瞭解了。",
  ui_story_5037_50379901_109_dialog_content = "那些事我倒是聽菲雅說過好多次。",
  ui_story_5037_50379901_110_dialog_content = "欸？什麼時候？",
  ui_story_5037_50379901_111_dialog_content = "我們一起去好泊城的時候，不是也遇到了菲雅？",
  ui_story_5037_50379901_112_dialog_content = "啊~是那個時候呀。",
  ui_story_5037_50379901_113_dialog_content = "那時我們一起參加了綠榴石號上舉辦的嘉年華，玩得很開心！",
  ui_story_5037_50379901_114_dialog_content = "可是我們誰都沒有想到……",
  ui_story_5037_50379901_115_dialog_content = "歡樂的嘉年華背後竟然隱藏著城主艾維斯策劃已久的陰謀。",
  ui_story_5037_50379901_116_dialog_content = "雖然後來我們明白了艾維斯的苦衷。",
  ui_story_5037_50379901_117_dialog_content = "但作為一城之主，他實在是不該做出那麼莽撞的行動。",
  ui_story_5037_50379901_118_dialog_content = "而最後，艾維斯為了好泊城的子民而犧牲自己，化解了災難。",
  ui_story_5037_50379901_119_dialog_content = "這讓我意識到，也許每個人都無法用絕對的好或是絕對的壞去判斷。",
  ui_story_5037_50379901_120_dialog_content = "不知道傑諾有沒有找到可以讓艾維斯甦醒的辦法。",
  ui_story_5037_50379901_121_dialog_content = "若他甦醒，我一定會把他親自帶回白夜城審判。",
  ui_story_5037_50379901_122_dialog_content = "……呃哈哈。",
  ui_story_5037_50379901_123_dialog_content = "從好泊城回來後，PlayerName遇到了正在追捕連環殺人犯的渡。",
  ui_story_5037_50379901_124_dialog_content = "他們跟隨線索去到一座被稱作「樂園」的小鎮，尤佛里亞。",
  ui_story_5037_50379901_125_dialog_content = "雖然被人們稱作是「樂園」，但這些年尤佛里亞淪為幫派亂鬥的迷霧之城。",
