  ui_story_5037_50379901_128_dialog_content = "相信不久以後，尤佛里亞可以重新成為人們的「樂園」。",
  ui_story_5037_50379901_129_dialog_content = "在那之後過了沒多久……",
  ui_story_5037_50379901_130_dialog_content = "我和PlayerName去新開業的「安德森尖叫屋」湊熱鬧。",
  ui_story_5037_50379901_131_dialog_content = "在機緣巧合之下，我們參與了一部探祕錄影片的拍攝。",
  ui_story_5037_50379901_132_dialog_content = "本來只是想來遊玩體驗，沒想到真的讓我們遇到了令人毛骨悚然的靈異事件？",
  ui_story_5037_50379901_133_dialog_content = "尖叫屋中爆發出一陣陣真情實感的尖叫！",
  ui_story_5037_50379901_134_dialog_content = "我最喜歡的恐怖片導演……竟然一直在利用暗鬼製作血腥的拍攝現場！",
  ui_story_5037_50379901_135_dialog_content = "真是慶幸那時候我有事沒去。",
  ui_story_5037_50379901_136_dialog_content = "欸，難道天不怕地不怕的卡蓮還會害怕去尖叫屋嗎？",
  ui_story_5037_50379901_137_dialog_content = "我只是覺得如果我去了，恐怕會把女鬼嚇死。",
  ui_story_5037_50379901_138_dialog_content = "哈哈，妳？妳哪裡嚇人啦？",
