  ui_story_5037_50379901_144_dialog_content = "原來如此……",
  ui_story_5037_50379901_145_dialog_content = "咳咳，我們還是言歸正傳吧！",
  ui_story_5037_50379901_146_dialog_content = "PlayerName，這一年馬上就要結束啦。",
  ui_story_5037_50379901_147_dialog_content = "我們希望可以用這種方式，幫PlayerName記錄這一整年的經歷。",
