  ui_story_5037_50379901_149_dialog_content = "帶上我們一起出發！",
  ui_story_5037_50379901_151_dialog_content = "妳們……？",
  ui_story_5037_50379901_152_dialog_content = "所以妳們這幾天神神祕祕的，就是在準備這個短片嗎？",
  ui_story_5037_50379901_153_dialog_content = "嘿嘿~我們想要給你一個驚喜嘛！",
